window.__D("text/maamarei-admur-hazaken/c010",{"p":[[2100990391,"אמת דלגבי הנבראים נחשב הביטול של המלאכים עליונים לחשיבות גדולה שנמצא בהן בחי' הביטול של השתחואה שא\"א להיות נמצא יותר בערך הנברא, אכן לגבי הנאצלים באצי' דאיהו<sup data-n=\"5632\">10</sup> וגרמוהי חד ממש ואפי' בחי' ביטול לא יתכן לכנות בהם, במה נחשב, ואדרבה גריעותא הוא לגביהם ולא זכ\"ו בעיניו, וכנ\"ל מפני שהטוב דבריאה נחשב לסיגים ופסולת לגבי אצי' כו', וזהו סדר הברורין שמלמטה למעלה בקדושה לעומת ונגד סדר הבירורין שמלמעלה למטה ברבוי ההשתלשלות ירידת השפע עליונה וברור אחר ברור הטוב ממנה עד שמתהוה תכלית הגסות הרע דעשי' ממש שיש בהם ג\"כ כמה מדריגות שונים כענין שארז\"ל בשטן כו' כנ\"ל (והכל א' רק זה בירור אוכל מתוך פסולת ואח\"כ אוכל מתוך האוכל בעלי' עד אין קץ כמ\"ש ואכלתם<sup data-n=\"5633\">11</sup> אכול וגו' כמ\"ש במ\"א וזה בירור פסולת מתוך האוכל כו'.\n<b>וכענין</b> ששמע מבן מורו ע\"ה ר' אברהם ז\"ל שיש<sup data-n=\"5634\">12</sup> ב' בחי' ברורים הנ\"ל בגשמיות בהתוך הכסף בכור, יש שמצרף לכסף המעורב בנחושת בכור לברר ולהוציא הפסולת הנחושת מן הכסף נקי שבפעם ראשון בהשלכת חתיכת הכסף יוצא הפסולת הגסה הנחושת הגסה ממש ועדיין יש בהכסף תערובת פסולת נחושת דקה שאינו צלול הכסף עדיין מחמת התערובת הנ\"ל, לזאת משימין הכסף הברור ההוא עוד פעם שני בכור להוציא ולהפריד ממנו אפי' הפסולת הדקה ההיא, שאז מצוחצח יותר הכסף וכן פעם שלישי ורביעי שבכל פעם שמצרף לכסף יותר בכור מפריד הדקה מן הדקה הפסולת שבו יותר עד שנשאר הכסף נקי בתכלית הזכוך בלי תערובת פסולת כלל אף לא מן הדקה שבדקה כלל, ויש סדר צרוף הכסף בהפוך לברר הכסף הטוב מן הפסולת הנחושת שתחלה בפ\"א כשהשליך בכור חתיכת הנחושת שבו תערובת הכסף הוציא מעט ממנו טוב ומובחר ממנו ועדיין יש בו תערובת כסף גרוע ובפעם שני ושלישי מתברר יותר אף הכסף הגרוע ממנו דהיינו שהכסף שמתברר ממנו בפעם שני גרוע מן הראשון וכן השלישי גרוע מן השני עד שנשאר הפסולת הנחושת בתכלית ההגשמה בלי תערובת כסף כלל אף לא מן הגרוע שבגרוע כלל, ככה ממש עד\"ז למעלה יש ב' בחי' בסדר הבירורין מלמעלה למטה ומלמטה למעלה וכולא חד כו' וכנ\"ל וכמשנ\"ת במ\"א בארוכה ע\"ש.\n<b>והנה</b> עיקר המברר כל הבירורין הוא בחי' ש' מ\"ה בחי' ומדרגת מרע\"ה שנמשך מח\"ע כמ\"ש וירא<sup data-n=\"5635\">13</sup> ראשית לו כי בחכמה<sup data-n=\"5636\">14</sup> דייקא אתברירו והוא בחי' טעמי' שלמעלה משרש השבירה שהי' בנקודי' כו', ופי' כי הטעמים שבחכמה דוקא הוא מצד השראת העונג עליון בפנימיות החכמה דוקא כמו עד\"מ למטה כשמשכיל האדם איזה השכלה חדשה פתאום מרגיש בה טוב טעם ודעת ושעשועי' גדולים",[["5632","10","<b>דאיהו וגרמוהי חד</b>: ת\"ז בהקדמה (יז, ב)."],["5633","11","<b>ואכלתם אכול</b>: יואל ב, כו."],["5634","12","<b>שיש ב' בחי' ברורים</b>: ראה ג\"כ מאמרי הנחות תקע\"ז ע' קז."],["5635","13","<b>וירא ראשית לו</b>: ברכה לג, כא."],["5636","14","<b>בחכמה דייקא אתברירו</b>: ראה זהר (היכלות) פקודי רנד, סע\"ב."]]],[2100990392,"בהרגש' מתיקות הטעם וסברא ההיא, שהרגשת הטעם והמתיקות הוא בפנימיות השכל ההוא דייקא, ולא בחיצוניותו כשמתפשט בדבור לזולתו אל התלמיד שאין התלמיד מרגיש טוב טעם של המושכל רק כפי שמשפיע לו הרב יקבל הדבר ממשי של השכל חיצוני עצמו ולא טעמו הפנימי המורגש לבעל המשפיע והוא ערבה לה, וכענין שנראה בפלפול האמוראים בתלמוד בדברי התנאים לבא לעומק המושג הפנימי שלהן שאמרו ז\"ל מ\"ט<sup data-n=\"5637\">15</sup> דר' מאיר כדומה פי' מאי טעמא הפנימי של סברת ר' מאיר כו' וכיוצא בזה עד\"מ למעלה בחי' השראת הטעם של העונג העליון הוא בפנימיות החכמה עליונה דוקא ולכך ע\"י הטעמים שבחכמה אתברירו כל הברורין דב\"ן כו' וד\"ל.\n<b>וזהו</b> תורה צוה לנו משה מורשה וגו', ויובן זה בהקדים לבאר ענין הירושה שנאמר בתורה לתת<sup data-n=\"5638\">16</sup> לכם את ארץ הכנעני וגו', לרשת<sup data-n=\"5639\">17</sup> אותם וגו', למען הביא אתכם על האדמה אשר אתה בא שמה לרשתה כו'. והיינו כי הז' אומות שרשן מז' מלכים דאדום דתהו שמתו ועשו הוא אבי אדום, לכך יצא ראשון בהשתלשלות אדמוני כולו כאדרת שער כו', כי קליפה<sup data-n=\"5640\">18</sup> קדמה לפרי, וכנראה בשלי' הולד החופה עליו כו' שהפסולת<sup data-n=\"5641\">19</sup> יוצא ראשון לכן עשו הוא אבי אדום, שרש הז' מלכין דתהו שלפני מלך מלך דישראל שרש עולם התיקון דאצי' שקדמה עולם התהו לעולם התיקון בסדר ההשתלשלות. אך מצד תערובת הסיגים שבמלכים דתה\"ו נשברו ומתו ונפלו למטה מעולם התיקון להיותם מתבררים ע\"י ש' מ\"ה החדש כו', וכל הלבושים דתיקון המה בירושה מהמתבררים דמלכים שמתו [וכ\"ז בהשתלשלות יצא עשו ראשון, אבל במחשבה<sup data-n=\"5642\">20</sup> קדומה יעקב הוא הבכור האמיתי כדפרש\"י<sup data-n=\"5643\">21</sup> במשל השפופרת שמה שנכנס ראשון יצא אחרון כו', וכמ\"ש במ\"א ע\"פ יעקב יעקב ומת\"ג בנתיים פסיק טעמי' בגווייהו כו' ע\"ש].\n<b>וזהו</b> ע\"י מעשה המצות שלמטה שמלובשים בנוגה דבי\"ע שמבררין הניצוצין דתהו שעי\"ז ממשיכים בחי' לבושים ומקיפים למל' דאצי' בסוד ירושה כנ\"ל וכמ\"ש בכ' אריז\"ל שממעשה<sup data-n=\"5644\">22</sup> המצות נעשים לבושים להנשמות בג\"ע עליון ותחתון שנהנין מזיו השכינה דרך הלבושים, אך זהו מבחי' הברורים דבי\"ע שע\"י מעשה התחתונים שממשיכים לבושים לנבראים להנות מזיו השכינה לבד אך לא זו עיקר המכוון כ\"א ע\"י אתדל\"ת זה גורמים אתערותא דלעילא להיות מתבררים הברורים דב\"ן דאצי'",[["5637","15","<b>מ\"ט דר' מאיר</b>: ראה ב\"ק ה, ב. נדה יח, ב."],["5638","16","<b>לתת לכם את ארץ הכנעני</b>: ראה בהר כה, לח."],["5639","17","<b>לרשת אותם</b>: פר' ראה יב, כט."],["5640","18","<b>קליפה קדמה לפרי</b>: נסמן לעיל ע' תשלב. תשמה."],["5641","19","<b>שהפסולת יוצא ראשון</b>: נסמן לעיל ע' תשלב."],["5642","20","<b>במחשבה קדומה יעקב הוא הבכור</b>: ראה לעיל ע' תשמה."],["5643","21","<b>כדפרש\"י במשל השפופרת</b>: ראה ב\"ר פס\"ח, ח. הובא ברש\"י תולדות כה, כו. סה\"מ תקס\"ה ח\"ב ע' תשי. מאמרי אדה\"א בראשית ע' קעט. וש\"נ. תו\"ח תולדות קסא, א. קפט, ב."],["5644","22","<b>שממעשה המצות נעשים לבושים</b>: נסמן לעיל ע' תקיג."]]],[2100990393,"להמשיך מקיפים ולבושים ממקורן ש' ס\"ג למל' דאצי' עצמה, וז\"ס שכר מצוה מצוה שלמעלה מכל חיי עוה\"ב שממשכ' הלבוש מלכות ממש מקור הזיו שבג\"ע כו' (וכנ\"ל שיש כמה מדרגות בסדר הברורין מלמטה למעלה כו', לכן ע\"י הברורים שלמטה נמשכו הלבושים לנשמות וכמ\"כ למעלה מעלה בהברורים עליונים דאצי' יורשים הלבושים מהן להיותן לבושים לנאצלים ממש כו' וד\"ל).\n<b>וזהו</b> יפה שעה א' בתשובה ומע\"ט מכל חיי עוה\"ב כו', וזהו תורה צוה לנו משה מורש\"ה וגו', פי' כל התורה כולה הוא הכל בכדי לברר ברורים דתהו לאהפכא מחשוכא לנהורא ע\"י מעשה המצות, וזהו תורת מש\"ה שאמר ונחנו מ\"ה המברר כל הברורים ומהם נעשו הלבושים לכבוד מל' ית' בסוד ירושה כנ\"ל, וזהו תורה צוה לנו משה דוקא, מורש\"ה דוקא, קהלת י' עקב, המה המתבררים שנתלקטו הניצוצין המפוזרים והנדחים כולם כאחד בקדושה בבחי' יעק\"ב, י' עקב, י' חכמה המשפילי לברר בבחי' עקביים, כי יעקב<sup data-n=\"5645\">23</sup> הוא בריח התיכון [ומשה<sup data-n=\"5646\">24</sup> מלגיו יעקב מלבר וכולא חד כנודע] המבריח כו' וד\"ל.\n<b>וזהו</b> וכבוד הד\"ר מלכותו כר' יוחנן דקרי למאני מכבדותי' הן הן הלבושים דמל' דאצי' שנמשכים מבחי' הד\"ר מלך הח' המברר כל הברורים דתה\"ו (והוא שרש התה\"ו והתיקון כנודע) והוא שרשן של ישראל המקיימים המצות למטה. וזהו ב' בחי' שיש במצות, בחי' שמחה של מצוה הוא מצד שנמשכו מרצון העליון ב\"ה והיא ממשכת בחי' לבוש מלכות וע\"ז נאמר תחת אשר לא עבדת וגו' בשמחה ובטוב לבב מרוב כ\"ל וכמארז\"ל יפה שעה א' כו' מכל חיי עוה\"ב כו' כנ\"ל. והשנית הוא לקיים מצות המלך ב\"ה בלי טעם כלל והיא התחילה, כי זהו בחי' המשכת עמ\"ש הקודמת לכל כו', ואח\"כ לשמוח בשמחה של מצוה שלא ציוה לחטוב עצים כ\"א המצות האלה אשר יעשה האדם וחי בהם מכל חיי עוה\"ב כו', ושעי\"ז מתחברים ב' בחי' חו\"ג אהוי\"ר כאחד וזהו ענין התיקון באצי' לחבר כמה הפכים בנושא אחד משא\"כ בתהו כנודע.\n<b>וזהו</b> ענין הויכוח של שמואל הנביא ע\"ה עם שאול המלך ע\"ה כאשר אמר לו בדבר ה' כה<sup data-n=\"5647\">25</sup> אמר ה' צבאות פקדתי את אשר עשה לך עמלק כו' והחרמת כו' כשחמל העם על מיטיב הצאן הלך שאול בתר טעמא כי עיקר טעם המצוה הוא להאבידו מן העולם ע\"כ הותיר ממיטיב הצאן למען זבוח לה' לתקנם בעולות וזבחים כי מה בכך שיהרגם או כשיזבחם לה' בעולות שבין כך ובין כך יאבדו מן העולם, וע\"ז אמר שאול הקימותי את דבר ה', והשיב לו שמואל החפץ לה' בעולות וזבחים כו' כי שמוע מזבח טוב כו', החפ\"ץ דייקא הוא הרצון העליון פשוט מצטרך",[["5645","23","<b>יעקב. . בריח התיכון</b>: ראה זהר תרומה קעה, ב."],["5646","24","<b>משה מלגיו יעקב מלבר</b>: תקו\"ז תי\"ג (כט, א)."],["5647","25","<b>כה אמר ה' צבאות</b>: שמואל-א טו, ב ואילך."]]],[2100990394,"לקיים רצונו הפשוט בלי טעם כלל כי אין טעם לרצון וזה מזבח טוב כו' וכמ\"ש במ\"א ע\"ש.\n<b>וזהו</b> ענין חג<sup data-n=\"5648\">26</sup> הסוכות שהוא המשכת ז' מקיפים למל' בחי' לבושי מלכות בכל ז'<sup data-n=\"5649\">27</sup> ימי החג ז' אושפיזין עלאין ע\"י קיום המצות שקיימו בכל השנה, כי רמ\"ח<sup data-n=\"5650\">28</sup> מ\"ע המה רמ\"ח אברין דמלכא, רמ\"ח אברי ז\"א כנודע, רק זהו דרך פרט (בהתחלקותן לט' וכאו\"א כולל ט\"ס טפ\"ט עולה פ\"א ורת\"ס עולה רמ\"ג וה\"ח רמ\"ח כו'), אבל המקיפים דז\"א המה כוללים, לכך המה שבעה ימים כנגד ז' ימי הבנין שנמשכים בז' ימים דסוכות שהמה כוללים רמ\"ח אברים פרטים דז\"א, וכן בסוכות ממשיכים כלליות השפע על כל השנה הבאה. . בר\"ה ממשיכים כלליות השפע כו', שלכך<sup data-n=\"5651\">29</sup> נק' בשם רא\"ש כו', כמו ראש האדם הכולל כלליות חיות הגוף כו', ולכן אומרים בסוכות זמן שמחתינו שממשיכים שמחה של מצוה על כל הימים פרטים הבאים בשנה, הגם שבפרטיות הימים נמצאים ימים אשר אין עת לשמוח כו', אעפ\"כ דרך כלל הוא בחי' שמחה כו', ובפרט בשמחת תורה ממשיכים בחי' רננה דאורייתא לכל השנה, והיינו בחי' הטעמים שבתורה וכמ\"ש ובלילה<sup data-n=\"5652\">30</sup> שיר\"ה עמי כנ\"ל, שהשיר עגול ולמעלה מן ההשכל כו', שנמשך מבחי' רצון העליון הכ\"ע הסכ\"ע המשפילי כו', דכחשיכה כאורה שוין קמיה.\n<b>וזהו</b> בחי' ישורו\"ן דכתיב אין<sup data-n=\"5653\">31</sup> כאל ישורון, דלגבי מלת ישורון נאמר אין כאל, דכחשיכה כאורה שוין קמיה, וזהו בחי' ישורון שהוא ל' ישר, בחי' השתוות עליונים ותחתונים קמיה כולם כאחד בשוה כלא חשיבי, ולשון שיר\"ה ולשון עגול הכל א', וזהו בחי' כתר דא\"ק, המקיף עד רגלי העשי' בהשואה א' כו', דהנה בשעת מתן תורה נתנו לכאו\"א ב' כתרים כו', אך בחטא העגל התנצלו את עדים כו', ועדיין לא נתתקן חטא העגל כמ\"ש ביום<sup data-n=\"5654\">32</sup> פקדי כו' עד ביאת משיח צדקינו ב\"ב לא אפשר להמשיך הכ\"ע בשלימותו (רק הארה ממנו ואף גם זאת מכתר הפרטי שת\"ת<sup data-n=\"5655\">33</sup> דאימא נעשה כתר לז\"א ממשיכים בשבועות בקריאת התורה) רק ע\"י התפלה אפשר להמשיך מעט מזעיר הארת הכתר הכללי עד בוא גואלינו משיח צדקנו ב\"ב אז יתגלה כלליות הכתר בשלימותו ויתוקן חטא העגל בשלימותו כו', והיינו כי השיר דתפלה הוא בחי' רצון פשוט שלמעלה מהשכל אליו ית', ואתעדל\"ת אתעדל\"ע ממשיך הארת הכ\"ע רצון העליון הפשוט כו' מבחי' ישורו\"ן, וזהו ויהי בישורו\"ן מלך, שמבחי' ישורו\"ן הכתר הכולל דא\"ק מקור כל המקיפים",[["5648","26","<b>חג הסוכות. . ז' מקיפים</b>: ראה ג\"כ תו\"א מקץ לז, ד."],["5649","27","<b>ז' ימי החג ז' אושפיזין</b>: ראה זח\"ג קג, ב ואילך."],["5650","28","<b>רמ\"ח מ\"ע. . אברין דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א)."],["5651","29","<b>שלכך נק' בשם ראש</b>: נסמן לעיל ע' תשמח."],["5652","30","<b>ובלילה שיר\"ה עמי</b>: תהלים מב, ט."],["5653","31","<b>אין כאל ישורון</b>: ברכה לג, כו."],["5654","32","<b>ביום פקדי</b>: תשא לב, לד."],["5655","33","<b>שת\"ת דאימא נעשה כתר לז\"א</b>: ראה ע\"ח שער מוחין דצלם רפ\"ה ורפ\"ז. שער דרושי הצלם דרוש ד' וה'."]]],[2100990395,"נמשך השפע של הלבושים ומקיפים למל' דאצי', וזהו מ\"ש בפרקי<sup data-n=\"5656\">34</sup> דר\"א עד שלא נברא העולם הי' הוא ושמו בלבד, ופי' המקובלים הקדמונים כי שמ\"ו<sup data-n=\"5657\">35</sup> גי' רצון וזהו הכתר דא\"ק עפ\"י קבלת האריז\"ל שלפני האצי' כו' והוא הנק' בחי' ישורון וד\"ל.\n<b>בהתאסף</b> ראשי עם יחד שבטי ישראל, פי' עיקר זמן התגלות הכ\"ע דא\"ק הוא בזמן התאסף ראשי עם יחד בהתכללות כולם כאחד באחדות אמיתי באור פניו ית', והיינו בזמן המשיח ב\"ב, שאז יוכללו כל. . בהתכללות ראש א' הוא משיח צדקינו, אבל עד זמן ההוא אין האחדות נמצא בישראל מימות יהושע בן נון כו', ומכ\"ש בימי התנאים ואמוראים שנתחלקו לכמה ראשים וכו', זולתי במ\"ת כתיב ויחן<sup data-n=\"5658\">36</sup> ישראל כו', ואעפ\"כ הי' מתחלקים לכמה ראשים, שרי<sup data-n=\"5659\">37</sup> אלפים ושרי מאות כו', אבל בימות המשיח ב\"ב יתאספו ראשי עם יחד שבטי ישראל באחד אמיתי, אשר כמוהו לא נהייתה אפי' במ\"ת, ואז דוקא ויהי בישורון מלך וד\"ל.\n<b>והנה</b> מה שכינו חז\"ל הטבעת<sup data-n=\"5660\">38</sup> של ברזל הקשור בבהמות בשם שי\"ר כו' ושל זהב וכסף בש' טבעת בלשונם ז\"ל, הוא מפני שהמלאכים עליונים שבחיצוניות העולמות נק' בש' בהמות וחיות והשירה שלהן הוא בחי' חיצוני' כאמרם ז\"ל כל בעלי השיר יוצאין בשיר כו', הכוונה השיר של המלאכים שהוא חיצוני וז' מיני מתכות הן ששרשן מז' מדות עליונות הן החיצוני' שבכולם הוא הברזל אבל השי\"ר של הנשמות הוא הפנימיות שבכולם שנק' טבעת בלשונם ז\"ל שהוא של בחי' זהב וכסף וכמ\"ש שירה עמי שירו דייקא הפנימי כו' וכמ\"ש<sup data-n=\"5661\">39</sup> במ\"א ע\"פ מזמור שיר חנוכת הבית וגו' ע\"ש.",[["5656","34","<b>בפרקי דר\"א עד שלא נברא העולם</b>: פ\"ג."],["5657","35","<b>שמ\"ו גי' רצון</b>: ראה מאמרי אדה\"ז תקס\"ד ע' רלו בשם הפרדס. פע\"ח (שער הק\"ש) ש\"ח, ספכ\"ח."],["5658","36","<b>ויחן ישראל</b>: ישראל יט, ב."],["5659","37","<b>שרי אלפים ושרי מאות</b>: יתרו יח, כא. כה."],["5660","38","<b>הטבעת של ברזל הקשור בבהמות בשם שיר</b>: ראה רמב\"ם הל' כלים פ\"ח, ה\"ט. ראה תו\"ח לד, ד בראשית שחיצוניות העולמות נק' בשם בהמות."],["5661","39","<b>וכמ\"ש במ\"א ע\"פ מזמור שיר חנוכת הבית</b>: ראה לקו\"ת ברכה צח, ג."]]],[2100990396,"<h3>נוסח שלישי: לבאר מ\"ש שתכלית העבודה</h3>\n<b>[תורה צוה]</b>\n<b>לבאר</b><sup data-n=\"5662\">1</sup> מ\"ש שתכלית העבודה לברר בירורין ולמטה נק' מ\"ה<sup data-n=\"5663\">2</sup> וב\"ן, מ\"ה הוא המברר וב\"ן הוא המתברר, ולמעלה נק' ע\"ב ס\"ג, ס\"ג הוא שבירה וחלל וע\"ב הוא תיקון וטעמים מצחא דא\"ק מל' דא\"ס כח המברר.\n<b>והענין</b> דהנה איתא במדרש<sup data-n=\"5664\">3</sup> ישראל ואומות עלו במחשבה מחשבה דא\"ק, כה<sup data-n=\"5665\">4</sup> אמר אחיך אדום, ואדרבה אפילו עשיו<sup data-n=\"5666\">5</sup> הוא בכורך כתיב והיינו מצד יציאה וכמ\"ש ויצא<sup data-n=\"5667\">6</sup> הראשון אדמוני כו', והוא ע\"פ מ\"ש שקודם<sup data-n=\"5668\">7</sup> בריאת העולם הי' א\"ס ב\"ה ממלא כל המקום בשוה וכשעלה ברצונו הפשוט לברוא את העולם צמצם וסילק את נקודת עצמותו ונעשה מקום חלל ופנוי ומהנקודה הנ\"ל נמשך קו\"ח להתפשט נמצא מקור ושרש האומות הוא מההסתלקות וחלל שנעשה קודם הקו הנ\"ל שהוא שרש ישראל, ולמשל כשאדם אינו רוצה איזה דבר הוא מסלק אותו ולמשל<sup data-n=\"5669\">8</sup> שליא קודם לולד שא\"א להתהוות הרמ\"ח אברי הולד וגידים אם לא שיהי' מקיף אותם מקודם השליא ואח\"כ כשיוצא הולד לאויר העולם יוצא ג\"כ מקודם השליא ואח\"כ יוצא הולד והשליא נעשה פסולת וד\"ל.\n<b>ולמשל</b> ג\"כ ממ\"ש קליפה<sup data-n=\"5670\">9</sup> קודם לפרי והענין שמקודם כשהפרי חונט אין ניכר שום התחלקות פרי וקליפה רק אח\"כ כשנגדל הפרי נגדל ונבדל ג\"כ הקליפה יותר, כן ג\"כ כאן מקודם מבחי' יציאה היינו מצד ההסתלקות והחלל יצא עשו הראשון ואח\"כ כשהתחיל למשוך הקו\"ח הנ\"ל בפנימי' נבדל פנימי' מחיצוניו' ונעשה למטה בהשתלשלות חיצוניות דחיצוניות ורע גמור.\n<b>וזהו</b> ואלה<sup data-n=\"5671\">10</sup> המלכים אשר מלכו בארץ אדום לפני מלוך מלך לבני ישראל והיינו מצד יציאה כו' ונעשה מזה וימלוך<sup data-n=\"5672\">11</sup> וימת כו' בחי' מיתה ממש וזהו ענין",[["5662","1","<b>לבאר מ\"ש שתכלית העבודה לברר בירורין</b>: נעתק מכת\"י 1157 (שא, ב).\nהנחה אחרת מביאור ד\"ה תורה צוה מהנדפס לעיל ע' תשמג. וע' תשנט."],["5663","2","<b>מ\"ה וב\"ן. . ע\"ב ס\"ג</b>: ראה ג\"כ תו\"א ויחי מז, ד. לקו\"ת במדבר ז, א. ובכ\"מ."],["5664","3","<b>במדרש ישראל ואומות עלו במחשבה</b>: ב\"ר פ\"א, ד. וראה לקו\"ת שה\"ש ביאור לד\"ה יונתי בחגוי (יז, סע\"ד ואילך)."],["5665","4","<b>כה אמר אחיך אדום</b>: חקת כ, יד — וישלח משה מלאכים. . אל מלך אדום כה אמר אחיך ישראל."],["5666","5","<b>עשו הוא בכורך</b>: ראה תולדות כז, יט — ויאמר יעקב אל אביו אנכי עשו בכרך."],["5667","6","<b>ויצא הראשון אדמוני</b>: תולדות כה, כה."],["5668","7","<b>שקודם בריאת העולם. . ממלא כל המקום</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א ענף ב. שעה\"י קטו, ובהערה 2."],["5669","8","<b>ולמשל שליא קודם לולד</b>: ראה תו\"א וישלח כה, ג."],["5670","9","<b>קליפה קודם לפרי</b>: ראה זהר (סבא) משפטים קח, רע\"ב. וראה תו\"א סא, א. תו\"ח בראשית קפה, א."],["5671","10","<b>ואלה המלכים אשר מלכו בארץ אדום</b>: וישלח לו, לא."],["5672","11","<b>וימלוך וימת</b>: שם לב-לג."]]],[2100990397,"משארז\"ל אין<sup data-n=\"5673\">12</sup> לך עשב מלמטה שאין לו מזל מלמעלה שמכה בו ואומר לו גדל, המזל היינו בחי' כח הצומח רוחני שנעשה ממנו עשב וגרעין גשמי הווה ונפסד נמצא הוא בחי' מיתה לכח הצומח רוחני כשמתלבש בעשב הגשמי וזהו בחי' מזל והכאה דרך דילוג ומיתה ממש מרוחני לגשמי כמו\"כ הענין שיתהווה מנאצלים נבראים הוא ע\"י בחי' מזלות ודילוג ומיתה על אופן וימלוך וימת וד\"ל.\n<b>וזהו</b> שפעם<sup data-n=\"5674\">13</sup> א' הוא אומר שטן<sup data-n=\"5675\">14</sup> ופנינה לש\"ש נתכוונו, הנה המשמעות שיש בהם איזה צד קדושה ופעם א' הוא אומר נתן<sup data-n=\"5676\">15</sup> עיניו במקדש ראשון כו', הענין הוא כנ\"ל שבהשתלשלות למטה נעשה רע גמור. וזהו ג\"כ שפעם<sup data-n=\"5677\">16</sup> א' הוא אומר וצבא<sup data-n=\"5678\">17</sup> השמים לך משתחוים היינו שמשבח הביטול של המלאכים ופעם א' הוא אומר<sup data-n=\"5679\">18</sup> הן במלאכיו ישים תהלה כו' ושמים<sup data-n=\"5680\">19</sup> לא זכו בעיניו, והענין ג\"כ כנ\"ל שמצד נאצלים הביטול של המלאכים כלא נחשב ומצד נבראים ובחי' תחתונים משבח הביטול של המלאכים מחמת שהנבראים ירדו מטה מטה מאוד עד בחי' מזלות ומיתה הנ\"ל והוא הבחי' מלוכה ומיתה הנ\"ל המאיר בז' מלכין קדמאין שמתו עד שמלך מלך<sup data-n=\"5681\">20</sup> הח' שלא נאמר בו עוד מיתה ושבירה כי הוא בחי' תיקון מכח המברר הנ\"ל והוא מלך ישראל (כי אף שמבחי' יציאה נאמר עשיו בכורך אבל מצד שרש דשרש ישראל הוא מבחי' מל' דא\"ק העצמי) מלך הדר מלשון הדר מלכותך והוד<sup data-n=\"5682\">21</sup> והדר לפניו דוקא מל'<sup data-n=\"5683\">22</sup> דא\"ס מצחא דא\"ק בחי' טעמים הנ\"ל.\n<b>וזהו</b> מ\"ש בפרקי<sup data-n=\"5684\">23</sup> ר\"א עד שלא נברא העולם הי' הוא ושמו בלבד דהיינו מל' דא\"ס וזהו ג\"כ אתה<sup data-n=\"5685\">24</sup> קדוש ושמך קדוש<sup data-n=\"5686\">25</sup> ומובדל בחי' שמו הגדול.\n<b>ובזה</b> יובן ג\"כ שפעם א' הוא אומר אסתכל<sup data-n=\"5687\">26</sup> באורייתא וברא עלמא ופעם א' הוא אומר אורייתא<sup data-n=\"5688\">27</sup> מחכמה נפקת, והענין כידוע שיש רצון מורכב ורצון פשוט, רצון מורכב הוא שנמשך מקו\"ח הנ\"ל ונתלבש בחכמה ושכל ומדות, אך מאין נלקח",[["5673","12","<b>אין לך עשב מלמטה</b>: ראה ב\"ר פ\"י, ו. זח\"א רנא, א (בהשמטות). ח\"ב קעא, ב. מורה נבוכים ח\"ב, פ\"י. אגה\"ת פ\"ו."],["5674","13","<b>שפעם א'</b>: ראה לקו\"ת חקת סב, ב. מסעי צב, א. דרך מצותיך לא, ב."],["5675","14","<b>שטן ופנינה לש\"ש נתכוונו</b>: ב\"ב טז, א."],["5676","15","<b>נתן עיניו במקדש ראשון</b>: סוכה נב, א."],["5677","16","<b>שפעם א' הוא אומר</b>: ראה לקו\"ת מטות פז, א."],["5678","17","<b>וצבא השמים לך משתחווים</b>: נחמי' ט, ו."],["5679","18","<b>במלאכיו ישים תהלה</b>: איוב ד, יח."],["5680","19","<b>ושמים לא זכו בעיניו</b>: איוב טו, טו."],["5681","20","<b>מלך הח'. . בחי' תיקון</b>: וישלח שם לט. ראה ע\"ח שער (ט) שבירת הכלים פ\"ח. שער (י) התיקון פ\"ב-ג. תו\"א ויחי קג, ב. ובהנסמן לשם."],["5682","21","<b>והוד והדר לפניו</b>: דברי הימים-א טז, כז."],["5683","22","<b>מל' דא\"ס מצחא דא\"ק</b>: ראה ע\"ח (שער התיקון) פ\"ג."],["5684","23","<b>בפרקי ר\"א עד שלא נברא העולם</b>: פ\"ג."],["5685","24","<b>אתה קדוש ושמך קדוש</b>: שמונה עשרה."],["5686","25","<b>קדוש ומובדל</b>: ראה תו\"כ ורש\"י ר\"פ קדושים. תניא כמצויין במפתח ענינים מערכת קדושה."],["5687","26","<b>אסתכל באורייתא וברא עלמא</b>: זח\"ב קסא, רע\"ב."],["5688","27","<b>אורייתא מחכמה נפקת</b>: זח\"ב סב, א. פה, א. קכא, א. ועוד."]]],[2100990398,"זה הרצון ומדוע יש לו זה הרצון ושכל עד\"מ ולא אחר הוא מפני שיש לו תענוג מזה הרצון והשכל, והתענוג הוא טעם<sup data-n=\"5689\">28</sup> הכמוס על הרצון וכמבואר במ\"א, אך מי הכריחו שיהי' זה התענוג ולא אחר הוא מפני שיש עוד מקור התענוגים בעצמותו ממש שא\"א להתגלות ולהתלבש בשום שכל בעולם וממנו נלקח דרך בטישה ובקיעה וכמבואר במ\"א התענוג המורכב ברצון ושכל, וזהו שעשועי<sup data-n=\"5690\">29</sup> המלך בעצמות א\"ס ב\"ה ממש, וזהו<sup data-n=\"5691\">30</sup> ואהי' אצלו אמון, שעשועים לשון רבים לרמז על ב' תענוגים הנ\"ל.\n<b>וזהו</b> מ\"ש אמון פדגוג כו' כי הוא מלשון המשכה שהוא תענוג הנמשך ברצון ושכל וכו' ואמון מופלא ומכוסה כו' הוא כמ\"ש ואהי' אצלו אמון אצלו א\"ס ב\"ה ממש נמצא ממילא יובן אורייתא מחכמה נפקת הוא התענוג הנמשך ברצון ושכל הנ\"ל, ואסתכל באורייתא וברא עלמא הוא בחי' מקור התענוג שעשועי המלך בעצמו שקודם ההסתלקות וקו\"ח הנ\"ל ונק' טעמי תורה כידוע שטעם הוא תענוג וכמבואר<sup data-n=\"5692\">31</sup> במ\"א מבחי' טעמים הנ\"ל שהם מקור התורה רנה דאורייתא שרש דשרש ישראל.\n<b>וזהו</b> עבדו<sup data-n=\"5693\">32</sup> לפניו בשמחה הוא ענין שמחה של מצוה ותענוג הנמשך בשכל ומדות ובואו לפניו ברננה היינו רננה<sup data-n=\"5694\">33</sup> דאורייתא בחי' תענוג אהי' אצלו אמון הנ\"ל, ולכן גוי<sup data-n=\"5695\">34</sup> שלמד תורה כלא נחשב ואדרבה כו' הוא מצד שאין מקורם ושרשם מבחי' טעמים ורננה דאורייתא הנ\"ל אין יכולים להשיג בחי' התורה הנ\"ל, ומה<sup data-n=\"5696\">35</sup> לך לספר חוקי כתיב, אבל ישראל יכולים לעלות למקורם ושרשם מקור התורה הנ\"ל, וע\"י מה הם יכולים לעלות מאחר שמצד הגוף בהשתלשלות ירדו מטה כו' הוא ע\"י דו\"ר וכידוע שהם גדפין<sup data-n=\"5697\">36</sup> לפרחא לעילא והענין כי רחימו הוא שמחה של מצוה הנ\"ל היינו שמחמת שנתן לו הקב\"ה מצות כמו אתרוג ולולב וכדומה שהיו תחת ממשלת ק\"נ להעלותם ולעשות בהם מצוה הוא אוהב אותו ויש לו מזה תענוג המורכב בשכל ומדות אבל דחילו הוא ענין מצות המלך שאפילו<sup data-n=\"5698\">37</sup> שיצוה לו לחתוך עצים וכדומה עד\"מ מבלי שישיג הוא שום תענוג רק שעשועי המלך בעצמו ממש.\n<b>וזהו</b> החילוק שבין אוה\"ע וישראל וכמארז\"ל<sup data-n=\"5699\">38</sup> שכשיבקשו אוה\"ע ליתן להם תו\"מ יאמר להם הקב\"ה מצוה קלה יש לי וסוכה שמה וכאו\"א עושה לו סוכתו",[["5689","28","<b>טעם הכמוס. . וכמבואר במ\"א</b>: ראה לקו\"ת שלח מט, ג. ושם מציין לע\"ח שער כ\"ב פ\"ה. והוא בהוצאת שקלאוו תק\"ס. ולפנינו הוא שער (כג) מוחין דצלם פ\"א."],["5690","29","<b>שעשועי המלך בעצמות א\"ס ב\"ה ממש</b>: נת' בעמק המלך שער א. וראה לקו\"ת שה\"ש כז, סע\"א."],["5691","30","<b>ואהי' אצלו אמון. . אמון פדגוג</b>: משלי ח, ל. ב\"ר בתחילתו."],["5692","31","<b>וכמבואר במ\"א</b>: ראה תו\"ח בראשית ד, א ובהנסמן שם."],["5693","32","<b>עבדו לפניו בשמחה</b>: תהלים ק, ב."],["5694","33","<b>רננה דאורייתא</b>: ראה זהר בהקדמה ח, א."],["5695","34","<b>גוי שלמד תורה</b>: ראה הל' ת\"ת לאדה\"ז פ\"ד ה\"ג."],["5696","35","<b>ומה לך לספר חוקי</b>: תהלים נ, טז."],["5697","36","<b>גדפין לפרחא לעילא</b>: ראה תקו\"ז ת\"ו."],["5698","37","<b>שאפילו שיצוה לו לחתוך עצים</b>: נסמן לעיל ע' תשלז."],["5699","38","<b>וכמארז\"ל. . מצוה קלה יש לי וסוכה שמה</b>: ע\"ז ג, א."]]],[2100990399,"בראש גגו ומתענג בה מאהבת המקום ב\"ה אליהם ואח\"כ כשהקב\"ה יוציא חמה כו' אינהו בעוטי מבעטי אבל לא ישראל וכו', הענין הוא כנ\"ל שמצד שהם אינם יכולים לקבל ולהשיג רק שמחה של מצוה ושישיגו מזה התענוג אבל ישראל אפשר להם לקבל התענוג הנעלם שעשועי המלך בעצמו מצות המלך אפילו שלא ישיגו הם שום תענוג.\n<b>וזהו</b> ג\"כ ענין הויכוח של שאול ושמואל שהקב\"ה אמר וצוה לא<sup data-n=\"5700\">39</sup> תחי' כל נשמה ובמלחמת עמלק לקח שאול מבחר הצאן בכדי להעלות עולה וזבחים, וכידוע היינו שרצה ג\"כ לקיים מצות לא תחי' כו' אבל שישיג בחי' תענוג לעשות עולה ריח ניחוח כו', שמחה של מצוה הנ\"ל, ואמר לו שמואל החפץ<sup data-n=\"5701\">40</sup> לה' בעולה וזבחים כי אם להקשיב ולשמוע כו' מצות המלך הנ\"ל שעשועי המלך בעצמו, אבל דהע\"ה אמר אם<sup data-n=\"5702\">41</sup> כה יאמר כו' ואם יאמר לא חפצתי הנני, בחי' לקשוב ולשמוע הנ\"ל, בחי' דחילו הנ\"ל.\n<b>וזהו</b> שבשעת מ\"ת שהי' ג\"כ הארה מזה התענוג מקיף הכללי הנ\"ל אמרו ישראל נעשה<sup data-n=\"5703\">42</sup> ונשמע, נשמע היינו שעושה מה שהוא שומע ומבין בשכלו בחי' שמחה של מצוה הנ\"ל, והקדימו נעשה שהוא בחי' מצות המלך הנ\"ל. וזהו שמלאך<sup data-n=\"5704\">43</sup> סנד\"ל בא וקשר להם ב' כתרים א' מנעשה וא' מנשמע, היינו ב' בחי' שעשועי' הנ\"ל וצריך לזה סיוע של מלאך ומיכאל<sup data-n=\"5705\">44</sup> כהנא רבה מקריב<sup data-n=\"5706\">45</sup> נשמות הצדיקים ע\"ג המזבח וכו', להעלותן עד מקום הנ\"ל מפני שנשמתן בהשתלשלות למטה אינה יכולה לעלות בעצמה עד מקום הנ\"ל וכידוע, וזהו שארז\"ל שראה<sup data-n=\"5707\">46</sup> שכולהו עולים ע\"י מלאכים וכו' לבר מגוהרקא דרבי חייא רבה דמנפשי' קא סליק מצד שהי' נשמתו ממקום גבוה ונעלה מאוד עד שהי' יכול בעצמו לעלות כו' ודו\"ק.\n<b>וזהו</b> ענין מ\"ש תורה<sup data-n=\"5708\">47</sup> צוה לנו משה מורשה בחי' ירושה מקהילת יעקב כי ידוע שיעקב<sup data-n=\"5709\">48</sup> הוא יו\"ד עקב שנפל בבחי' עקביי' בשבה\"כ בחי' מיתה הנ\"ל, וכד<sup data-n=\"5710\">49</sup> אתכפיא סט\"א הנ\"ל ונעשה קהילת ואסיפת יעקב אסתלק יקרא דקוב\"ה בחי' יקר",[["5700","39","<b>לא תחי' כל נשמה</b>: פ' שופטים כ, טז."],["5701","40","<b>החפץ לה' בעולה וזבחים כי אם להקשיב ולשמוע</b>: שמואל-א טו, כב. — ויאמר שמואל החפץ לה' בעולות וזבחים כשמוע בקול ה'. . הנה שמוע מזבח טוב להקשיב מחלב מילים."],["5702","41","<b>אם כה יאמר כו' ואם יאמר לא חפצתי</b>: ראה שמואל-ב טו, כו."],["5703","42","<b>נעשה ונשמע</b>: משפטים כד, ז."],["5704","43","<b>שמלאך סנד\"ל בא וקשר להם ב' כתרים</b>: ראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 202."],["5705","44","<b>ומיכאל כהנא רבה</b>: ראה זהר (ס\"ת) לך פ, סע\"א. פא, רע\"א."],["5706","45","<b>מקריב נשמות</b>: ראה חגיגה יב, ב. תוד\"ה ומיכאל מנחות קי, א."],["5707","46","<b>שראה שכולהו עולים ע\"י מלאכים</b>: ב\"מ פה, ב."],["5708","47","<b>תורה צוה לנו משה</b>: ברכה לג, ד."],["5709","48","<b>שיעקב הוא יו\"ד עקב</b>: ע\"ח ש\"ג פ\"ב. פרדס שכ\"ג בערכו. וראה תו\"א ר\"פ ויצא. ובכ\"מ."],["5710","49","<b>וכד אתכפיא סט\"א</b>: ראה זהר תרומה קכח, ב."]]],[2100990400,"והדר מלכותו הנ\"ל שעשועי המלך בעצמו ולכן הוא שהתורה ירושה מבחי' יעקב הנ\"ל בחי' תוהו ותיקון ירושה מתוהו וד\"ל.\n<b>ובזה</b> יובן מ\"ש בזוה\"ק<sup data-n=\"5711\">50</sup> שישראל נקראים בג' שמות יעקב וישראל וישורון, הענין הוא כי מבחי' קהלת יעקב הנ\"ל נעשה בחי' ישראל וכמ\"ש ע\"כ<sup data-n=\"5712\">51</sup> לא יאמר שמך עוד יעקב כי אם ישראל יהי' שמך כי שרית עם אלקים ועם אנשים ותוכל, אלקים היינו הטבע, וכידוע שאלקים<sup data-n=\"5713\">52</sup> בגימט' הטבע, ולכאורה למה לא נאמר על אלקים, אך הענין הוא שדווקא עם אלקים וכמארז\"ל זכה<sup data-n=\"5714\">53</sup> נעשה לו עזר לא זכה כנגדו, היינו ע\"פ מ\"ש בזוהר כד אתכפייא סט\"א אסתלק יקרא דקוב\"ה ונעשה אתהפכא חשוכא לנהורא ויתרון ותוס' וריבוי האור מן החושך עצמו, וזהו כי שרית שנעשה שר עם אלקים דייקא וד\"ל. וזהו שמע<sup data-n=\"5715\">54</sup> ישראל, בחי' ישראל הנ\"ל, נאמר ואהבת בכל לבבך ודרשו רז\"ל בשני<sup data-n=\"5716\">55</sup> יצריך דוקא וכו', ועל זה נאמר בזוהר דא<sup data-n=\"5717\">56</sup> הוא רזא היינו הרז שנעשה יתרון אור ותוס' משני יצריך דוקא וד\"ל.\n<b>ואח\"כ</b> הוא בחי' ישורון ובכל<sup data-n=\"5718\">57</sup> מאדך בחי' רעותא דליבא כי ישורון הוא סובל ג' פי' האחד הוא לשון שורה וישר שמחמת אתכפייא ואתהפכא הנ\"ל אסתלק<sup data-n=\"5719\">58</sup> יקרא דקוב\"ה ויגיע לו הארה מבחי' טעמי תורה ושעשועי המלך בעצמו הנ\"ל שקמי' כחשיכה כאורה ומעלה ומטה שוין בבחי' שורה, וזהו אצל ישורון כתיב אין<sup data-n=\"5720\">59</sup> כאל ישורון בחי' הוא ושמו בלבד תענוג הנעלם הנ\"ל.\n<b>ופי'</b> הב' דישורון הוא מלשון שירה, כי מחמת אתהפכא הנ\"ל מגיע לו הארה מבחי' תענוג הנ\"ל שהוא מקיף הכללי שאינו יכול להתלבש דרך אורות וכלים בשכל ודבור וכדומה רק בבחי' העדר הכלי בחי' שירה רננה דאורייתא הנ\"ל קול פשוט בלא דיבור למעלה מהדעת וכו', וגם נראה בחוש שבחי' ניגון מרמז על זה הבחי' שלעולם סוף כל ניגון עולה וחוזר לקדמותו לתחילת הניגון היינו שמעלה ומטה שוין (ולכך נאמר מעשה<sup data-n=\"5721\">60</sup> בא' שהעלה טינא בלבו ולא יכול למסבל ובכה, הענין הוא שכאשר בא לבחי' ישורון בחי' תענוג וטעמי תורה הנ\"ל רננה דאורייתא מקיף הכללי הנ\"ל לא יכול הכלי מוחין ומדות שלו למסבל האור ולהתיישב בתוכו רק נבקע ויוצא לחוץ בבחי' בכי' מותרות מוחין העדר הכלי, וזהו ג\"כ הנאמר בר\"ע<sup data-n=\"5722\">61</sup>",[["5711","50","<b>בזוה\"ק שישראל. . יעקב וישראל וישורון</b>: ראה זהר בראשית קעז, ב."],["5712","51","<b>ע\"כ לא יאמר שמך עוד יעקב</b>: וישלח לב, כט."],["5713","52","<b>שאלקים בגימט' הטבע</b>: פרדס שער יב (שער הנתיבות) פ\"ב. ראשית חכמה שער התשובה פ\"ו ד\"ה והמרגיל (קכא, ב). של\"ה פט, א (דאיתא בזהר). קפט, א (ומרומז בזהר). שח, ב."],["5714","53","<b>זכה נעשה לו עזר</b>: ראה יבמות סג, א."],["5715","54","<b>שמע ישראל. . ואהבת בכל לבבך</b>: ואתחנן ו, ד. ה."],["5716","55","<b>בשני יצריך</b>: ספרי ואתחנן שם."],["5717","56","<b>בזוהר דא הוא רזא</b>: וירא קו, א."],["5718","57","<b>ובכל מאדך</b>: ואתחנן שם."],["5719","58","<b>אסתלק יקרא דקוב\"ה</b>: ראה זהר תרומה קכח, ב."],["5720","59","<b>אין כאל ישורון</b>: ברכה לג, כו."],["5721","60","<b>מעשה בא' שהעלה טינא בלבו</b>: סנהדרין עה, א."],["5722","61","<b>בר\"ע. . אדם מניחו בזויות</b>: ברכות לא, א. וראה לקו\"ת פקודי ה, א."]]],[2100990401,"כשהי' אדם מניחו בזויות זו מוצאו בזויות אחרת מרוב כריעות והשתחוואות היינו ג\"כ כנ\"ל מחמת רבוי האור נעשה העדר הכלי וכמשל אדם המדבר לפני המלך וכשרואה שאין המלך פונה אליו היינו שאינו יכול להשיגו הוא נופל לפניו בהשתחוואה ומראה לו העדר הכלי שלו וד\"ל.\n<b>וזהו</b> בחי' בכל מאודך רעותא דליבא בריח התיכון שנכללו יחד דו\"ר בחי' חו\"ג שהם הפכים וא\"א שיולד מהם דבר חדש כשהם כאו\"א בפ\"ע אך כשנתגלה בהם בחי' כתר הנ\"ל ממילא נעדרו מבחי' כלי שלהם והוכרחו שניהם לבטל אליו ונכללו זה בזה ונעשו יחוד גמור ואז נולד מהם דבר חדש בחי' רעותא דליבא וכמבואר זה במ\"א<sup data-n=\"5723\">62</sup> באריכות). וזהו מ\"ש שמלך הח' הדר כבוד מלכותו הנ\"ל, ושם<sup data-n=\"5724\">63</sup> עירו שהוא שורה בתוכה הוא פעו מלשון הגמרא פעיו, ופעיו הוא בחי' שירה וקול פשוט הנ\"ל.\n<b>ופי'</b> הג' של ישורון<sup data-n=\"5725\">64</sup> הוא מלשון שיר וטבעת שהוא עגול סוכ\"ע מקיף הנעלם וכללי, כי הנה ידוע שבלשון הגמרא שיר הוא של ברזל של בהמה וזהו כל<sup data-n=\"5726\">65</sup> בעלי השיר יוצאים בשיר ונמשכים בשיר בחי' ביטול המלאכים בחי' בהמות וחיצוניות העולמות, וטבעת הוא של כסף וזהב בחי' שיר של ישראל וד\"ל בחי' תענוג ומקיף הנעלם הנ\"ל, ומעין זה הי' להם בשעת מ\"ת וזהו נעשה ונשמע שאמרו כו', אך לכאורה מאין הי' זה להם כי כעת הוא מחמת התורה ובדו\"ר כנ\"ל, אבל בעת הנ\"ל לא הי' זה, אך הוא מצד שהיו במצרים בחומר<sup data-n=\"5727\">66</sup> ובלבנים ויצעקו<sup data-n=\"5728\">67</sup> אל ה' בצר כו' ע\"י אותות ומופתים וע\"י אמונה וד\"ל.\n<b>וזהו</b> מ\"ש שלע\"ל יהי' ויהי בישורון מלך בהתאסף ראשי עם יחד שבטי ישראל, בחי' ראש אחד כתר הכללי היינו שכעת אנו עושים רק הארה בלבד מבחי' ישורון הנ\"ל, ולכן א\"א להיות יחד שבטי ישראל וכו', ואף שבמ\"ת שהי' הארה מבחי' הנ\"ל כתיב ויחן<sup data-n=\"5729\">68</sup> שם ישראל לשון<sup data-n=\"5730\">69</sup> יחיד עכ\"ז הי' להם שרי<sup data-n=\"5731\">70</sup> אלפים ושרי מאות כו' אבל לע\"ל כשיתגלה כתר הכללי יוכללו ויתאספו כולם בראש א' במלך המשיח ולא<sup data-n=\"5732\">71</sup> ילמדו איש את רעהו כתיב כי כולם ידעו אותי מקטנם ועד גדולם מצד שיתגלה הבחי' שקטן וגדול שם הוא וד\"ל, וזהו שתקרא לע\"ל ארץ<sup data-n=\"5733\">72</sup> חפץ, חפצי בה",[["5723","62","<b>במ\"א באריכות</b>: ראה לקו\"ת שלח מג, א. בלק עא, ג."],["5724","63","<b>ושם עירו. . פעו</b>: וישלח לו, לט."],["5725","64","<b>ישורון הוא מלשון שיר וטבעת</b>: ראה לקו\"ת שה\"ש א, ג."],["5726","65","<b>כל בעלי השיר יוצאים בשיר</b>: שבת נא, ב. וראה תו\"א ז, ג. קיג, א. לקו\"ת ברכה צח, א."],["5727","66","<b>בחומר ובלבנים</b>: שמות א, יד."],["5728","67","<b>ויצעקו אל ה'</b>: תהלים קז, ו."],["5729","68","<b>ויחן שם ישראל</b>: יתרו יט, ב."],["5730","69","<b>לשון יחיד</b>: מכילתא ופרש\"י שם."],["5731","70","<b>שרי אלפים ושרי מאות</b>: יתרו יח, כא. כה."],["5732","71","<b>ולא ילמדו איש את רעהו</b>: ירמי' לא, לג."],["5733","72","<b>ארץ חפץ, חפצי בה</b>: מלאכי ג, יב. ישעי' סב, ד."]]],[2100990402,"היינו שיתגלה בבחי' ארץ בחי' חפץ ורצון פשוט הנ\"ל שמעלה ומטה שוין ועתידה<sup data-n=\"5734\">73</sup> ארץ שתוציא כלי מילת וגלוסקאות היינו שלא יהי' צריך לחרישה וזריעה בחי' בירורין מ\"ה וב\"ן מנוגה מחמת שיתגלה בחי' טעמים הנ\"ל בחי' המברר.\n<b>וזהו</b> ענין בחי' ז' ימי הסוכות שאנו עושים הקפות ממצות לולב היינו שמחה של מצוה הנ\"ל מכל השנה, כי חודש<sup data-n=\"5735\">74</sup> תשרי הוא ראש וכללות השנה ומר\"ה<sup data-n=\"5736\">75</sup> ממשיכים יראה על כל השנה ומיוה\"כ סליחה וכמבואר במ\"א וסוכות הוא בחי' שמחה מרמ\"ח מ\"ע על כל השנה, אך לפי\"ז לכאורה הי' צריך להיות רמ\"ח ימים שמחות כו', אך הענין הוא כידוע שהרמ\"ח מ\"ע נמשכים מהז' מדות ולכן המקיפים והשמחות הוא ג\"כ לז' ימים בחי' מדות הנ\"ל ושמחת תורה שהוא כלל השמחות של תורה וטעמין ורנני דאורייתא בחי' שעשועי המלך בעצמו הנ\"ל לכן<sup data-n=\"5737\">76</sup> אנו עושים הקפה עם ספרי תורה וד\"ל.",[["5734","73","<b>ועתידה ארץ שתוציא כלי מילת וגלוסקאות</b>: שבת ל, ב."],["5735","74","<b>חודש תשרי. . ראש וכללות השנה</b>: נסמן לעיל ע' תשמח."],["5736","75","<b>ומר\"ה ממשיכים יראה על כל השנה</b>: נסמן לעיל ע' תשמח."],["5737","76","<b>לכן אנו עושים הקפה עם ספרי תורה</b>: ראה לקו\"ת דרושים לסוכות פ, ג."]]],[2100990403,"<h3>בהקדמת הזוהר ר\"ח פתח כשושנה בין החוחים</h3>\n<b></b><b>בעזר\"ה יום שמיני עצרת </b>\nיום שמיני עצרת\n(הקדמת ספר הזוהר)\nר'<sup data-n=\"5738\">1</sup> חזקיה פתח כשושנה<sup data-n=\"5739\">2</sup> בין החוחים מאן שושנה דא כנ\"י מה שושנה דאיהי בין החוחים אית בה סומק וחוור אוף כנ\"י אית בה דין ורחמי ע\"כ. פי' משל זה דשושנה בין החוחים על בחי' מלכו' דאצי' הוא אומר דפשט הכתוב ג\"כ מורה ע\"ז דהרי כך הוא אומר כשושנה בין החוחים כך רעייתי שהוא בחי' כנ\"י שהיא בחי' מל' למעלה כידוע בין הבנות כו' וא\"כ תחלה יש לפרש הפסוק הזה עצמו ואח\"כ יתבאר מה שחידש ר' חזקיה בו במאמר זה.\n<b>דהנה</b> ידוע דבחי' מל'<sup data-n=\"5740\">3</sup> דאצי' נעשה עתיק לבריא' ובחי' עתיק זה נק' כתר דבי\"ע וביאור ענינו כשבא בגילוי כך הוא דהנה ידוע דשם ב\"ן כשיורד למטה לברר ברורי' דרפ\"ח ניצוצי' שנפלו בנוגה הנה ידוע שהוא עד\"מ כמו ביטול הנר",[["5738","1","<b>ר' חזקיה פתח</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (קכב, א). מאמר זה רשום בהכת\"י אחר ד\"ה תורה צוה וביאוריו (משמחת תורה ואסרו חג).\nראה ביאוה\"ז מכ\"ק אדמו\"ר הצ\"צ ח\"ב ע' תקפה."],["5739","2","<b>כשושנה בין החוחים</b>: שה\"ש ב, ב."],["5740","3","<b>מל' דאצי' נעשה עתיק לבריאה</b>: נסמן לעיל ע' תקסה."]]],[2100990404,"בפני האבוקה הגדולה שכאשר יתגלה אור האבוקה הגדולה ממילא יומשך אחריה כל ניצוצין הקטני' העומדי' מקרוב אליה כו' וכך הוא הנמשל למעלה דכאשר מתגלה אור האלקי למטה בתגבורת אור גדולה ורחבה אזי ממילא כל בחי' ניצוצי' האלקיי' שנפלו למטה כאשר מתקרבים אל זה הגילוי הגדול ממילא המה בטילי' ונכללי' בכללות גילוי שכינה כביטול והתכללו' הנר באבוקה ממש כו' ואמנם הנה ענין גילוי אור זה הגדול היינו כאשר מתגלה מבחי' כתר דבי\"ע ובכל עולם לפי ערכו כאשר מתגלה מבחי' הכתר מגיע להם בחי' הביטול במציאות ממש ואז הוא זמן הבירור מבחי' תערובו' טו\"ר שיש בהם ונתהפך חשוכא לנהורא ומרירו למיתקא כו' והוא ענין הבירור דשם ב\"ן הנ\"ל שהוא מפני ענין גילוי שכינה יותר מכפי המדה והצמצום הראשון שנתצמצם האור האלקי באורו' וכלים מכלים שונים והיינו ג\"כ ענין גילוי בחי' עתיק דבריא' הנ\"ל בג\"ע העליון כשהנשמו' עולין שם מדי חודש ושבת כו' להתענג על ה' וכמאמר הזוהר<sup data-n=\"5741\">4</sup> דקדב\"ה אתא לאשתעשא עם צדיקייא בג\"ע ושעשועים הללו הם בחי' &lt;שפד&gt;\nשעשועי' שנמשכי' מעתיק דבריא' והוא ענין גילוי גדול כענין גילוי המלך בעונג ושעשועי' עם עבדיו כו' וז\"ש לחזות<sup data-n=\"5742\">5</sup> בנועם ה' כו' ואזי ממילא מתבטלי' כל העולמו' ממציאותם כו' ואז ג\"כ הוא זמן הבירור לאתהפכא חשוכא לנהורא כו' גם מכל התענוגי' הגשמיי' שנפלו למטה כו'.\n<b>ומפני</b> שע\"י התבררו' והתכללות זאת ניתוסף ונתרבה ההארה בענין תוס' גילוי בשם ב\"ן כמשל שלהבת האבוקה שניתוסף אורה הרבה ע\"י התכללו' ריבוי הניצוצו' בה כו'. לכך נמשלה לשושנה בין החוחים דגם השושנה הגשמית הנה סיבת יופייה והדרה בא רק מחמת גידולה בין החוחים והקוצים דוקא לפי שיתרון<sup data-n=\"5743\">6</sup> האור בא מתוך החושך דוקא כו' וזהו שהמשיל לשם ב\"ן כשיורד למטה בהיכלו' הנוגה לברר לשושנה בין החוחים דוקא וד\"ל, ואח\"כ אמר דכמו שהמל' בהיותה בבי\"ע נמשלה לשושנה בין החוחים כך הוא רעייתי בין הבנות למעלה.\n<b>והנה</b> מתחלה יש להבין פי' וענין בנות מה הן דהנה כתיב רבות<sup data-n=\"5744\">7</sup> בנות עשו חיל ואת עלית כו' דקאי על בחי' מל' דעולה במעלה על כל הבנות ולכאורה אינו מובן דהלא הבנות הן הנשמו' כמ\"ש ועלמות<sup data-n=\"5745\">8</sup> אין מספר א\"ת עלמות אלא עולמו' כו' והרי העולמו' הן נמשכי' מבחי' מל' מאין ליש ומאי רבותא דאת עלית על כולנה. אך הענין הוא דבנות הללו על בחי' אורו' דאצי' הוא אומר שנאצלו ביחד עם בחי' מל' דאצי' מאו\"א כו' ועליהם אומר רבות בנות עשו חיל ואעפ\"כ את עלית עליהם.",[["5741","4","<b>הזוהר דקדב\"ה אתא לאשתעשא עם צדיקייא בג\"ע</b>: ראה זח\"א צב, א. הנסמן בסה\"מ תשי\"א ע' 9."],["5742","5","<b>לחזות בנועם ה'</b>: תהלים כז, ד."],["5743","6","<b>שיתרון האור בא מתוך החושך</b>: ע\"פ קהלת ב, יג."],["5744","7","<b>רבות בנות עשו חיל</b>: משלי לא, כט."],["5745","8","<b>ועלמות אין מספר. . א\"ת עלמות אלא עולמו'</b>: שה\"ש ו, ח. ת\"ז בהקדמה (יד, ב). וראה זהר אחרי עא, ב. ע\"ז לה, ב. אוה\"ת וארא ס\"ע קצו ואילך."]]],[2100990405,"<b>וביאור</b> הדברים הנה יובן עד\"מ מן הכפרים לעיר שנקראו הכפרים בשם בנות לגבי העיר וכמו ושמתי<sup data-n=\"5746\">9</sup> אותם לך לבנות כו' וכן בנות<sup data-n=\"5747\">10</sup> ירושלים כלומר העיירו' הקטני' הסמוכי' אליה וכן על כל עיר שיש הרבה כפרים סביבותיה נקראו בנות כידוע כמו יבנה ובנותיה בית<sup data-n=\"5748\">11</sup> שאן ובנותיה כו' והטעם הוא לפי שהמדינה עצמה שהוא העיר היותר גדולה הנה היא כוללת את כל הכפרים הסובבי' בהתכנסם לתוכה לעיתים וכולם שייכי' ונכללי' בה ומאחר שכולן יעלו שמה אין להם שם ומקום מיוחד בפ\"ע רק שם העיר שנכללי' שם כי הלא אינם רק חלקים פרטיים והעיר כוללת את כולם וכמו כל פרטי פרטיים שנמשכו מן הכלל שנכללי' כולם בכלל הכוללם יחד כידוע.\n<b>וכך</b> יובן הנמשל למעלה דהנה באצי' עצמו יש אורו' שנק' אורו' פרטיים ופרטי פרטיים שכולם המה מתאחדי' ונכלל באור כללי אחד הכוללם יחד והוא כמו ספירה דאור החסד דאצי' שמסתעפי' ממנה חלקי אורו' וניצוצי' הרבה כמו חלק אור גבורה שבחסד שבחסד וכיוצא שזהו חלק אור קטן מאד אחר שכבר נחלק החסד לי' וגם החסד שבחסד נחלק לי' כו' וכיוצא בזה יש הרבה פרטים רבים וכולם נכללי' בספי' שהיא כוללת כולם יחד ונקראו בנות עד\"מ הכפרים שנק' בנות לגבי העיר כנ\"ל. ואמנם הנה בחי' מלכו' דאצי' איננה בחי' אור פרטי כשאר האורו' הפרטיים שנמשלו לכפרים גם אחר התלבשותן באותיו' שנק' בתים והיכלו' באצי' כו' אלא היא בחי' אור כללי דוקא הכולל כל האורו' הנמשכי' באצי' בכל פרטי פרטיהם אחר שהיא נק' בחי' מקבל כללי שמקבלת בתוכה כל ההשפעות וההמשכו' וכמ\"ש כל<sup data-n=\"5749\">12</sup> הנחלים הולכי' אל הים כו' וכמשל כלי הדיבור שמקבלת בתוכה כל השפעו' מן כל פרטי אור של השכל וגם של &lt;שפה&gt;\nהמדות שבלב כו' וכידוע וע\"כ אמר כן<sup data-n=\"5750\">13</sup> רעייתי בין הבנות וזה קאי על בחי' פנימי' כח הדיבור בעודנו מקבל מכח השכל עצמו שנק' רעייתי שנק' אחות לז\"א שהן המדו' כנודע ושם יש בנות רבות שמקבלים כולם מאורו' ומוחין דאו\"א ונק' אחים וריעים לז\"א וכמ\"ש למען<sup data-n=\"5751\">14</sup> אחיי וריעיי כו' וכמ\"ש במ\"א כמו נשמות הג' סבות ונשמת<sup data-n=\"5752\">15</sup> ר\"ע ורשב\"י שהיו מניצוצי משה כו', אבל מ\"מ את עלית על כולנה לפי שהמלכו' בחי' כוללת כל האורו' ואע\"פ שגם הבנות עשו חיל כו'.\n<b>וזהו</b> מ\"ש ששים<sup data-n=\"5753\">16</sup> המה מלכו' ושמונים פלגשים ועלמו' אין מספר שיש בחי' מלכו' שמקבלי' מאורו' דאו\"א תמיד ויש פלגשים שמקבלי' לעיתי' רחוקי' ויש עלמו' שאינן ראויין ליחוד עדיין כו' וכולם הם פרטי אורו' דאצי' ונק' בנות לגבי המל'",[["5746","9","<b>ושמתי אותם לך לבנות</b>: יחזקאל טז, סא — ונתתי אתהן לך לבנות."],["5747","10","<b>בנות ירושלים. . כפרים סביבותיה נקראו בנות</b>: ראה שה\"ש א, ה."],["5748","11","<b>בית שאן ובנותיה</b>: יהושע יז, יא."],["5749","12","<b>כל הנחלים הולכי' אל הים</b>: קהלת א, ז."],["5750","13","<b>כן רעייתי בין הבנות</b>: שה\"ש ב, ב."],["5751","14","<b>למען אחי ורעי</b>: תהלים קכב, ח."],["5752","15","<b>ונשמות ר\"ע ורשב\"י</b>: ראה תו\"ח שמות [הוצאת קה\"ת — תשס\"ג] צח, א."],["5753","16","<b>ששים המה מלכו' ושמונים פלגשים</b>: שה\"ש ו, ח."]]],[2100990406,"אחת היא כו' להיותה כנ\"ל אור הכללי הכוללם יחד וזהו כן רעייתי בין הבנות שעולה על כולנה ביופיה והדרה כו' כמשל השושנה בין החוחים כנ\"ל שהוא כאשר המל' מלובשת ומוסתרת בחיצוניו' העולמו' כמשל הדיבור שיוצא לחוץ ממש כך רעייתי שהוא בחי' פנימי' הדיבור שהוא בחי' מל' דתבונה כאשר מקבלת למעלה מאו\"א כו' בין הבנות שאר חלקי פרטי האורו' המסתעפי' שכולם נכללי' במלכו' דתבונה עד שנקראו רק בנותיה בלבד וכמ\"ש ושמתי לך לבנות כו' וכל זה למעלה הוא מפני שאת עלית על כולנה בבחי' הברורי' למטה כשהיתה שושנה בין החוחים כו' וכנ\"ל וד\"ל.\n<b>מה</b> שושנה אית בה סומק וחוור כו'. פי' ר' חזקיה בא לחדש עוד בפי' הפסוק הזה דרך כלל דסיבת היופי אשר ברעייתי למעלה להיו' כלולה מדין ורחמי שעי\"ז הוא עיקר היופי כמו שידוע דבחיבור מראה האודם והלובן דוקא אז הוא היופי וכמ\"ש הנך<sup data-n=\"5754\">17</sup> יפה רעייתי כו' אינו אלא מחמת בחי' הברורים דרפ\"ח כו' שמברר שם ב\"ן למטה בנוגה דבי\"ע כנ\"ל כשהיא שושנה בין החוחים כאשר נעשין בה ב' גוונין הללו דוקא סומק וחוור והוא כשמברר אותם בבחי' רצוא ושוב אוי\"ר כו' ודוקא כלולי' יחד ואזי גם למעלה במל' דאצי' כשעולה במעלה על כל הבנות בזאת היא בהיותה כלולה מדין ורחמי יחד שבזה הוא עיקר היופי משא\"כ בשאר בנות העליונות כמו ששים מלכו' ושמונים פלגשים כו' שאין בהם בחי' התכללו' זאת אלא רק בחי' פרט א' מחסדי' או מגבורו' כו', וזהו רבות בנות גם הם עשו חיל לברר אבל את עלית על כולנה לפי שיש בה סומק וחוור בהתכללו' כו' וזהו כמו ביאור על הפסוק למה אמר משל זה דכשושנה בין החוחים דוקא שהוא מטעם בחי' התכללו' דחו\"ג כו' וד\"ל.\n<b>מה</b> שושנה אית בה תליסר עלין אוף כנ\"י אית בה תליסר מכילן דרחמין דסחרין לה מכל סטרהא, אוף אלקים דהכא משעתא דאדכר אפיק תליסר תיבין לסחרא לכנ\"י ולנטרא לה, ע\"כ. פי' לפי שהזכיר תחלה בטעם המשל לשושנה שהוא מטעם בחי' היופי שבא מצד ההתכללו' חו\"ג כנ\"ל עתה חוזר לבאר שרש ענין בחי' היופי הזה שהוא בא ונמשך ממקום גבוה מאד &lt;שפו&gt;\nוהוא מבחי' יופי העליון דהארת פנים דא\"א דאצי' שמאיר בי\"ג מדה\"ר שהן נקראין בחי' עלין עד\"מ כי הנה המל'<sup data-n=\"5755\">18</sup> נק' אשה וכמ\"ש אשה יראת ה' כו' אשת<sup data-n=\"5756\">19</sup> חיל כו' וידוע מאמרם ז\"ל דאין<sup data-n=\"5757\">20</sup> אשה אלא ליופי וע\"כ גם מטבע האשה להיו' יפה יותר מן האיש כנראה בתולדה שלהם למטה והטעם הוא לפי שהאשה מדרגתה שפלה ונדבקי' בה פסולת רב כמו דמים הטמאי' וכמאמרם חמת<sup data-n=\"5758\">21</sup> מלא כו' ע\"כ צריכה היא יותר לבחי' היופי מן האיש כי מי שהוא יותר בחושך צריך להאיר לו אור גדול יותר כדי שלא יוחשך אורו ביותר כו' וכך הוא הנמשל למעלה מאחר דבחי' מל' דאצי' נק' אשה הרי אין אשה אלא ליופי כי",[["5754","17","<b>הנך יפה רעייתי</b>: שה\"ש א, טו. ד, א."],["5755","18","<b>המל' נק' אשה. . אשה יראת ה'</b>: משלי לא, א. וראה תו\"ח נח סב, ג הערה 17."],["5756","19","<b>אשת חיל</b>: משלי לא, יו\"ד."],["5757","20","<b>דאין אשה אלא ליופי</b>: ראה תענית לא, א."],["5758","21","<b>חמת מלא</b>: ראה שבת קנב, א."]]],[2100990407,"להיותה מסתתרת בבי\"ע ויונקים ממנה החיצונים מבחי' פסולת ה' דמי' טמאי' וכיוצא הי' אור שלה חשוך מאד מחשכת יניקו' החיצוני' ע\"כ צריכה להאיר לה מבחי' אור גדול ביותר ליפותה והיינו דוקא מבחי' יופי היותר עליון שהוא בחי' הארת פנים דא\"א כמו שנא' יאר<sup data-n=\"5759\">22</sup> ה' פניו אליך, אליך דוקא דהיינו לכנ\"י שהוא בחי' מל' דאצי' כידוע דכל<sup data-n=\"5760\">23</sup> ישראל בני מלכים הם כו' וד\"ל.\n<b>וזהו</b> ענין תליסר עלין דשושנה כי עד\"מ השושנה היא עצמה עומדת באמצע ויש בה סומק וחוור והעלין שלה עומדים מרחוק וסובבים אותה מכל צד לשומרה מכל דבר נזק וגם בסיבוב זה הנה היא מתייפה לעין כל רואה כו' כך למעלה בחי' תליסר מכילן דרחמי שמאירי' מי\"ג תקוני' דא\"א נקראו עלין עד\"מ להיות גורמי' תוספ' היופי בכנ\"י שהיא בחי' מלכות ולסחרא לה ולנטרה לה מיניקו' החיצוני' שלא יוחשך אורה כי צריכה לכך מטעם הנ\"ל ונעשין בחי' אורו' מקיפי' למלכו' לשומרה כו' וכמו העלין בשושנה שהמה שומרי' אותה מכל צד כו' כי בחי' המל' להיותה סופא דכל דרגין למעלה ונדבק בה בחי' פסולת דחיצוני' ע\"כ צריכה שמירה ביותר וע\"כ מבואר בע\"ח שיש למלכות דאצי' ז' מקיפי' יותר מז\"א כו' מטעם שצריכה שמירה ביותר והוא הטעם לענין היופי ג\"כ וכנ\"ל וד\"ל.\n<b>אוף</b> אלקים דהכא כו' פי' ענין הנ\"ל בהארת י\"ג מדה\"ר מא\"א למלכו' מצא לזה ראיה מבוארת בפ' ראשונה זו דבראשית<sup data-n=\"5761\">24</sup> ברא אלקי' כו' דהרי ידוע בב'<sup data-n=\"5762\">25</sup> ההי\"ן דשם הוי' ה\"א הראשונה היינו שם<sup data-n=\"5763\">26</sup> האחת שפרה שמשפרת<sup data-n=\"5764\">27</sup> את הולד כו' והוא שם<sup data-n=\"5765\">28</sup> הגדולה לאה כו' והיינו בחי' בינה<sup data-n=\"5766\">29</sup> שנק' אלקים חיים אלקי' עילאה והוא שכינתא עילא' כו' וה\"א אחרונה שכינתא תתא' והוא אלקי' תתא' כו' והוא בחי' דיבור שנק' פעו כו'.\n<b>וזהו</b> שאמר אוף אלקים דהכא פי' כי פי' בראשית<sup data-n=\"5767\">30</sup> הוא אור החכמה כתרגומו בחוכמתא וכידוע שהחכמה<sup data-n=\"5768\">31</sup> נק' ראשית ופי' אלקי'<sup data-n=\"5769\">32</sup> היינו בחי' בינה כידוע",[["5759","22","<b>יאר ה' פניו אליך</b>: נשא ו, כה."],["5760","23","<b>דכל ישראל בני מלכים הם</b>: שבת סז, א."],["5761","24","<b>דבראשית ברא אלקי'</b>: בראשית א, א."],["5762","25","<b>בב' ההי\"ן דשם הוי'</b>: ראה לקו\"ת צו טז, ג. מאמרי אדה\"ז הקצרים ע' כח. סה\"מ נביאים ע' קח. תו\"ח שמות [הוצאת קה\"ת — תשס\"ג] כה, ג-ד. לג, א. אוה\"ת שמות כרך ז ע' ב'תק ואילך. כרך ח ע' ב'תתמד ואילך."],["5763","26","<b>שם האחת שפרה</b>: שמות א, טו."],["5764","27","<b>שמשפרת את הולד</b>: סוטה יא, ב."],["5765","28","<b>שם הגדולה לאה</b>: ויצא כט, טז."],["5766","29","<b>בינה שנק' אלקים חיים</b>: ראה זהר יתרו סח, ב ובהגהות הרח\"ו שם. אור החמה שם. ע\"ח שער (כו) הצלם רפ\"ג. לקו\"ת להאריז\"ל ירמי' י, י. סידור האריז\"ל ומשנת חסידים ב [תפלת הבריאה פ\"ב מ\"א] בברכת יוצר."],["5767","30","<b>בראשית. . כתרגומו בחוכמתא</b>: בראשית א, א. וראה תרגום ירושלמי שם."],["5768","31","<b>שהחכמה נק' ראשית</b>: ראה זהר בראשית לא, רע\"ב."],["5769","32","<b>אלקי'. . בחי' בינה</b>: ראה זהר בהקדמה ב, א. ובמקדש מלך שם. בראשית כב, א (תוספתא) בראשית לא, ב."]]],[2100990408,"דחו\"ב<sup data-n=\"5770\">33</sup> נק' תרין ריעין כו' ואבא<sup data-n=\"5771\">34</sup> אמר לאימא כמ\"ש בזוהר והיינו בראשית דחכמה ברא אלקי' בחי' בינה כו' והנה מאלקים זה עד אלקים תניינא שהוא ורוח<sup data-n=\"5772\">35</sup> אלקי' מרחפת כו' יש י\"ג<sup data-n=\"5773\">36</sup> תיבות כידוע והיינו י\"ג מדה\"ר שמאירי' מא\"א דרך בחי' אור הבינה דוקא והוא בחי' אלקי' קדמא' כדי להביא לה תוס' אור ויופי כו' כנ\"ל, והיינו שאמר שיש ראי' לענין הנ\"ל מענין י\"ג תיבו' דאפיק משעתא דאדכר ה\"א עילא' שהוא אלקי' עילא' דבינה עד אלקי' תניינא כו' כדי לסחרא לה ולנטרא לה כו' כשתצטרך לבא בירידו' המדרגו' להתלבש בדיבור בי' מאמרו' וכנ\"ל הטעם וד\"ל.\n&lt;שפז&gt;\n<b>ולבתר</b> אדכר זמנא אוחרא אמאי אדכר זמנא אחרא בגין חמש עלין תקיפין דסחרין לשושנה, ואינון חמש אקרון ישועות ואינון חמש תרעין וע\"ד כתיב כוס<sup data-n=\"5774\">37</sup> ישועות אשא דא כוס דאצטרך למהוי על חמש אצבען ולא יתיר, כגוונא דשושנה דיתבא על חמש עלין תקיפין דוגמא דה' אצבען ושושנה איהי כוס של ברכה ע\"כ. פי' חמש עלין תקיפין הן בחי' ה\"ג דשם אלקים שבמלכו' ולכך נק' עלין תקיפין מתוקף הגבורות ואינון חמש אקרון ישועות פי' ישועות כולל ב' עניני' א' מבחי' החסדי' כידוע שכל ישועה ע\"י אור החסד בא והב' מבחי' הגבורו' ג\"כ להיות כי הישועה צריך להיו' בה בחי' תוקף ועוז להושיע מבחי' המנגד והוא בחי' גבורה שבחסד כו'. וביאור הדברים הנה ידוע דיש במלכו' בחי' ה\"ג אשר לצורך בנינה ויש בה בחי' ה\"ג אשר לצורך עצמה, ותחלה יש לבאר ענין ה\"ג שלצורך בנינה דהנה כתיב אף<sup data-n=\"5775\">38</sup> ידי יסדה ארץ וידוע פי' ידי היינו בחי' ה'<sup data-n=\"5776\">39</sup> אצבעות שביד שהן בחי' ה\"ג שבחסד כי הנה עד\"מ היד הגשמי שרשה בעצם הוא מבחי' החסד כי היד פושטת להחיו'<sup data-n=\"5777\">40</sup> רוח שפלים בצדקה לעני וכיוצא וגם בפעולת היד הנה פועלת כל מעשה, אך הנה הכח שיש ביד הוא כח כללי ולא הי' מסתעף ממנה פעולה פרטית אם לא ע\"י האצבעות שמחלקות כחות היד עד שיכול לפעול פעולה פרטית כנרא' לעין שעיקר חלקי הפעולה באה ע\"י חלקי האצבעו' שמגבילי' כח הפעולה הכללית שביד וע\"כ הן נק' בחי' הגבורו' והצמצום כי מחלקי' ומצמצמי' הפעולה כו'.\n<b>והנמשל</b> יובן למעלה ביד העליון כמו דכתיב אף ידי יסדה כו' דהיינו בחי' חסד כללי להשפיע השפעה כללית וכמ\"ש כי<sup data-n=\"5778\">41</sup> אמרתי עולם חסד יבנה כו' ואעפ\"כ עיקר בנין<sup data-n=\"5779\">42</sup> המל' מבחי' הגבורו' כידוע והיינו מבחי' ה\"ג שבחסד זה והן",[["5770","33","<b>דחו\"ב נק' תרין ריעין</b>: ראה זהר בשלח נו, א. ויקרא ד, א. ובאור החמה לשם. לקו\"ת פר' ראה יח, ב."],["5771","34","<b>ואבא אמר לאימא</b>: ראה זהר בראשית כב, א."],["5772","35","<b>ורוח אלקי' מרחפת</b>: בראשית א, ב."],["5773","36","<b>י\"ג תיבות. . י\"ג מדה\"ר</b>: ראה יהל אור ע' תרכו ואילך."],["5774","37","<b>כוס ישועות אשא</b>: תהלים קטז, יג."],["5775","38","<b>אף ידי יסדה ארץ</b>: ישעי' מח, יג."],["5776","39","<b>ה' אצבעות שביד שהן בחי' ה\"ג שבחסד</b>: ראה דרך מצותיך סג, ב. המשך תער\"ב ע' א'תטו."],["5777","40","<b>להחיו' רוח שפלים</b>: ישעי' נז, טו."],["5778","41","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["5779","42","<b>בנין המל' מבחי' הגבורו'</b>: ראה סידור שחרית מא, א: כמ\"ש בע\"ח בענין הדלקת נרות המנורה [שער תיקון הנוקבא — של\"ד, פ\"ה]. סה\"מ תרמ\"ו ע' יו\"ד: וכמ\"ש בהקדמת הזהר בתחלתו במק\"מ שם."]]],[2100990409,"בחי' ה' אצבעות שביד המחלקו' החסד ומגבילי' כח הפועל האלקי לבא בריבוי התחלקות עד אין קץ כו' וד\"ל. ונמצא שיש בהגבלה זו של האצבעות מבחי' הגבורו' ומבחי' החסדי' יחד שהרי הגבלה זאת לצורך המקבל היא כדי שיוכל לבא אור השפע בכח מיוחד כנ\"ל והוא חסד גדול וע\"כ נק' בחי' גבורה שבחסד וכמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> ענין ה\"ג שלצורך בנינה והן ענין ה' אצבען שכוס של ברכה מונח עליהן כמו שאמר כאן כוס של ברכה דאצטריך למהוי על ה' אצבען ולא יתיר כו' וידוע דכוס של ברכה היינו בחי' מל'<sup data-n=\"5780\">43</sup> דאצי' שנק' כוס כמ\"ש כוסי<sup data-n=\"5781\">44</sup> רויה ואמרו ז\"ל כסא<sup data-n=\"5782\">45</sup> דמלכא משיחא כו', ולהיו' כי עיקר בנין המל' בעולמות הוא מבחי' ה\"ג של ה' אצבעו' היד כנ\"ל ע\"כ אמר דכוס של ברכה אצטריך למהוי על ה' אצבען כו' וד\"ל.\n<b>אך</b> עדיין יש להבין מהו ענין כוס של ברכה עצמו ומהו ענין ישיבתו על ה' האצבעות דוקא כו'. הענין הוא לפי שיש עוד בחי' ה\"ג במל' עצמה שלמעלה מבחי' ה\"ג שלצורך בנינה הנ\"ל והיינו בבחי' מל' דאצי' כמו שהיא בבחי' האצי' עדיין שמקבלת כל האור ושפע דאצי' וכמ\"ש כל<sup data-n=\"5783\">46</sup> הנחלים הולכי' אל הים כו' ואז נקראת כוס של ברכה פי' עד\"מ הכוס יש בו בית קיבול בחללו שיכנס בו היין כך למעלה היין עצמו הוא בחי' המוחי' דאו\"א שנמשכין למלכו' ולכך נק' כום של ברכה שמקבלת בתוכה כל הברכו' וההמשכו' מוחין כו' וד\"ל אך כדי שיהי' בה בחי' בית &lt;שפח&gt;\nקיבול לקבל הרבה צריך לעשות בה בחי' החלל והן בחי' ה\"ג המצמצמי' בעצמותה להיו' בה בחי' בית קיבול בחלל רחב והיינו בחי' ה\"ג שביסוד כו' שע\"ז נא' ואל<sup data-n=\"5784\">47</sup> אישך תשוקתך כו' והיינו בחי' ה\"ג לצורך עצמה אמנם כדי שלא ינקו החיצוני' מקבלת אור שפעה לכך צריך להניח כוס של ברכה על ה' האצבעו' שהן בחי' גבורה שבחסד המצמצמי' ומגבילי' האור כנ\"ל כדי להכניע החיצוני' שלא יקרבו גם הם לקבל והן ה' העלין דשושנה יתבא עליהן כמו שאמר כגוונא דשושנה דיתבא על ה' עלין תקיפין דוגמא דה' אצבען ושושנה איהי כוס של ברכה פי' שושנה עצמה היא בחי' מל' דאצי' עצמה ובהיותה מלובשת בבי\"ע נק' שושנה בין החוחים כנ\"ל ויתבא על ה' עלין תקיפין היינו בחי' ה\"ג שבחסד דוגמא דה' אצבען ושושנה עצמה נק' כו\"ס של ברכה שמקבלת השפע בעצמותה כנ\"ל ומה שיושבת על ה' עלין תקיפין היינו לשומרה מן החיצונים כנ\"ל והיינו שאמר בתחלת המאמר אמאי אדכר זמנא אוחרא בגין לאפקא ה' עלין תקיפין דסחרין לשושנה פי' אלקים תניינא הוא ג\"כ מבחי' בינה שמוציא' בחי' ה\"ג מנצפ\"ך בשביל בנין הנוקבא וכמאמר הידוע דאימא אוזיפת מאנהא לברתא וכמ\"ש במ\"א וד\"ל.",[["5780","43","<b>מלכות דאצילות שנק' כוס</b>: ראה פרדס (שער ערה\"כ) שכ\"ג, מערכת כוס."],["5781","44","<b>כוסי רויה</b>: תהלים כג, ה."],["5782","45","<b>כסא דמלכא משיחא</b>: ראה יומא עו, א. סידור שחרית נב, ב. תו\"א תולדות יח, סע\"ד ואילך."],["5783","46","<b>כל הנחלים הולכי' אל הים</b>: קהלת א, ז."],["5784","47","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."]]],[2100990410,"<b>ואינון</b> חמש אקרון ישועו' ואינון ה' תרעין פי' נ' שערים דבינה יש בהן בחי' ה\"ח כלליים וה\"ג כלליים ומבחי' ה\"ג וה\"ח הללו נמשך למל' ה\"ג שבחסד הנ\"ל ואקרון ישועו' לכלול ב' ענינים א' מבחי' חסד כי הקבלה שלהם לצורך שפע המקבלי' היא כנ\"ל והב' מבחי' הגבורו' להכניע החיצונים כנ\"ל כי כל ישועה הוא מסתעף מתוקף ועוז להציל מבחי' המנגד כנ\"ל והיינו שאמר וע\"ד כתיב כוס ישועות דא כוס של ברכה דאצטריך למהוי על ה' אצבען וכנ\"ל וד\"ל.\n<b>מאלקים</b> תניינא עד אלקים תליתאה חמש תיבין מכאן ולהלאה אור דאתברי ואתגניז ואתכליל בברית ההוא דעאל בשושנה דא ואפיק בה זרעא ודא אקרי עץ עושה פרי אשר זרעו בו כו'. הנה תחלה דיבר בה' גבורו' דנוקבא שבבחי' יסוד דנוק' ועתה מדבר בבחי' ה' חסדי' דביסוד דדכורא והיינו ה' תיבין דמאלקי' תניינא עד אלקי' תליתאה שהן בפסוק ויאמר<sup data-n=\"5785\">48</sup> אלקים יהי אור ויהי אור ויאמר אלקי' כו' דאור זה מיירי באור החסד דדכורא כמ\"ש כי<sup data-n=\"5786\">49</sup> זכר חסדו בחי' דכר עוזרו הוא מבחי' החסדי' והן ה' חסדי' כוללי' מ\"ד דז\"א והיינו יהי אור ויהי אור כו' וכולם נשפעים ונכללי' ביסוד שנק' ברית ונק' עץ<sup data-n=\"5787\">50</sup> עושה פרי כו'.\n<b>אך</b> הנה מה שאמר מכאן ולהלאה אור דאתברי ואתגניז ואתכליל כו' ענין כפל הלשון ואתברי ואתכליל כו' וגם ענין אמרו ואתגניז דאחר שנברא נגנז ואח\"כ אתכליל בברית כו', הנה זה יובן בהקדים תחלה המשל והדוגמא לזה מהשפעת זרע זכר בגשמיו' דהנה אמרו לובן<sup data-n=\"5788\">51</sup> שממנו העצמו' כו' דהזרע זכר נקרא לובן לפי שיוצא ונמשך טפת הזרע דרך הלובן שבעצמות כי מבואר בספרי הרפואה שיש גידי' דקים בעצמו' ששרשם נמשך מן המוחין שבראש וידוע שהן גידי ההרגשה שבמוח שמתפשטים בעצמות דוקא כי המוח שבראש הוא שרש המוח שבכל עצם כו' וכמ\"ש<sup data-n=\"5789\">52</sup> במ\"א ולכך כאשר טפת הזרע נמשכת מן המוח שבראש אזי מתפשטת &lt;שפט&gt;\nונמשכת בכל העצמות ג\"כ ע\"י המוח שבעצמו' ואותה הטפה הגם שהולכת דרך חוט השדרה אבל נרגשת היא דרך הילוכה בכל העצמות הקשורי' בח\"י חוליות השדרה כנראה בחוש והיינו מטעם הגידי' הדקים שבעצמות שמתפשטי' מן המוח שבראש כנ\"ל וד\"ל. ולזה הטעם נק' לובן לפי שנמשך דרך גידי העצמות שהן לבינים.\n<b>והנה</b> בירידת טפת הזרע מן המוח בגידי העצמות מחמת זה נרגש הרגשת הילוך שפע הזרע בכל איברי הגוף הרגשה גדולה ביותר מכל מיני הרגשה הנמצאים באיברי הגוף מטעם שהוא מתקשר מן המוח המתקשר בכל העצמות וזהו שאמרו בזוהר דביחוד וזיווג יש הארות והשפעות כוללות מכל האיברים כו' והיינו משום דכל שייפין נמשך בהן ג\"כ הארת עונג מירידת אור זה בירידת דרך גידי'",[["5785","48","<b>ויאמר אלקים יהי אור</b>: בראשית א, ג."],["5786","49","<b>כי זכר חסדו</b>: תהלים צח, ג."],["5787","50","<b>עץ עושה פרי</b>: בראשית א, יב."],["5788","51","<b>לובן שממנו העצמו'</b>: ראה נדה לא, א."],["5789","52","<b>וכמ\"ש במ\"א</b>: ראה תו\"א ח\"ש טז, ג."]]],[2100990411,"שבעצמות אך הנה בירידת טפת הזרע הנה הוא מתלבש ונעלם בתכלית ההעלם ונעשה לובן רוחני ודק כלובן הדק שיש בגידי העצמו' שקשורי' בח\"י חוליות ובבואו לכליות המבשלות הזרע והם מתפשטים למטה מהיסוד דהיינו לגידי ביצים שם מתבשלת הזרע ממש ומתחממת ויוצאת אבל בהיותה בחוליות עדיין לא היתה בהרגשת החימום כ\"כ לפי שמובלעת היא ונעלמת בתוך הגידי' שבעצמו' כנ\"ל ונמצא יצאה מן ההעלם לגילוי כו' וכך יובן בזיווג ויחוד הרוחני בה' חסדי' דמ\"ד דז\"א שאחר יציאתם ממקורם ממוחי' דז\"א מיד נעלמים הם ונכללי' בחלקי המוחין שבעצמו' ואח\"כ יוצאי' בגילוי ביסוד שנק' ברית והיינו שאמר אור דאתברי ואתגניז ואתכלל בברית פי' דאתברי במוחי' שבראש ואתגניז בעברו דרך העצמות שנעלם ונבלע בהן כנ\"ל ואח\"כ חוזר ובא לידי גילוי ואתכליל בברית שנק' יסוד ואפיק זרעא ונק' עץ עושה פרי אשר זרעו בו כו' וד\"ל.\n<b>וכמה</b> דדיוקנא דברית אזדרע במ\"ב זווגין כך אזדרע שמא גליפא במ\"ב אתוון כעובדא דבראשית. פי' התחלקו' טפת הזרע מתחלקת היא ביציאתה ברחם הנוקבא כנ\"ל והתחלקו' זאת הוא ע\"י שם<sup data-n=\"5790\">53</sup> מ\"ב שהוא מבחי' הגבורו' כמבואר במ\"א והיינו כמו עובדא דבראשית שהן ל\"ב פעמי' ויאמר אלקי' שהוא בחי' התחלקו' אור השפע מה' חסדי' דדכורא הנ\"ל והיינו שאמר כך אזדרע שמא גליפא במ\"ב אתוון כעובדא דבראשית וד\"ל.",[["5790","53","<b>שם מ\"ב. . הגבורו'</b>: ראה זהר תרומה קלב, ב."]]],[2101000027,"<h3>מים רבים</h3>\n<b>בעזר\"ה</b>\n<b>מים</b><sup data-n=\"1\">1</sup> רבים לא יוכלו לכבות את האהבה<sup data-n=\"2\">2</sup> ונהרות לא ישטפוה, אם יתן איש את כל הון ביתו באהבה בוז יבוזו לו כו'. הנה ידוע שהנהרות נובעין מן התהום ע\"י אמצעות המעיינות דוקא דהיינו שהמעיינות נובעין מן התהום ממש ומן המעיינות נמשכו הנהרות, והכתובי' המעידי' ע\"ז הנה כתיב במי המבול מעיינות<sup data-n=\"3\">3</sup> תהום רבה נבקעו הרי המעיינות נובעין ונבקעי' מן התהום וכתיב המשלח<sup data-n=\"4\">4</sup> מעיינים בנחלים כו' והנחלים<sup data-n=\"5\">5</sup> הולכים אל הים כו', והנה ע\"י אמצעות המעיינות והנחלים נמשך מי התהום ומתקבץ בימים אך הנה המעיינות עדיין המה מכוסים ונעלמים בארץ כמארז\"ל ארעא<sup data-n=\"6\">6</sup> חלחולי מחלחלא כו' והן גידי המעיינות שנובעין בהעלם גדול מתחת לארץ אבל הנהרות הן הנמשכים בגילוי ע\"פ כל הארץ כו'. וכמ\"כ יובן למעלה דהנה בחי' חכ' שבתורה נק' מים כמ\"ש הוי<sup data-n=\"7\">7</sup> כל צמא לכו למים כו' ואין<sup data-n=\"8\">8</sup> מים אלא תורה, וידוע דאוריי'<sup data-n=\"9\">9</sup> מח\"ע נפקת, ובבחי' החכ' יש ב' מדריגות הא' בחי' חכ' הנעלמה שאינה מושגת כלל (ונק'<sup data-n=\"10\">10</sup> בפרד\"ס שכל הנעלם מכל רעיון והוא הנק' בזוהר בשם ח\"ס) והיינו כמא' חכים<sup data-n=\"11\">11</sup> ולא בחכ' ידיע' כלל שאינו מושג במקבלי' לא בנאצלים ולא נבראים כו' והוא בחי' החכ' הכלולה בא\"ס עצמו דהוא<sup data-n=\"12\">12</sup> המדע והוא הידוע כו' וכמשל הנפש המשכלת שכח השכל כלול בעצם הנפש כידוע, וזהו פי' מים רבים כי לשון רבים הוא אשר אין למים סוף כלל והוא בחי' חכ' דא\"ס שהוא בבחי' א\"ס ממש כי הוא המדע כו' וכמ\"ש לתבונתו<sup data-n=\"13\">13</sup> אין חקר וגם בחי' המים רבים",[["1","1","<b>מים רבים</b>: נדפס בשינויים בתו\"א תולדות יז, ד. וראה עוד על נוסחאות המאמר וזמן אמירתו, להלן ברשימת הכת\"י."],["2","2","<b>מים רבים לא יוכלו לכבות את האהבה</b>: שה\"ש ח, ז."],["3","3","<b>מעיינות תהום רבה נבקעו</b>: ראה בראשית ז, יא."],["4","4","<b>המשלח מעיינות בנחלים</b>: ראה תהלים קד, י. וראה זח\"ג קפא, א."],["5","5","<b>והנחלים הולכים אל הים</b>: ראה קהלת א, ז."],["6","6","<b>ארעא חלחולי מחלחלא</b>: חגיגה כב, א."],["7","7","<b>הוי כל צמא לכו למים</b>: ישעי' נה, א."],["8","8","<b>ואין מים אלא תורה</b>: ב\"ק יז, א."],["9","9","<b>דאוריי' מח\"ע נפקת</b>: זח\"ב פה, א. קכא, א."],["10","10","<b>ונק' בפרדס שכל הנעלם מכל רעיון</b>: ראה שער הנתיבות רפ\"ג. וראה אוה\"ת לך לך כרך ד' תרפה, א."],["11","11","<b>חכים ולא בחכמה ידיעא</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."],["12","12","<b>דהוא המדע והוא הידוע</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ב ה\"י, מו\"נ ח\"א פס\"ח. שמונה פרקים פ\"ח. תניא פ\"ב ובליקוט פירושים ומ\"מ שם."],["13","13","<b>לתבונתו אין חקר</b>: ראה ישעי' מ, כח."]]],[2101000028,"הללו הן בבחי' ההעלם בלתי גילוי כלל וכמ\"ש ולא בחכ' ידיע' והיינו כמו משל ענין המעיינות דתהום רבה שנבקעים מן התהום כנ\"ל שנובעים בהעלם גדול ונובעים בלי שיעור וגבול ע\"ד שאמר ומעיינות תהום רבה נבקעו כו' אבל בחי' הנהרות הן הנובעי' ונמשכים בגילוי ובאין במדה ושיעור מן המעיינות וכמ\"ש המשלח מעיינים בנחלים כו' וכן ונהר<sup data-n=\"14\">14</sup> יוצא מעדן כו' והוא בחי' בינה שנמשכת מן החכמה שנק' עדן ונק' מעיין כידוע והיינו בחי' ההשגה וההבנה באור א\"ס כמו הנשמו' שנהנין מזיו כו' שמשיגין אוא\"ס והוא בחי' יש מאין כי החכ' נק' אין וכמ\"ש והחכ'<sup data-n=\"15\">15</sup> מאין כו' והבינה נק' יש כמ\"ש להנחיל<sup data-n=\"16\">16</sup> אוהבי יש ש\"י עולמות כו' כידוע וד\"ל, וזהו מים רבים דחכ' עילאה לא יוכלו לכבות את האהבה וגם בחי' נהרות הנ\"ל לא ישטפוה כו', אך י\"ל תחלה מהו בחי' האהבה הזאת ומהו עוצם מעלתה עד שמים רבים ונהרות כו'.\n<b>וי\"ל</b> תחלה מ\"ש ברבקה ותרד<sup data-n=\"17\">17</sup> העיינה ותמלא כדה ותעל וידוע ומבואר במ\"א דבחי'<sup data-n=\"18\">18</sup> עין זה הוא בחי' ח\"ע חכים ולא בחכ' ידיע' הנ\"ל ופי'<sup data-n=\"19\">19</sup> ותמלא כדה היינו כ\"ד ספרים דאוריי' משום דאוריי' מח\"ע נפקת כנ\"ל ורבקה ירדה בבחי' ח\"ע שהוא הנק' העיינה ותמלא משם כ\"ד ספרי' דאוריי' כמו עד\"מ מי ששואב בכד קטן מים הגדול כו', וא\"כ י\"ל מהו בחי' רבקה שנאמר בה ותרד העיינה כו', והנה תחלה י\"ל שרש בחי' יצחק ואח\"כ יובן בחי' רבקה כו' דהנה פי' יצחק הוא ענין תענוג ושעשועי' גדולים כמו הצחוק והשחוק שעושה תענוג גדול ולכך נק' יצחק כמ\"ש צחוק<sup data-n=\"20\">20</sup> עשה לנו האלקים כל השומע יצחק לי כו'.\n<b>והענין</b> הוא כי הנה פי' יצחק לשון עתיד הוא שעתיד לצחק כי היוד משמש על להבא כידוע והענין הוא למעלה משום דעיקר התענוג העליון של המאציל יהי' לעתיד דוקא דהיינו אחר שיתא אלפי שני דהווה עלמא שיושלמו כל הבירורי' דרפ\"ח ניצוצין כו' אבל עכשיו עדיין לא נבררו ואין הצחוק למעלה בשלימות עדיין, והטעם שנק' בחי' הבירורי' בשם צחוק היינו כמ\"ש צחוק עשה לנו האלקים שהוא בחי' שם ב\"ן שנק' אלקים הוא העושה בחי' הצחוק העליון כו', והענין הוא כידוע בפי' כי<sup data-n=\"21\">21</sup> שמש ומגן ה' אלקי' כמשל גופו של מאור השמש עם הזיו שמן הנרתק שהרי הזיו של השמש הוא בטל ונכלל במאור ומה שנראה לבחי' יש ודבר בפ\"ע היינו",[["14","14","<b>ונהר יוצא מעדן והוא בחי' בינה</b>: בראשית ב, י. זח\"ב קכג, ב. ובכ\"מ."],["15","15","<b>והחכ' מאין</b>: איוב כח, יב."],["16","16","<b>להנחיל אוהבי יש ש\"י עולמות</b>: משלי ח, כא. סוף עוקצין."],["17","17","<b>ותרד העיינה ותמלא כדה ותעל</b>: בראשית כד, טז. ובהבא להלן ראה בארוכה תו\"ח ח\"ש קכז, ג ואילך. וראה לקו\"ת ברכה צו, ג. אוה\"ת נ\"ך ע' יח."],["18","18","<b>דבחי' עין זה הוא בחי' ח\"ע</b>: ראה ג\"כ אוה\"ת דרושים ליוהכ\"פ ע' א'תקצח."],["19","19","<b>ופי' ותמלא כדה היינו כ\"ד ספרים דאורייתא</b>: ראה ת\"ז תכ\"א (מו, ב). אוה\"ת בראשית מח, א."],["20","20","<b>צחוק עשה לנו האלקים</b>: ראה בראשית כא, ו."],["21","21","<b>כי שמש ומגן ה' אלקי'</b>: תהלים פד, יב. וראה שער היחוה\"א פ\"ג ואילך. תו\"א בראשית ד, ד ואילך."]]],[2101000029,"ע\"י הנרתק שמבדיל בפני השמש כמו הזכוכי' הבהירה שע\"י יבהיק האור ובלעדה לא הי' נראה אור כלל כו', וככה יובן למשכיל למעלה בבחי' זיו ואור עליון האלקי שהוא ע\"י בחי' שם אלקי' המסתיר ומבדיל בפני שם הוי' שנמשל לשמש עצמו כו' ואם לאו הי' בחי' הזיו הזה נכלל במאור עצמו שהוא שם הוי' כו' (וע\"כ לעתיד דכתיב ונגלה<sup data-n=\"22\">22</sup> כבוד הוי' ארז\"ל שעתיד<sup data-n=\"23\">23</sup> הקב\"ה להוציא חמה מנרתקה כו' וכמ\"ש במ\"א) וזהו בחי' מדת מל' דאצי' שמחי' כל הנבראים מאין ליש ממש בבחי' גבול וכמ\"ש מלכה\"כ<sup data-n=\"24\">24</sup> ותרגום כבודו זיו יקרי' כו' וע\"ז נאמר כי<sup data-n=\"25\">25</sup> עמך מקור חיים באורך נראה אור פי' באורך העצמי שהוא שם הוי' שנמשל לשמש כנ\"ל נראה אור וזיו ע\"י אמצעו' שם אלקים שהוא כמו הנרתק לשם הוי' כנ\"ל וא\"כ ה\"ז אור<sup data-n=\"26\">26</sup> של תולדה כמו האור הנראה מתוך המסך המסתיר לעצם האור כו' וע\"כ יכול להיות נבראי' בבחי' נפרד ממש וא\"כ עיקר סיבת התהוות מאין ליש נפרד הוא ע\"י שם אלקים דוקא כנ\"ל וע\"כ בהתהפכו'<sup data-n=\"27\">27</sup> חשוכא לנהורא ומרירו למיתקא שהוא ענין ובחי' הבירורי' הנ\"ל והיינו בחי' ביטול היש לאין וכמו וצבא<sup data-n=\"28\">28</sup> השמים לך משתחווים או ע\"י מס\"נ בתפלה ותשובה וכה\"ג ע\"י תומ\"צ שהוא עיקר הבירורי' דרפ\"ח כו' כידוע אזי נעשה עי\"ז למעלה בחי' צחוק ותענוג גדול כי הרי זהו היפך ההשתלשלו' מאין ליש, ומה שבתחלה העלים וצמצם האור העצמי דשם הוי' ע\"י שם אלקים כדי שיוכל להיות התהוות<sup data-n=\"29\">29</sup> נבראים מאין ליש כנ\"ל היינו רק כדי שיהי' אח\"כ בחי' ביטול היש לאין בהיפוך חשוכא לנהורא כו' וה\"ז ממש כמו עד<sup data-n=\"30\">30</sup>\"מ הצחוק שעושין לפני המלך לעשות דברים להיו' כפלא כו' (וגם כאן הרי ממך<sup data-n=\"31\">31</sup> הכל כתיב והוא עשה הצמצום כדי שיהי' אח\"כ בחי' ביטול היש כדבר פלא כו' וע\"ד המבואר<sup data-n=\"32\">32</sup> במ\"א בענין הקניגי שעתיד הקב\"ה לעשות לצדיקים בעוה\"ב כו') וזהו מ\"ש צחוק עשה לנו האלקים דוקא שהוא שם אלקים המסתיר לשם הוי' כדי שיהי' מאין ליש (ואח\"כ בגילוי שם אלקים שהוא בחי' המל' בבי\"ע מתבררי' ונכללים בה כנר בפני האבוקה כו' והוא ענין הבירורי' דשם<sup data-n=\"33\">*32</sup> ב\"ן מברר כידוע) ומה שנק' יצחק ל' עתיד לפי שלעתיד יושלמו כל הבירורי' בהיפוך חשוכא לנהורא וז\"ש כל<sup data-n=\"34\">33</sup> השומע יצחק לי כו' וד\"ל.",[["22","22","<b>ונגלה כבוד ה'</b>: ישעי' מ, ה."],["23","23","<b>שעתיד הקב\"ה להוציא חמה מנרתקה</b>: ראה נדרים ח, ב. ע\"ז ג, ב. וראה ג\"כ או\"ת (להה\"מ) הוצאת קה\"ת כו, א. עד, א. אוה\"ת תרומה ע' א'תמט. ובכ\"מ."],["24","24","<b>מלא כל הארץ כבודו</b>: ישעי' ו, ג."],["25","25","<b>כי עמך מקור חיים</b>: תהלים לו, י."],["26","26","<b>אור של תולדה</b>: ראה תו\"א לך לך יב, ב. וירא יד, ג. ביאוה\"ז לאדהאמ\"צ יז, א. ובכ\"מ."],["27","27","<b>בהתהפכו' חשוכא לנהורא ומרירו למיתקא</b>: ראה זח\"א ד, א. ובכ\"מ."],["28","28","<b>וצבא השמים לך משתחוים</b>: נחמי' ט, ו."],["29","29","<b>התהוות נבראים. . כדי שיהי' אח\"כ בחי' ביטול היש לאין</b>: ראה ג\"כ תו\"א שמות נד, ב. לקו\"ת אמור לז, א. פינחס עז, ג. דרושים לש\"ש סז, ב. אוה\"ת בא ע' רנה. ובכ\"מ."],["30","30","<b>עד\"מ הצחוק שעושין לפני המלך</b>: ראה ג\"כ לקו\"ת במדבר כ, א."],["31","31","<b>ממך הכל</b>: דה\"א כט, יד."],["32","32","<b>המבואר במ\"א בענין הקניגי</b>: ויק\"ר פי\"ג, ג. וראה ד\"ה ויתן לך בסה\"מ תקס\"ב ע' צה ובתו\"ח ואוה\"ת ס\"פ תולדות. לקו\"ת שמיני יח, א. וראה לקו\"ש חי\"ב ע' 177."],["33","*32","<b>דשם ב\"ן מברר</b>: כ\"ה בהכת\"י. ראה גם להלן ע' פ."],["34","33","<b>כל השומע יצחק לי</b>: בראשית כא, ו."]]],[2101000030,"<b>והנה</b> ביצחק כתיב והנה<sup data-n=\"35\">34</sup> יצחק מצחק את רבקה אשתו פי' כל בחי' הצחוק דיצחק הנ\"ל הוא ע\"י שמצחק את רבקה אשתו כי עיקר בחי' צחוק ותענוג העליון מכל הבירורי' דרפ\"ח כו' כנ\"ל הוא ע\"י בחי' רבקה דוקא. וביאור הדברי' הנה פי' רבקה הוא בחי' חיבור וקשר של ג' או ד' יחד כמ\"ש במשנה שתי<sup data-n=\"36\">35</sup> רבקות של שלש שלש בקר או של ארבע בקר כו' כי חיבור וקשר שלש או ד' בקר יחד נק' רבקה של בקר והיינו שאמרו משנכנסו<sup data-n=\"37\">36</sup> לרבקה כו' והענין הוא למעלה בבחי' מרכבה העליונה דפני<sup data-n=\"38\">37</sup> ארי' להימין ופני השור מהשמאל כו' בבחי' קישור וחיבור של המרכבה מג' או ד' יחד נק' רבקה דהיינו בחי' היחוד וההתכללות שלהם מצד בחי' הביטול שיש בהם לפני בוראם המהווה אותם מאין ליש והוא בחי' המל'<sup data-n=\"39\">38</sup> שנק' כסא וכמא'<sup data-n=\"40\">39</sup> והחיות נושאות את הכסא פי' כסא הוא בחי' המל' שמחי' כל העולמות שהוא בחי' שם אלקי' הנ\"ל ונק' כסא כ\"ס א' לשון כיסוי והסתר כנ\"ל ששם אלקים מסתיר על שם הוי' אך מ\"מ נק' כסא הוי' ונק' כסא הכבוד כידוע והמרכבה העליונה שמתאחדי' ומתחברי' כולם יחד בתכלי' האחדות וההתכללות גם שיש בהן שני הפכים כארי' ושור כו' (וע\"כ יש רבקה של שלש והן ג' מדריגות שיש בכל א' כמו פני ארי' שהוא בחי' חסד כלול מג'<sup data-n=\"41\">40</sup> וכמ\"ש בי\"ב בקר שתחת ים של שלמה שהוא ג\"כ ענין המרכבה כידוע ששלשה<sup data-n=\"42\">41</sup> פונים תימנה כו' וכמ\"ש<sup data-n=\"43\">42</sup> בזהר בהיכלות דפ' פקודי ויש רבקה של ד' חיות כו') וענין האחדות שלהם מפני בחי' הביטול רצון שלהם שכולם מתבטלים ממציאותם ואין להם רצון אחר שיהיו מחולקים זה באופן כך וזה באופן כך ועי\"ז נושאות את הכסא יחד כאיש א' כו' וכמ\"כ האבות<sup data-n=\"44\">43</sup> הן המרכבה למעלה גם שהן ב' הפכי' אוי\"ר כולם מתאחדי' יחד כו' וכך גם למטה בכנ<sup data-n=\"45\">44</sup>\"י בגופים להיות ביטול רצון הנפש הבהמי' ששרשה מבחי' פני שור כו' כאשר מתאחדי' כולם בבחי' ביטול רצון א' נק' רבקה של בקר כו' והוא בחי' ביטול היש לאין כנ\"ל שמזה נעשה בחי' צחוק ותענוג העליון כנ\"ל וד\"ל, וזהו יצחק מצחק את רבקה אשתו פי' מה שיצחק מצחק בבחי' צחוק העליון הנ\"ל הוא ע\"י בחי' רבקה אשתו שהוא בחי' ביטול היש לאין שבבחי' מרכבה העליונה כנ\"ל מזה נעשה בחי' צחוק ותענוג העליון כנ\"ל וד\"ל. וזהו ותרד העיינה ותמלא כדה כו' כי הנה ע\"י בחי' ביטול נה\"ב ששרשה מפני שור כו' שבמרכבה העליונה כנ\"ל נמשך עי\"ז בחי' כ\"ד",[["35","34","<b>והנה יצחק מצחק את רבקה אשתו</b>: בראשית כו, ח."],["36","35","<b>שתי רבקות של שלש שלש בקר</b>: עירובין יז, ב."],["37","36","<b>משנכנסו לרבקה</b>: ראה פסחים כו, א."],["38","37","<b>דפני ארי' להימין</b>: ראה יחזקאל א, י."],["39","38","<b>המל' שנק' כסא</b>: ראה פרדס שער ערכי הכינויים (שכ\"ג) מע' כסא. ס' מאמרי אדה\"ז עה\"ת ח\"א ע' קכא וע' שלא. סה\"מ תקס\"ח ע' קנב. ביאורי הזהר להצ\"צ כרך ב' ע' תתח ואילך. אוה\"ת נח כרך ג' תרמח, סע\"ב. ובכ\"מ."],["40","39","<b>וכמא' והחיות נושאות את הכסא</b>: ראה בחיי תרומה כה, י בשם פדר\"א. וראה פדר\"א ספ\"ד. שמו\"ר ספכ\"ג."],["41","40","<b>מג'</b>: בכת\"י ב: מגבורה."],["42","41","<b>ששלשה פונים תימנה</b>: ראה מלכים א ז, כה."],["43","42","<b>וכמ\"ש בזוהר בהיכלות דפ' פקודי</b>: ראה ג\"כ זח\"א רמא, א. רמז, א. זח\"ב קצז, ב."],["44","43","<b>האבות הן המרכבה</b>: ב\"ר פמ\"ז, ו. זח\"א רי, ב. זח\"ג קפב, א."],["45","44","<b>בכנ\"י</b>: בכת\"י ב: בכללות נש\"י."]]],[2101000031,"ספרי' דאוריי' דהנה כל הכ\"ד ספרים נתלבשו בעניני' גשמי' כמו מצות תרומו' ומעשרו' שהוא בבחי' צומח הגשמי ומצות הקרבנות בבחי' החי גשמי וכיוצא בזה בכל המצות הכתובי' בתשב\"כ ותשבע\"פ הכל בבחי' נוגה דדצ\"ח גשמיי' ששרשם אחד עם נה\"ב והטעם הוא כי<sup data-n=\"46\">45</sup> בחכ' דוקא אתברירו וע\"י ביטול הנה\"ב מלמטה למעלה נמשך חכ' שבכ\"ד ספרי' דאוריי' אל בחי' נוגה מלמעלה למטה לברר שם ולהבדיל בין קודש לחול בין טמא לטהור כו' במצות ל\"ת וכמ\"כ במ\"ע דוקא בדצ\"ח גשמיי' מתלבש אור החכ' שבתורה וכמו שארז\"ל שביקשו<sup data-n=\"47\">46</sup> המלאכי' שיותן להם התורה והשיבם כלום יצה\"ר יש בכם כו' וז\"ש ותמלא כדה שרבקה דוקא ממלאת כ\"ד ספרי' דאוריי' כו' מים הגדול דח\"ע חכים ולא בחכ' ידיע' וע\"ד הנ\"ל בענין יצחק מצחק את רבקה אשתו וד\"ל (ושרש הדברי' הנה יצחק ורבקה הוא בחי' מ\"ה וב\"ן שלפני האצי' דהיינו בחי' חו\"ג דע\"י דאע\"ג דלית<sup data-n=\"48\">47</sup> שמאלא בהאי ע\"י אבל בחי' מ\"ה וב\"ן יש בו ובחי' רבקה הוא בחי' ב\"ן נוק' דע\"י וז\"ש ותרד העיינה בבחי' ח\"ס שרש התורה כי בחי' גבורה דע\"י יורד בח\"ס כידוע ותמלא כ\"ד ספרים לברר על ידם בירורי נוגה כנ\"ל כידוע דבחי' גבורה דע\"י שבח\"ס הוא מקור כל הבירורי' כו' ויצחק הוא בחי' מ\"ה שמצחק את רבקה אשתו שהוא בחי' חסד דע\"י שמלובש בגלגלת' כו' וד\"ל).\n<b>ומ\"ש</b> ותמלא כדה ותעל הנה עלי' זאת היא למעלה מעלה גם מבחי' יצחק הנ\"ל ג\"כ כמ\"ש אשת<sup data-n=\"49\">48</sup> חיל עט\"ב וכתיב נקבה<sup data-n=\"50\">49</sup> תסובב גבר כו', והענין הוא לפי שברבקה נאמר שהיא טובת מראה מאוד וכל<sup data-n=\"51\">50</sup> מקום<sup data-n=\"52\">51</sup> שנאמר מאד הוא בלי שיעור וגבול כידוע והענין הוא כי בחי' מראה זאת היינו כמ\"ש הראיני<sup data-n=\"53\">52</sup> את מראיך כי מראיך נאוה פי' כידוע בפי' מ\"ש עיניך<sup data-n=\"54\">53</sup> יונים כמשל היונים שעיקר התענוג שלהם הוא בהסתכלותם זע\"ז וההסתכלות בתשוקה ותענוג הוא תענוג נפלא ביותר עד שיוכל להיות כל לבו בתענוג זה וכמ\"כ למעלה הנה יש בחי' תענוג ההסתכלות מלמטה למעלה כמא' לאסתכלא<sup data-n=\"55\">54</sup> ביקרא דמלכא שהסתכלות זאת היא בתענוג נפלא וז\"ש עיניך יונים מכנ\"י להקב\"ה וכמ\"כ מהקב\"ה לכנ\"י כתיב עיניו<sup data-n=\"56\">55</sup> כיונים כו'. ואמנם בחי' הסתכלות דכנ\"י לאסתכלא ביקרא דמלכא הוא בתשוקה ותענוג נפלא ביותר וכמ\"ש ואל<sup data-n=\"57\">56</sup> אישך תשוקתיך ולכך<sup data-n=\"58\">57</sup> נק' כלה מלשון כלתה<sup data-n=\"59\">58</sup> נפשי כו' (וע\"כ",[["46","45","<b>כי בחכ' דוקא אתברירו</b>: ראה זח\"ב רנד, ב. ע\"ח שי\"ח פ\"ה ועוד. מבו\"ש ש\"ה ח\"א פ\"ב. אגה\"ק סכ\"ח. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 206."],["47","46","<b>שביקשו המלאכים שיותן להם התורה</b>: שבת פח, ב."],["48","47","<b>דלית שמאלא בהאי ע\"י</b>: זח\"ג קכט, א."],["49","48","<b>אשת חיל עט\"ב</b>: משלי יב, ד. וראה אוה\"ת בראשית מ, ב."],["50","49","<b>נקבה תסובב גבר</b>: ירמי' לא, כא."],["51","50","<b>טובת מראה מאד</b>: בראשית כד, טז."],["52","51","<b>וכל מקום שנאמר מאד הוא בלי שיעור וגבול</b>: ראה ג\"כ לקו\"ת שלח מב, ג. דרמ\"צ קס, ב."],["53","52","<b>הראיני את מראיך</b>: שה\"ש ב, יד."],["54","53","<b>עיניך יונים</b>: שה\"ש א, טו. ד, א."],["55","54","<b>לאסתכלא ביקרא דמלכא</b>: ראה זח\"ב רמז, ב."],["56","55","<b>עיניו כיונים</b>: שה\"ש ה, יב."],["57","56","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["58","57","<b>ולכך נק' כלה</b>: ראה דב\"ר ס\"פ ואתחנן. שהש\"ר ע\"פ מה יפו דודיך (ד, י)."],["59","58","<b>כלתה נפשי</b>: תהלים פד, ג."]]],[2101000032,"נאמר בה הסיבי<sup data-n=\"60\">59</sup> עיניך מלהסתכל שהמה הרהיבוני כו' וכמ\"ש במ\"א) וזהו שנאמר ברבקה שהוא בחי' ביטול והתכללו' מלמטה למעלה מיש לאין כנ\"ל שהיא טובת מראה כו' פי' כמ\"ש מראך נאוה כמו המראה שמביטין בה שיחזור האור אל מול הפנים הרואין כו' כך בחי' הסתכלו' דכנ\"י למעלה הוא בבחי' או\"ח מלמטה למעלה (וכמ\"ש במ\"א באריכות בענין הראיני את מראיך כו' שהוא מפני המסך המדובק באחורי המראה שעי\"ז חוזר האור כידוע וכך ע\"י ביטול רצון נה\"ב המסך המבדיל כו' וד\"ל) ומ\"ש כי מראך נאוה וכן מ\"ש טובת מראה הענין הוא מפני שבחי' התענוג אשר בבחי' ההסתכלו' הוא להודות ולהלל ביקרא דמלכא בשירות ותשבחות שלו כמו בשיר השירי' דכנ\"י או' ישקיני מנשיקות פיהו וכמ\"כ בפסוד\"ז להלל בתשבחות בה' מזמורים דהללויה שהוא הכנה לק\"ש וכמ\"ש יסדר<sup data-n=\"61\">60</sup> אדם שבחו כו' שעי\"ז יוכל לבא לבחי' אהבה רבה דבכל מאדך בק\"ש בבחי' ביטול רצון מכל וכל כו' וע\"כ נק' רבקה שהוא בחי' אהבה רבה דק\"ש כנ\"ל בשם טובת מראה ע\"ש בחי' התענוג שבהסתכלות ביקרא דמלכא בפסוד\"ז וז\"ש ברבקה טובת מראה מאד בלי שיעור (כי בחי' או\"ח חוזר אל עצמו' המאצי' ממש כמו האהבה דבכל מאדך שהיא לעצמו' א\"ס דוקא וכמ\"ש מי לי בשמי<sup data-n=\"62\">61</sup>ם כו' ושם הוא בחי' מאד בלי גבול ולכך נאמר בה ותעל כנ\"ל שעליה זאת היא למעלה מעלה גם מבחי' יצחק לפי שנאמר א\"ח עט\"ב נקבה כו' והיינו מטעם זה וד\"ל).\n<b>וזהו</b> מים רבים לא יוכלו לכבות את האהבה פי' בחי' האהבה הזאת הוא בחי' צמאון התשוקה באהבה בתענוגים מלמטה למעלה בבחי' או\"ח כנ\"ל שהוא בחי' רבקה כו' ופי' מים רבים הוא בחי' ח\"ע שמחמתה נתהווה בחי' אהבה רבה זאת כמו ע\"י השגת אור א\"ס בפסוק ראשון דק\"ש שמע<sup data-n=\"63\">62</sup> ישראל בחי' יחו\"ע ובשכמל\"ו יחו\"ת עד רום המעלות ואמנם אין ביכולת עונג שבחכ' להשקיט ולכבות צמאון האהבה רבה זאת הגם שנולדה ממנה לפי שבחי' או\"ח דא\"ר זאת מגעת עד למעלה מעלה דהיינו בבחי' עצמו' אא\"ס ממש כנ\"ל ולגבי עצמו' הא\"ס הארת החכ' כלא חשיבי ממש שהרי ידוע שהחכ'<sup data-n=\"64\">63</sup> נק' יו\"ד וכמו<sup data-n=\"65\">64</sup> אות יו\"ד לגבי עומק מח' הכללית שבשכל שבטילה שם במציאותה כי אין ערוך כלל לאות א' שבמחשבה לגבי עצם שכל האדם ומכ\"ש לגבי הנפש עצמה כו' כמ\"כ גם בחי' ח\"ע שנמשכה מאור א\"ס כמ\"ש והחכ'<sup data-n=\"66\">65</sup> מאין תמצא וכמו משל המעיין שנובע כו' כנ\"ל באורך הרי כלא חשיבי לגבי עצמות חכמתו ית' שנק' חכים ולא בחכ' ידיע' והוא בחי' חכ' דא\"ס עצמו כי הוא המדע כו' וכמ\"ש לתבונתו אין חקר וכנ\"ל ומכ\"ש לגבי עצמות א\"ס ממש כו' ובחי' א\"ר הנ\"ל הוא דוקא לבחי' עצמו' אור א\"ס כנ\"ל ע\"כ אמר דגם מים רבים דהיינו גם בחי' חכ' הקדומה כו' לא יוכלו לכבות ולהשקיט לא\"ר הנ\"ל מפני",[["60","59","<b>הסיבי עיניך</b>: שה\"ש ו, ה."],["61","60","<b>יסדר אדם שבחו</b>: ברכות לב, א. זח\"א קסט, א. ובכ\"מ."],["62","61","<b>מי לי בשמים</b>: תהלים עג, כה."],["63","62","<b>שמע ישראל בחי' יחו\"ע ובשכמל\"ו יחו\"ת</b>: זח\"א יח, ב."],["64","63","<b>שהחכ' נק' יו\"ד</b>: ראה זח\"ג רצ, ב. ובכ\"מ."],["65","64","<b>וכמו אות יו\"ד לגבי עומק מח' הכללית</b>: ראה תניא פ\"כ ובליקוט פירושים ומ\"מ שם."],["66","65","<b>והחכ' מאין תמצא</b>: איוב כח, יב."]]],[2101000033,"שמתאחדת בעצמות א\"ס ממש מטעם הנ\"ל (וז\"ש ברבקה ותרד העיינה לשון ירידה לפי שבחי' ח\"ס למטה הימנה אך מה שתמלא כ\"ד ספרים הוא חלק המובחר שבחכמה ובזה תוכל לעלות למעלה מעלה וכמ\"ש ותעל כנ\"ל והיינו מ\"ש אם יתן איש כו' וכמו שיתבאר בסמוך וד\"ל).\n<b>ונהרות</b> לא ישטפוה. הנה מבואר למעלה ההפרש בין המעינות לנהרות שהנהרות באין בגילוי ויש להן שיעור אך לפרקים מתגברין הנהרות ביותר כידוע ולזה אמר דגם בחי' נהרות העליונות כאשר מתגברים ומתרחבים ביותר גם המה לא ישטפוה לבחי' אה\"ר הנ\"ל לכסותה ולהעלימה כו', והענין הוא כמבואר למעלה שבחי' בינה נק' נהר וכמ\"ש ונהר יוצא מעדן והיינו בחי' ההשגה וההבנה באור א\"ס שנק' יש כנ\"ל והחכ' נק' אין כו' אך כ\"ז הוא כאשר ההשגה הוא בלתי עונג אזי היא באה במדה ושיעור אבל כאשר מתלבש בה העונג אזי אין לה שיעור בהתרחבות ובעומק ובאורך כו' כמו הנהר שמתגבר לרוחב כו', והדוגמא מזה היינו כמו הנשמו' שנהנין מזיו כו' שגם שכאו\"א השגתו מוגבלת אבל ע\"י בחי' ההנאה והעונג האלקי שבהשגתם ההשגה מתפשטת בלי שיעור וז\"ש ונהרותם<sup data-n=\"67\">66</sup> כשמן אוליך שהוא בחי' התענוג שבבינה וכנראה בחוש באדם כשמבין ומשיג דוקא אז מתענג ובאמצעות התענוג מתרחבת ההשגה בלי שיעור וד\"ל ולמעלה הנה הוא הנק' נהרי אפרסמונא דכי' שהשמן הטוב שיש לו ריח טוב כמו שמן אפרסמון הוא למעלה בחי' התענוג שבחכ' כמ\"ש כשמן<sup data-n=\"68\">67</sup> הטוב על הראש כו' וכתיב ונהרותם כשמן כו' שיש בבינה שנק' נהר ג\"כ בחי' שמן הטוב הזה והמה תליסר<sup data-n=\"69\">68</sup> נהרי דאפרסמונא דכי' שנז' בגמ' גבי ר\"א ב\"פ והוא בחי' העונג הנפלא שבהשגה דבינה כו' ואזי מתרחב ההשגה בלי שיעור כנ\"ל, והנה גם בחי' נהרי אפרסמוני דכי' הללו לא יוכלו לשטוף את האה\"ר הנ\"ל וז\"ש ונהרות לא ישטפוה (וכנראה בחוש שגם בחי' התענוג הנפלא שבהשגה אלקי' לא תוכל להשקיט צמאון של אהבה בתענוגים הנ\"ל והראי' מר\"ע<sup data-n=\"70\">69</sup> שהיו מוצאין אותו בזוויות זו כו' מפני רוב כריעות והשתחוואו' שהוא בחי' ביטול רצון בא\"ר הנ\"ל ולא הי' ביכולת התענוג שבהשגתו לשטוף צמאון זה כו' וד\"ל).\n<b>אם</b> יתן איש את כל הון ביתו באהבה בוז יבוזו לו כו'. פי' הגם שמים רבים לא יוכלו לכבות את האהבת ונהרות בו' מ\"מ יש דבר שיוכל להשקיט את צמאון האהבה הנ\"ל והוא אם יתן איש את כל הון ביתו כו' דהיינו ע\"י בחי' כ\"ד ספרי' דאוריי' הנ\"ל שנק' הון ביתו כו' דהנה אנו רואים שכל תענוג הוא משקיט את צמאון התשוקה כמו כאשר יכסוף אדם וישתוקק לדבר מה הנה כאשר ישיג את דבר תאותו מתענג בו והתענוג ההוא מבטל את הצמאון והתשוקה שהי' לו מקודם וכמ\"כ יובן",[["67","66","<b>ונהרותם כשמן אוליך</b>: יחזקאל לב, יד."],["68","67","<b>כשמן הטוב על הראש</b>: תהלים קלג, ב. וראה לקו\"ת בהעלותך לה, ב. ובכ\"מ."],["69","68","<b>תליסר נהרי דאפרסמונא דכיא שנז' בגמ'</b>: תענית כה, א. וראה ב\"ר פס\"ב, ב. זח\"א קעו, א. ובכ\"מ. לקו\"ת שה\"ש ב, ד. ביאוה\"ז קיח, ב."],["70","69","<b>מר\"ע שהיו מוצאין אותו בזוית זו</b>: ברכות לא, א."]]],[2101000034,"למעלה בבחי' אה\"ר הנ\"ל דכתיב צמאה<sup data-n=\"71\">70</sup> נפשי כו' כלה<sup data-n=\"72\">71</sup> שארי ולבבי כו' הנה כאשר ישיג לנפשו מהארת אוא\"ס שמשתוקק אליו בדביקה וחשיקה כו' אזי מתבטל הצמאון שצמאה נפשו לאל חי כו' מפני בחי' התענוג שמתענג על ה' והנה השגת הנפש במהות אור א\"ס אינו אלא במעשה המצות ועסק תורתו שהן כ\"ד ספרי' דאוריי' שהמה עצמיות רצונו וחכמתו ית' ובהם מלובש שעשועיו ותענוגיו העצמיי' הנק' עונג העליון שהוא מקור כל התענוגים שלמעלה מבחי' החכ' וע\"כ הגם שבחי' מים רבים דחכ' לא יוכלו לכבות את האה\"ר הנ\"ל ולהשקיט צמאון הנפש אבל ע\"י בחי' התענוג שמתענג בעונג העליון שבמעשה המצות ובעצמות חכמתו ששם משכן הארת אור א\"ס עצמו נשקט הצמאון (ומ\"ש מים רבים לא יוכלו לכבות כו' היינו בחי' חכ' בלתי עונג עליון כו' והגם שמבואר למעלה בפי' ונהרות כו' שהוא התענוג שבהשגה כו' היינו רק התלבשות העונג שבהשגה אשר אין לו ערך לעצמו' התענוג ובפרט לבחי' מקור התענוגים כו' ולפ\"ז פי' מים רבים הוא ג\"כ בהתלבשו' התענוג אבל גם הוא אין לו ערך לגבי עצם התענוג כו' לכך לא יוכלו לכבות כו'). וזהו פי' ברכות המצות ברוך אתה ה' פי' אתה הוא לנוכח מכוין לבחי' עצמות אור א\"ס שיהא מתברך ונמשך לעולם הנאצל שהוא שם הוי' הכולל ע\"ס יו\"ד חכ' כו' ואח\"כ להיות מלך העולם שהוא בחי' מל' דאצי' בעולם הנברא והיינו בחי' יחו\"ע ויחו\"ת כו' אשר קדשנו במצותיו פי' אשר לשון עונג כמו באשרי<sup data-n=\"73\">72</sup> כו' כידוע והוא בחי' עונג העליון הנ\"ל שנק' שעשועי<sup data-n=\"74\">73</sup> המלך בעצמותו והוא בחי' מקור התענוגים כו' שמלובש במעשה המצות כו', והמשך כוונת הברכה כך היא שיהא בחי' גילוי הארה והמשכה מעצמות אא\"ס ביחו\"ע ויחו\"ת שהוא הוי' ומלך העולם כנ\"ל להיות בחי' אשר שהוא עונג העליון קדשנו במצותיו דהיינו שגם מצות שלנו הנעשות בדברי' גשמיי' יהא גם בהן התלבשות מבחי' עונג העליון הנק' אשר וז\"ש קדשנו במצותיו שיקדשנו בקדושת מצותיו שהוא בחי' רצה\"ע ממש שבו מאיר עונג העליון הנ\"ל וכמ\"ש מצותיו וע\"ד שארז<sup data-n=\"75\">74</sup>\"ל שהקב\"ה מניח תפילין כו' וכמ<sup data-n=\"76\">75</sup>\"ש בזהר שהמצות נק' רמ\"ח אברים דמלכא כידוע, והטעם שצריך לומר ברכה זאת ולמה לא יומשך ויתלבש עונג העליון הנ\"ל מעצמו בעשותו המצוה הענין הוא עד\"מ אם רוצה אדם להאיר למרחוק או במקום חושך ואפלה צריך להדליק אבוקה גדולה ולהוסיף על אור הנר משא\"כ כאשר אינו צריך להאיר רק מקרוב די באור הנר כו' והנמשל יובן דלמעלה בבחי' אצי' שהוא בקירוב יותר להארת אוא\"ס דאיהו<sup data-n=\"77\">76</sup> וחיוהי כו' וגם הארת אוא\"ס מאיר שם בתמידות א\"צ כ\"כ לתוס' אורה וברכה מאת\"ה כו' אבל בשביל המשכה וגילוי למטה מטה בדברים גשמיי' דנוגה שבמעשה המצות שהוא בתכלית הריחוק והוא",[["71","70","<b>צמאה נפשי</b>: תהלים מב, ג."],["72","71","<b>כלה שארי ולבבי</b>: תהלים עג, כו."],["73","72","<b>באשרי</b>: בראשית ל, יג. וראה ת\"ז תי' ט\"ל (עט, א)."],["74","73","<b>שעשועי המלך בעצמותו</b>: ראה עמק המלך ש\"א. לקו\"ת שה\"ש כז, א."],["75","74","<b>שארז\"ל שהקב\"ה מניח תפילין</b>: ברכות ו, א. וראה תו\"א מקץ לה, ב ואילך."],["76","75","<b>וכמ\"ש בזהר שהמצות נק' רמ\"ח אברים דמלכא</b>: ראה זח\"ב קיח, א. ת\"ז תי' ל. תניא פ\"ד ובליקוט פירושים ומ\"מ שם."],["77","76","<b>דאיהו וחיוהי</b>: ת\"ז בהקדמה (לפני ד\"ה קום יחזקאל)."]]],[2101000035,"מקום חושך ואפילה צריך להיות המשכה בתוס' אור ממקורא דכולא וז\"ש ברוך אתה על מעשה המצות דוקא וד\"ל.\n<b>אך</b> עתה לא נגלה האור הזה עדיין למטה בבחי' גילוי גמור ממש וגם בעולם הנאצל הארת אור זה המתברך ע\"י המצות שורה בהעלם ולעתיד יתגלה, וז\"ש אהי' אשר אהי'<sup data-n=\"78\">77</sup> פי' אהי' הוא למעלה משם הוי' דחכ' כו' והוא בחי' עונג העצמי הנ\"ל שעכשיו הוא נמשך בהעלם ולעתיד יתגלה וז\"ש אשר אהי' אנא<sup data-n=\"79\">78</sup> זמין כו' שעתיד להתגלות כו' וד\"ל. ובכ\"ז יובן מארז\"ל דיפה<sup data-n=\"80\">79</sup> שעה א' בתשובה ומע\"ט בעוה\"ז מכל חיי העוה\"ב. הנה דקדק לומר ב' דברים הא' ממעשה המצות או תשובה והב' בעוה\"ז דוקא. והענין הוא כי מעשה המצות בעוה\"ז מלובשים בדברים גשמי' דנוגה וצריך לזה להיות תוס' אור מבחי' עונג העליון העצמי כנ\"ל ומלבד מעלת שרש המצות עצמן למעלה שהן בחי' רצון ועונג העליון העצמי כנ\"ל שהוא למעלה מן החכ' כנ\"ל וזהו שאמרו דיפה שעה א' במעשה המצות בעוה\"ז שעי\"ז נמשך אור עונג העליון העצמי שהוא למעלה מהשגות הנשמות בג\"ע הנק' חיי העוה\"ב הגם שנהנין מזיו השכינה בעונג נפלא עד שאמרו באחר מוטב<sup data-n=\"81\">80</sup> לדייני' וליתי לעלמא דאתי כו' מפני שכדאי לסבול כל יסורי גיהנם בשבילו מ\"מ אין לעונג זה ערך ודמיון כלל לגבי עצמות העונג עליון שנמשך ע\"י המצות כנ\"ל בפי' מים רבים לא יוכלו לכבות כו' (וכן ע\"י התשובה שהיא ג\"כ לאהפכא חשוכא לנהורא שהוא בחי' בירורי נוגה כו' כמ\"ש במ\"א).\n<b>וזהו</b> ותרד העינה ותמלא כדה ותעל. דהנה זכר כאן עלי' וירידה בתחלה ירדה העינה למלאות ואח\"כ עלתה לאחר שתמלא כדה כו' והענין הוא כי בחי' ירידה זאת היא לצורך עלי' להיות מבואר למעלה דבחי' רבקה הוא בחי' אהבה רבה הנ\"ל, והנה בעבודה<sup data-n=\"82\">81</sup> שבלב זו תפלה יש צמאון א\"ר זאת בק\"ש באמרו בכל מאודך כו', אך הנה אמר בס<sup data-n=\"83\">82</sup>\"י אם רץ לבך שוב כו' דמיד אחר בחי' הרצוא בצמאון א\"ר זאת צ\"ל בחי' ירידה והמשכה למטה והוא לירד ולהתלבש בעסק התורה והמצות אחר התפלה וכמו שידוע בפי' האור<sup data-n=\"84\">83</sup> כי טוב כי טוב לגנוז האור בכלי כו', וזהו פי' ותרד העינה שבחי' רבקה תרד ותשפיל א\"ע למטה והוא בבחי' מעיין החכ' שירד",[["78","77","<b>אהי' אשר אהי'</b>: שמות ג, יד. וראה בארוכה סידור קנז, ד. שערי אורה עה, א. אוה\"ת וישלח רלט, ב. אוה\"ת דרושים ליוהכ\"פ ע' א'תקצד. ובכ\"מ."],["79","78","<b>אנא זמין כו'</b>: זח\"ג סה, ב. וראה תו\"ח נח (נח, ב)."],["80","79","<b>דיפה שעה א' בתשובה ומע\"ט בעוה\"ז</b>: אבות פ\"ד מי\"ז. וראה תניא ספ\"ד. תו\"א ויחי מו, ג. לקו\"ת ראה יט, ד. אוה\"ת דרושים לפ' זכור ע' א'תשסט ואילך. ובכ\"מ."],["81","80","<b>מוטב לדייני' וליתי לעלמא דאתי</b>: חגיגה טו, ב. וראה לקו\"ת בשלח א, ד. שם ויקרא נב, ב. דרמ\"צ א, ב. ובכ\"מ."],["82","81","<b>בעבודה שבלב זו תפלה</b>: תענית ב, א."],["83","82","<b>בס\"י אם רץ לבך</b>: ס\"י פ\"א מ\"ח. וראה ת\"ז בהקדמה (ז, א). וראה אוה\"ת יתרו ע' תתקעח, תתקפא."],["84","83","<b>האור כי טוב</b>: בראשית א, ד. וראה חגיגה יב, א. ובכ\"מ."]]],[2101000036,"למטה במעשה המצות בדברים גשמיי' כנ\"ל אך ירידה זאת צורך עלי' היא כי הנה פי' כדה היינו כ\"ד ספרים דאוריי' כנ\"ל ועד\"מ השואב בכד מן המעיין שממלא ושואב מן המים הצלולים הנקיים ומובררים ביותר כו' כך מכל בחי' ח\"ע שנק' עינה מלאה בכדה מן בחי' אור החכ' המובחר והוא בחי' חכ' שבתורה שנאמר בה כל<sup data-n=\"85\">84</sup> אמרות אלוה צרופה כו' ע\"כ אל תוסיף על דבריו כו' ולכך אמר אחכמה<sup data-n=\"86\">85</sup> והיא רחוקה כו' וכן כתיב תורת<sup data-n=\"87\">86</sup> ה' תמימה כו' מתוקים מדבש כו' וזהו ותמלא כדה כ\"ד ספרים שהן בחי' אותיות התורה שנק' כלים לאור החכ' של התורה (ונק' ג\"כ הון ביתו כמשי\"ת) והוא בחי' המשכת אור החכ' העצמי' שבתורה בכלי הכ\"ד הזה שהן כ\"ד ספרים כו' והיינו פי' ותמלא כדה כו' ותעל שעלתה בעלי' גדולה ע\"י בחי' ירידה זאת והיינו מטעם הנ\"ל לפי שבחי' עונג העליון העצמי הנק' שעשוע המלך בעצמו יורד למטה דוקא בבחי' התלבשו' בדברי' גשמיי' כנ\"ל ונמצא הרי עולה היא ע\"י ירידה והתלבשו' זאת בכ\"ד ספרים כו' לגבי עצמו' עונג העליון והגם שהוא נעלם עכשיו אבל לעתיד יתגלה וכמ\"ש אשר אהי' כנ\"ל וזהו פי' ותעל לשון עתיד לפי שעכשיו הוא בחי' ירידה ולעתיד הוא בחי' העלי' אבל הירידה הוא בשביל העלי' בלבד וד\"ל.\n<b>וזהו</b> אם יתן איש את כל הון ביתו כו' פי' איש א' י\"ש אלף זה הוא הנק' אלופו של עולם שממנו נמשך בחי' מקור התענוג העליון בחי' אשר הנ\"ל שמלובש במעשה המצות כנ\"ל וכדי שיומשך מקור התענוג מבחי' ההעלם לגילוי נק' איש א' י\"ש כמ\"ש להנחיל<sup data-n=\"88\">87</sup> אוהבי י\"ש שהוא ענין ש<sup data-n=\"89\">88</sup>\"י עולמות כו' (דהיינו בחי' התגלות עתיק בבינה שנק' י\"ש והיינו א' שמתלבש בבחי' י\"ש כו' וד\"ל), וז\"ש ה' איש מלחמה<sup data-n=\"90\">89</sup> כי בחי' המשכות מקור העונג העליון למטה בבחי' גילוי הנק' י\"ש נק' איש מלחמה כי צריך להיות ע\"י בחי' גבורות וצמצומים הרבה מפני שאין ערוך כלל לנאצלי' ונבראי' כו' לגבי בחי' מקור העונג העליון הגנוז בהעלם עצמו' המאציל הנק' שעשועי המלך בעצמותו כנ\"ל וד\"ל. וזהו אם יתן איש את כל הון ביתו פי' הון ביתו הנה פי' ביתו הוא בחי' בית דחכ' כמ\"ש בחכ'<sup data-n=\"91\">90</sup> יבנה בית והן בחי' אותיו' התורה בכ\"ד ספרים דאוריי' כמ\"ש ותמלא כדה כו' כנ\"ל וכמ<sup data-n=\"92\">91</sup>\"ש בס\"י שהאבנים הן האותיות שתי אבנים בונות כו' ולכך נק' ת\"ח בונים וכמ\"ש ורב<sup data-n=\"93\">92</sup> שלום בניך א\"ת בניך אלא בוניך שעוסקי'<sup data-n=\"94\">93</sup> בבנינו של עולם כו' ועד\"מ בבנין בית הנה עיקר העונג והשעשועי' הוא במטמונים הגנוזים בתוך חדרי הבית מכל הון יקר ונעים כו' הנק'",[["85","84","<b>כל אמרות אלוה צרופה. . אל תוסיף על דבריו</b>: ראה משלי ל, ה-ו."],["86","85","<b>אחכמה והיא רחוקה</b>: קהלת ז, כג."],["87","86","<b>תורת ה' תמימה. . מתוקים מדבש</b>: תהלים יט, ח-יא."],["88","87","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["89","88","<b>ש\"י עולמות</b>: סוף עוקצין."],["90","89","<b>ה' איש מלחמה</b>: שמות טו, ג. וראה בארוכה אוה\"ת תצא ע' תתעט ואילך."],["91","90","<b>בחכ' יבנה בית</b>: משלי כד, ג."],["92","91","<b>וכמ\"ש בס\"י. . שתי אבנים בונות</b>: פ\"ד מט\"ז. וראה ג\"כ תו\"א ויצא כא, א. ובכ\"מ."],["93","92","<b>ורב שלום בניך א\"ת בניך אלא בוניך</b>: ישעי' נד, יג. ברכות סד, א."],["94","93","<b>שעוסקי' בבנינו של עולם</b>: שבת קיד, א."]]],[2101000037,"הון ביתו כך למעלה הנה עיקר בחי' התענוג העליון בהון ביתו הגנוז באותיות התורה כ\"ד ספרים כו' והיינו מ\"ש אם יתן איש א' יש ממקור התענוג המלובש בכל הון ביתו שבתורה אזי בזה יוכל להיות השקט לצמאון אה\"ר הנ\"ל אע\"פ שמים רבים לא יוכלו לכבותה כנ\"ל מפני שבחי' עונג העליון שבהון ביתו למעלה הרבה מבחי' מים רבים הנ\"ל ויש ביכולתו לרות<sup data-n=\"95\">94</sup> צמאון דא\"ר הנ\"ל וד\"ל.\n<b>וזהו</b> אם יתן איש את כל הון ביתו באהבה בוז יבוזו לו פי' בוז יבוזו לשון ביזה ושלל שיבוזו ויחטפו לעוצם הפלאת הדבר במעלה להיותו כל הון יקר ונעים כו' כמו אדם הבוזז וחוטף דבר יקר הערך כמו אוצר של אבנים טובות שאינם ראוים לבוא לידו דרך נתינה ע\"כ חוטף ובוזז כי לא יוכל לעמוד על נפשו לעוצם יקרת האוצר כו', וכך יובן למעלה דהנה בחי' הארת האור עונג העליון שנק' הון יקר ונעים המלובש באותיות התורה לעוצם יוקר ומעלת האור במאד מאד לא יוכל לבא בהתגלות למטה גם באצי' בדרך השתלשלו' מעילה לעילה בסדר והדרגה אלא רק לפעמים יבא למטה בדרך ביזה וחטיפה למעלה מגדר השתלשלו' עו\"ע (וכמ\"ש<sup data-n=\"96\">95</sup> במ\"א ע\"פ ביום ההוא יהי' מצילת הסוס קדש וארז\"ל כל מה שהסוס רץ ומיצל יהי' קודש לה' והיינו אור העליון הגנוז ונעלם באותיות<sup data-n=\"97\">96</sup> התורה שנק' סוסים כמ\"ש כי<sup data-n=\"98\">97</sup> תרכב על סוסיך כו' ולעומת זה יש תא הרצים כו'). וענין הביזה הזאת היינו כמ\"ש פי<sup data-n=\"99\">98</sup> פערתי ואשאפה כו' שהוא מדבר בעוסק בד\"ת שאותיות התורה בהן מלובש כל הון יקר ונעים הנק' הון ביתו כנ\"ל וע\"כ צריך אדם לפתוח פיו ולשאוף אותיות התורה כמו בדרך ביזה לבוז אוצר נחמד כנ\"ל וז\"ש פי פערתי ואשאפה להון ביתו שבאותיו' התורה וע\"כ ארז\"ל דהרחב<sup data-n=\"100\">99</sup> פיך ואמלאהו בד\"ת הוא דכתיב שכל מה שירחיב פיו בדיבור בד\"ת יותר יותר ימולא מכל הון יקר ונעים וז\"ש ואמלאהו בבחי' עונג העליון שבהון ביתו וד\"ל.\n<b>ובכ\"ז</b> יובן מ\"ש נשאו<sup data-n=\"101\">100</sup> נהרות קולם ישאו נהרות דכים מקולות מים רבים אדירים כו'. דהנה פי' נהר הוא בחי' בינה כמ\"ש ונהר<sup data-n=\"102\">101</sup> יוצא מעדן כו' והיינו בחי' ההתבוננות באור א\"ס שעי\"ז נולד רשפי אש ההתלהבות לדבקה בה' כידוע והוא בחי' רצוא כמאמ' בינה<sup data-n=\"103\">102</sup> לבא כו' שמבינה נולד צמאון האהבה ביסוד האש שבלב",[["95","94","<b>לרות</b>: בכת\"י ב וכת\"י ג: לרוות גם."],["96","95","<b>וכמ\"ש במ\"א ע\"פ ביום ההוא יהי' מצילת הסוס</b>: ראה זכרי' יד, כ. פסחים נ, א. וראה סה\"מ תקס\"ד ע' רסח. שעה\"ת ח\"א ל, א ואילך. תו\"ח שמות עג, א. רנט, ב. שערי אורה עג, א."],["97","96","<b>באותיות התורה שנק' סוסים</b>: ראה ת\"ז בהקדמה (ג, ב. ח, א). שם תי' ה' (כ, ב). שם תי' מז (פד, ב). וראה תו\"א בשלח סב, ג. סג, ד. ובכ\"מ."],["98","97","<b>כי תרכב על סוסיך</b>: חבקוק ג, ח. וראה ג\"כ תו\"א בשלח סג, ד. דרושים למג\"א צו, ד. סה\"מ הנחות הר\"פ ע' ח. ובכ\"מ."],["99","98","<b>פי פערתי ואשאפה</b>: תהלים קיט, קלא."],["100","99","<b>דהרחב פיך ואמלאהו בד\"ת הוא דכתיב</b>: תהלים פא, יא. ברכות נ, א."],["101","100","<b>נשאו נהרות קולם</b>: תהלים צג, ג. וראה תהלים יהל אור ע\"פ זה."],["102","101","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["103","102","<b>בינה לבא</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."]]],[2101000038,"וזהו פי' נהרות קולם בבחי' ההעלאה מלמטה למעלה כו' ואח\"כ נמשך ההארה מלמעלה למטה בבחי' שוב כו' כמאמר רוח אייתי רוח ואמשיך רוח<sup data-n=\"104\">103</sup> כו' וכמ\"ש אם<sup data-n=\"105\">104</sup> ישים אליו לבו רוחו ונשמתו אליו יאסוף פי' אם ישים אליו לבו מלמטה למעלה בבחי' רצוא ע\"י ההתבוננו' (בכל חד לפום שעו\"ד וע\"כ אמר נהרות ל' רבי') אזי מיד אחר ההעלאה יש המשכה מלמעלה למטה והוא מ\"ש רוחו ונשמתו אליו יאסוף מלמעלה למטה וזהו ג\"כ מ\"ש אחר שנשאו נהרות קולם בבחי' רצוא בהעלאה אזי מיד ישאו נהרות דכים מלמעלה למטה בבחי' המשכה ומ\"ש דכים היינו ד\"ך י\"ם ופי' ד\"ך זה היינו ענין צלילת ובהירת וגם ענינו לשון טהרה בל' תרגום וכן<sup data-n=\"106\">105</sup> דכן כו' והיינו נהרות העליונים ביותר שנק' נהרי<sup data-n=\"107\">106</sup> אפרסמונא דכי' שהוא שמן אפרסמון זך ונקי ובהיר מאד וגם הוא טהור מכל מגע טומאה כו'. והענין הוא כידוע שבחי' ח\"ע נק' ים ונמשך משם לבינה ונק' נהר וכמ\"ש ונהר יוצא מעדן כו' ופי' ד\"ך י\"ם היינו כאשר בחי' העונג העליון מלובש בחכ' ואז נמשל לשמן אפרסמון דכי' כידוע בפי' הפסוק כשמן<sup data-n=\"108\">107</sup> הטוב על הראש כו' (שהוא מקור י\"ג מדה\"ר והוא מקור לתענוגי הנשמות כמו בר\"א ב\"פ כנ\"ל וגילוי אור זה בהשגה דבינה נק' נהרי אפרסמונא כו' כנ\"ל) וזהו ישאו נהרות דכים מבחי' עונג העליון שבחכ' והן הנק' נהרי אפרסמונא כו' והוא בחי' ההמשכה מלמעלה למטה, והיינו שמפרש עוד מקולות מים רבים אדירים כו' פי' מהיכן ישאו נהרות בחי' המשכה זאת מקולות של מים רבים אדירים שהו' בבחי' ח\"ע סתימאה שנק' מים רבים אדירים חכים ולא בחכ' ידיע' כנ\"ל בפי' מים רבים לא יוכלו לכבות כו' וד\"ל.\n<b>אדיר</b> במרום ה' כו' לביתך נאוה קדש ה' לאורך ימים. פי' קאי אדסמיך לי' אשר אמר ישאו נהרות דכים מקולות מים רבים אדירים כו' אבל גדול מכל מים רבים אדירים הללו הוא אדיר במרום ה' שהוא אדיר שבאדירים ולכך נק' אדיר במרום כלומר גם במרום שהוא בחי' קולות דמים רבים הנ\"ל נק' אדיר לגביהם, והענין הוא כמו שמפרש הטעם בסמוך לביתך נאוה קדש פי' לביתך הן בחי' אותיות התורה שנק' בית ה' ובחי' הון ביתו היינו בחי' עונג ושעשועי' העצמיי' שמלובש בהן כנ\"ל והוא הנק' שעשוע המלך אשר גנוז בהעלם עצמותו והוא למעלה הרבה מבחי' הארת העונג העליון שיורד ומאיר בחכ' שנק' ד\"ך י\"ם וקולות מים רבים אדירים כנ\"ל שהרי אינו אלא הארה בעלמא מעצמות התענוג הפשוט הגנוז ונעלם בבחי' עצמות (וכמ\"ש במ\"א באריכות בענין ג' סעודות דשבת ובכמת דוכתי). וזהו לביתך נאוה קודש פי' קדש הוא בחי' חכ' הגנוז באותיו' התורה שנק' ביתך נק' נאוה קדש בחי' היופי וההידור של הקדש והוא בחי' עצם התענוג הפשוט שמאיר בחכ'",[["104","103","<b>רוח אייתי רוח ואמשיך רוח</b>: זח\"ב קסב, ב. וראה אוה\"ת בראשית רפו, א."],["105","104","<b>אם ישים אליו לבו</b>: איוב לד, יד. וראה תו\"א מג\"א קכא, ג. ובכ\"מ."],["106","105","<b>וכן דכן</b>: ראה עדיות פ\"ח מ\"ד."],["107","106","<b>נהרי אפרסמונא דכיא</b>: ראה בהנסמן לעיל ע' ז."],["108","107","<b>כשמן הטוב על הראש</b>: תהלים קלג, ב. וראה לקו\"ת בהעלותך לה, ב. ובכ\"מ."]]],[2101000039,"שבתורה דוקא וז\"ש נאדר בקדש כו' וכנ\"ל בפי' אם יתן איש את כל הון ביתו בוז יבוזו כו' וד\"ל.\n<b>ה'</b> לאורך ימים. הנה ארז\"ל על אלף<sup data-n=\"109\">108</sup> השביעי שנק' יום שכולו ארוך יום שכולו שבת כו' והענין הוא כי פי' כולו ארוך היינו שגם בתחילתו הוא ארוך ולכאורה אין לשון אריכות נופל רק בסיום וסוף ולא בתחלה אך משום דהכונה הוא על בחי' גילוי אא\"ס עצמו שבפנימי' הכתר והוא בחי' גילוי עצם התענוג הפשוט הנ\"ל שאין לו תחלה ואין לו תכלה וגם בתחלתו הוא כמו בסופו מאחר שאין לו תחלה וסוף כו' וזהו הנק' יום שכולו ארוך בתחלה כמו בסוף. והענין הוא כי לעתיד לא יהי' בחי' עליות וירידות כלל מלילה ליום ומיום ללילה שהוא מברי' לאצי' ומאצי' לבריאה כו' כי קמי' עצמו' אא\"ס הכל שוין מעלה ומטה גם רוחניות וגשמיו' אצי' ועשי' יחו\"ע ויחו\"ת וגם למטה מטה יהי' אותו ההתגלות שלמעלה מעלה ממש בלי שום חילוק מדריגה כלל וכמארז\"ל עתידים<sup data-n=\"110\">109</sup> צדיקי' שיאמרו לפניהם קדוש למטה כו' משא\"כ עכשיו לפעמים יש בחי' הסתלקות ואו' המלאכים איה מקום כבודו כו' וזהו ה' לאורך ימים ליום שכולו ארוך הנ\"ל ולא יהי' אז עליות וירידות כלל והוא מ\"ש אדיר במרום ה' אדיר שבאדירים כנ\"ל כי מ\"ש נשאו נהרות ישאו נהרות דכים כו' הוא בחי' עליו' וירידות בהעלאה והמשכה כנ\"ל אבל כאשר יתגלה אדיר במרום ה' לביתך נאוה קודש כנ\"ל אזי ה' לאורך ימים יום שכולו ארוך בלי עליות וירידות כלל כי ימצא למטה כמו למעלה ולא יאמרו אי\"ה כו' (וגם יתפרש לאורך ימים ע\"ד המבואר במ<sup data-n=\"111\">110</sup>\"א בפי' ה' ימלוך לע\"ו שיאיר במל' בבחי' נצחי' דא\"ס שלמעלה מן הזמן כו' וז\"ש ה' לאורך ימים ליום שכולו ארוך וד\"ל).",[["109","108","<b>אלף השביעי שנק' יום שכולו ארוך יום שכולו שבת</b>: ראה קידושין לט, ב. סוף מס' תמיד. וראה ג\"כ אוה\"ת תצא ע' תתקנז."],["110","109","<b>עתידים צדיקים שיאמרו לפניהם קדוש</b>: ב\"ב עה, ב."],["111","110","<b>במ\"א בפי' ה' ימלוך</b>: שמות טו, יח. סה\"מ תקס\"ח ח\"א ע' תל ואילך."]]],[2101000040,"<h3>להבין שרשי הדברים</h3>\n<b>בעזר\"ה ביאור על הנ\"ל</b>\n<b>להבין</b><sup data-n=\"112\">1</sup> שרשי הדברים הנ\"ל. הנה מ\"ש אם יתן איש כו' אם זה לשון עתיד הוא כמו אם<sup data-n=\"113\">2</sup> כסף תלוה כו' אם<sup data-n=\"114\">3</sup> קרבה שנת היובל כו' וכיוצא בזה וגם כאן אם יתן איש את כל הון ביתו כו' מדבר על העתיד שעתיד ליתן הון ביתו בבחי' הגילוי מן ההעלם אבל עכשיו עדיין לא נתן הון ביתו בבחי' הגילוי כו' כמשי\"ת בעזר\"ה. ותחלה י\"ל מהו ענין הון ביתו כו' דהנה לפי הדוגמא מענין הון ביתו בגשמיו' היינו כמו האוצרות ומטמונים מכסף וזהב ותכשיטי' וש\"ד המונחים",[["112","1","<b>להבין שרשי הדברים</b>: נדפס בשינויים בתו\"א תולדות יט, א. ונו\"א בשינויים להלן בהוספות."],["113","2","<b>אם כסף תלוה</b>: שמות כב, כד."],["114","3","<b>אם קרבה שנת היובל</b>: ראה במדבר לו, ד."]]],[2101000041,"ומוטמנים בחדרי ביתו הוא שנק' הון ביתו ג\"כ למעלה ברוחניות, וי\"ל איך הוא למעלה, ויובן זה בהקדי' הפסוק בחכ'<sup data-n=\"115\">4</sup> יבנה בית ובתבונה יתכונן ובדעת חדרים ימלאון כל הון יקר ונעים הרי זכר כאן ג' דברים חכמה ותבונה ודעת כמ\"ש במדרש בג'<sup data-n=\"116\">5</sup> דברים ברא הקב\"ה את העולם בחכ' ובתבונה ובדעת כו' וחלק לג' דברים הללו לג' ענינים כאו\"א על מקומו ומדריגתו דוקא בחכ' יבנה גוף בנין הבית עצמו ובתבונה יתכונן הבית הזה שנבנה כבר ע\"י החכ' ואח\"כ בדעת יתמלאו כל חדרי הבית הזה כל הון יקר ונעים כו'. וי\"ל מה שייכות לחכ' לבנות גוף הבנין ולתבונה לכוננו בלבד ומה ענין מילוי החדרים ע\"י דעת להיות נמצא בהם כל הון יקר כו'. אך הענין הוא כידוע שהאותיו' נק' אבנים כמ<sup data-n=\"117\">6</sup>\"ש בס\"י ה' אבנים בונות כו' ועד\"מ מאותיו' הדיבור שהן בחי' דומם כו' ומכ\"ש אותיו' הכתב והיינו אותיו' התורה בכ\"ב אתוון דאתמסרו למשה כו' ובחי' צירופי אותיו' שבתשב\"כ נק' בתים וכמ\"ש<sup data-n=\"118\">7</sup> בזהר דאוריי' היכלא עילאה דקוב\"ה כו' וכן ארז\"ל ד'<sup data-n=\"119\">8</sup> אמות של הלכה הוא במקום היכל ק\"ק כו' וכמ\"ש ורב<sup data-n=\"120\">9</sup> שלום בניך א\"ת<sup data-n=\"121\">10</sup> בניך אלא בוניך שעוסקי' בבנינו של עולם כו' והוא בחי' צירופי אותיו' התורה שנק' בנין בית וז\"ש בחכ' יבנה בית שע\"י ח\"ע שבעצמות המאציל נבנה עיקר הבנין בית הזה בעצמו ומהותו דהיינו שכל שרש התהוות צירופי אותיו' הללו הוא בשרשם ומקורם באור חכ' הקדומה דא\"ק וכמ\"ש ואהי'<sup data-n=\"122\">11</sup> אצלו אמון כו' שנק' קדמות השכל כו' (וכנראה בחוש שהתהוות הצירופי' בא מלמעלה מן השכל דוקא כמ\"ש במ\"א באריכות בענין ההוא<sup data-n=\"123\">12</sup> צפרא דמצפצפא כו') ובתבונה היינו בחי' שכל הנגלה בעיון ומח' עד שנק' מחשבה של חכ' שהוא מקור גילוי אותיות במחו\"ד כידוע ובתבונה זו יתכונן האותיות הנק' בית ופי' יתכונן היינו ענין קיום והעמדה בלבד כמן כן ובסיס כו' והענין הוא שע\"י בחי' התבונה הזאת יש קיום והעמדה נצחית לבנין צירופי אותיו' שבתשב\"כ שנק' בתים והיינו כמו ע\"י העוסקים בתורה בהגיון כמ\"ש והגית<sup data-n=\"124\">13</sup> בה כו' (וע\"י העוסקי' בדיבור נבנה הבית עצמו כמ\"ש בוניך וע\"י ההגיון בעיון יתכונן הבית וז\"ש ובתבונה יתכונן ועיי' במק\"מ במ\"ש הרמ\"ז בענין ההפרש בין מצות עיון למצות קריאה כו' וד\"ל). ובדעת חדרים ימלאון פי' אחר שכבר יש ריבוי חדרים בבית דתורה והוא אופני ריבוי הצירופי' שנק' ריבוי היכלות כנ\"ל אזי ע\"י אור הדעת נתמלאו כל אותן החדרים בכל הון יקר כו'.",[["115","4","<b>בחכ' יבנה בית</b>: משלי כד, ג."],["116","5","<b>בג' דברים ברא הקב\"ה את העולם</b>: שמו\"ר מח, ד. תנחומא ויקהל ה. ובכ\"מ."],["117","6","<b>כמ\"ש בס\"י ה' אבנים בונות</b>: פ\"ד מט\"ז."],["118","7","<b>וכמ\"ש בזוהר דאורייתא היכלא עילאה דקוב\"ה</b>: זח\"ב ר, א."],["119","8","<b>ד' אמות של הלכה הוא במקום היכל ק\"ק</b>: ברכות ח, א."],["120","9","<b>ורב שלום בניך</b>: ישעי' נד, יג."],["121","10","<b>א\"ת בניך אלא בוניך שעוסקים בבנינו של עולם</b>: ברכות סד, א. שבת קיד, א."],["122","11","<b>ואהי' אצלו אמון</b>: משלי ח, ל. וראה אוה\"ת ריש דברים. אוה\"ת ברכה ע' א'תתנו ואילך. ובכ\"מ."],["123","12","<b>ההוא צפרא דמצפצפא</b>: זח\"ג רנד, א. וראה ביאוה\"ז שם. אגה\"ק ס\"ה ובליקוט פירושים ומ\"מ שם."],["124","13","<b>והגית בה</b>: יהושע א, ח. וראה תו\"א מג\"א ק, ד. לקו\"ת שה\"ש לד, ג."]]],[2101000042,"<b>ולהבין</b><sup data-n=\"125\">14</sup> כ\"ז הנה יש להקדי' ענין א' בכללות סדר ההשתלשלות דע\"ס דאצי' המובא בס' המקובלים ובפרט בס' הפרדס ובע\"ח באופן סדרם זמ\"ז אשר לכאורה מצינו ב' אופנים מחולקים בדבריהם האופן הא' הוא אשר הע\"ס משתלשלי' זמ\"ז מלמעלה למטה שבהכרח לפ\"ז שהעליון עומד למעלה והמקבל הימנו עומד למטה הימנו וכן עד\"ז מעילה לעילה עד הספי' האחרונה דהיינו בחי' הכתר עומד עליון מכולם והחכ' מקבל מן הכתר למטה הימנו והבינה מקבל מן החכ' למטה הימנו והדעת למטה מן הבינה והמדות חג\"ת וענפיהן נו\"ה כו' עומדים למטה מג\"ר שנק' חב\"ד לקבל מהן והן הנק' ו\"ק או ז\"ת כו' ומבואר אופן זה בע\"ח ובפרדס בכמה דוכתי ובזהר<sup data-n=\"126\">15</sup> ג\"כ במא' עבד מאנא רברבא וקרא בה גרמי' חכם כו' שזהו כדמיון החפירה שנמשכת מן הנהר ומחפירה זאת נמשכה אל אחרת שלמטה הימנה כו' שבהכרח כאו\"א מקבל עפ\"י סדר ההילוך וההמשכה מעליון לתחתון כו' כנ\"ל. וביאור ענין זה הסדר של ההשתלשלו' יובן למעלה מבשרי אחזה כו' כמו עד\"מ בי' כחות הנפש המתלבשי' בכלים בגוף שדרך כללו' נחלקו לשנים ג' שכליי' חב\"ד וז' מדות הג' שכליי' הנה בחי' חכ' היא הנק' ראשית כי הנה בחי'<sup data-n=\"127\">16</sup> חכ' נק' כח מ\"ה להיותו בחי' אין כי הוא בחי' ראשי' יציאת גילוי איזה שכל וסברא מלמעלה מן השכל הנופלת לאדם כאשר ממציא איזה מושכל חדש אך עדיין לא בא לכלל השגה והבנה גמורה להסביר בטוב טעם אלא רק כמו הארה מבהקת בכח שכלו כדמיון הברק כו' אחר שעדיין אינו מושג כלום ולכך נק' כח מ\"ה כו' והוא בחי' יו\"ד דחכ' בבחי' נקודה העדר ההתפשטות כידוע ואח\"כ מסתעפת ונמשכת נקודה זו דחכ' לאורך ורוחב בהתפשטות והוא בחי' בינה שהוא השגת והבנת המושכל להסביר אותו בטוב טעם לאורך ורוחב בהתפשטות כו' והוא הה' שנעשה מן היו\"ד כידוע הרי הבינה מקבלת מן החכ' וכמו המעיין שנמשך ומתפשט בנהר כו' וכמ\"ש ונהר<sup data-n=\"128\">17</sup> יוצא מעדן כו' כידוע וה\"ז כמו העליון שמשפיע לתחתון כנ\"ל (וכמ\"ש יהי<sup data-n=\"129\">18</sup> רקיע בתוך המים ויבדל בין מים עליונים דחכ' למ\"ת דבינה כו') ועד\"ז הנה בחי' בינה נק' עליון לגבי המדות הנולדי' ומסתעפי' ממנה כנראה בחוש שכאשר יתבונן האדם דוקא בהפלגת איזה דבר טוב אזי יולד בלבו אהבה ולהיפך כשיתבונן בדבר רע יולד שנאה כו' וכידוע בעבודת ה' ג\"כ שמההתבוננו' בגדולת ה' יולד בלבו אהבה לה' כו' ובהיפך מהתבוננו' דכולא קמי' כלא יולד יראה שלא לילך אחרי ההבל כו' ומדת הניצוח נמשך מן האהבה כו' ונמצא כולן מקבלי' זמ\"ז וזה עליון מזה כו' וככה ממש יובן למשכיל למעלה בסדר ההשתלשלו' ע\"ס דאצי' שראשי' הגילוי באצי' מלמעלה הוא בחי' החכ' שנק' כח מ\"ה כי בה ראשי' גילוי עצמו' המאציל עד\"מ הברקת אור",[["125","14","<b>ולהבין. . בכללות סדר ההשתלשלות דע\"ס</b>: בהבא להלן ראה ג\"כ ביאוה\"ז להצ\"צ ע' ערה ואילך. לקו\"ת ואתחנן ה, א ואילך. סה\"מ תקס\"ח ע' קפד ואילך. ובכ\"מ. וראה במה שמצויין עוד לקמן על הפרדס."],["126","15","<b>ובזהר. . עבד מאנא רברבא</b>: ראה זח\"ב מב, ב."],["127","16","<b>בחי' חכמה נק' כח מ\"ה</b>: זח\"ג כח, א. לד, א. הקדמת ת\"ז בתחילתה. ובכ\"מ. וראה תניא פ\"ג ופי\"ח ובליקוט פירושים ומ\"מ שם."],["128","17","<b>ונהר יוצא מעדן</b>: בראשית ב, י. וראה זח\"ב קכג, ב. ובכ\"מ."],["129","18","<b>יהי רקיע בתוך המים</b>: ראה בראשית א, ו. וראה אוה\"ת בראשית כט, א. ובכ\"מ."]]],[2101000043,"השכל כאשר עדיין בלתי מושג כנ\"ל והוא בחי' יו\"ד דשם הוי' שאינו בבחי' יש כלל וכלל ואח\"כ מתפשט למטה בבינה שהוא ה\"א דשם הוי' כמא' מבין<sup data-n=\"130\">19</sup> ולא בבינה כו' שהוא בחי' המרחב של ההשגה כנ\"ל והוא שנק' אימא עילאה מפני שהיא אם הבנים שהן בחי' ו\"ק דז\"א שנולדי' מבינה והיינו בחי' מדות עליונות חג\"ת דאצי' שנולדי' מבינה והוא הוי\"ו דשם הוי' כידוע וכ\"ז הולך בסדר השתלשלו' מעליון לתחתון דוקא כנ\"ל וד\"ל. והאופן השני בסדר ההשתלשלות דע\"ס דאצי' הוא היפך אופן סדר הראשון שאין הע\"ס מקבלי' דרך ירידה מזה לזה אלא כמבואר<sup data-n=\"131\">20</sup> הציור שלהן בפרדס ובע\"ח בכמה דוכתי שבאין בציור ג' קוין מחולקים זמ\"ז והוא קו א' שעומד לימין חח\"נ החכ' למעלה והחסד למטה הימנו והנצח למטה מן החסד ועד\"ז בקו השמאל בג\"ה בינה למעלה ותחתיה גבורה ותחת הגבורה הוד כו' ועד\"ז קו האמצעי דת\"י דעת למעלה ותחתיו ת\"ת ותחתיו יסוד שנמצא אין המדות מקבלים מבינה בלבד כנ\"ל בסדר הא' אלא החסד עומד בקו שלו והגבורה בקו שלו וגם בג\"ר חב\"ד אין הבינה מקבלת מן החכ' כנ\"ל בסדר אופן הא' אלא החכ' עומד בקו הימין לעצמו והבינה עומדת בקו השמאל מובדל בפ\"ע בלתי יש שייכות וחיבור זע\"ז והדעת גם הוא עומד בקו האמצעי מובדל בפ\"ע ואינו מקבל מחו\"ב שמימין ושמאל כו' ונמצא ציור אופן זה משונה לגמרי מאופן הראשון. והנה עיקר ההפרש אשר בין שני אופני' הנ\"ל הוא בבחי' הדעת בב' דברים הא' בבחי' הדעת עצמו באופן סדרו ועמידתו והב' בבחי' המדות המסתעפי' ע\"י הדעת. והנה בבחי' הדעת עצמו ההפרש הוא כך שלפי אופן הא' שג\"ר חב\"ד עומדים זה למטה מזה שנמצא הדעת למטה מחו\"ב ועליון מן המדות היינו שהוא בחי' ממוצע שהוא מקבל מבינה וממשיך השפע למדות וע\"כ עמידתו למטה מחו\"ב לקבל הארתם ולהשפיע אותם למדות שתחתיו (ומתחלה הוא כמו סגול זה. .. וכאשר מתהפך להאיר במדות נעשה כסגול זה. .. וכמשי\"ת שזהו העולה מב' האופנים הנ\"ל וד\"ל) משא\"כ לפי אופן הב' הרי הדעת עומד בקו האמצעי בשוה לב' הקוין חו\"ב ואינו עומד תחתיהם כלל לקבל אלא מקבל גם הוא מאור הכתר כמו חו\"ב והיינו שאינו מקבל שפע מחו\"ב אלא מאור הכתר להאיר בחו\"ב (ונק' דעת עליון כמשי\"ת בעזר\"ה). וההפרש הב' בין שני האופני' הנ\"ל הוא בבחי' המדות שמקבלי' ע\"י הדעת דלפי אופן הא' עיקר התהוות מציאות התפעלו' המדות נולד מחו\"ב ע\"י הדעת כנ\"ל שהדעת הוא בחי' ממוצע להביא הארת השכל להוליד המדות אבל לפי אופן וסדר הב' הרי לפי עמידת מקום הדעת תחת הכתר כמו חו\"ב בהכרח לומר שע\"י הדעת הזה נמשך הארת הכתר במדות ולא הארת חו\"ב כו'. וכ\"ז ההפרש אשר בין ב' אופנים המחולקי' הנ\"ל הנה באמת יובן למשכיל דב' האופנים הנ\"ל אמת ולא סתרי אהדדי כלל. אך יש להקדי' תחלה במהות בחי' הדעת שנחלק לב' מדריגות הא' הנק' דעת עליון שמחבר לחו\"ב וכמארז\"ל גדולה<sup data-n=\"132\">21</sup> דיעה שניתנה בין ב' אותיו' י\"ה חו\"ב וכתיב כי אל דעות<sup data-n=\"133\">22</sup> הוי' ב' דעות שיש עוד בחי' דעת הנק'",[["130","19","<b>מבין ולא בבינה כו'</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."],["131","20","<b>כמבואר הציור שלהן בפרדס</b>: פרדס ש\"ו פ\"א ואילך."],["132","21","<b>גדולה דיעה שניתנה בין ב' אותיו'</b>: ברכות לג, א. סנהדרין צב, א."],["133","22","<b>כי אל דעות ה'</b>: שמואל-א ב, ג."]]],[2101000044,"דעת תחתון ונק' בזוהר דעת דבין ב' כתפין כו' המחבר למדות חו\"ג כו' וביאור ענינם ידוע שבחי' דעת עליון הוא שנמשך מבחי' הכתר עצמו כמו שנמצא החכ' מן אור הכתר וכמ\"ש והחכ'<sup data-n=\"134\">23</sup> מאין תמצא כו' וע\"כ יש ביכולתו לחבר לחו\"ב ביחד ע\"י הארת הכתר שלמעלה משניהם (ומבשרי אחזה כו' בחי' התקשרות אשר ברצון שנק' כתר באיזה מושכל הנולד מן רצון יביא וימשיך גילוי אור שכל זה לידי הבנה והשגה בהרחבה גדולה וכנראה בחוש בכל חשק לאיזה לימוד שכלי ע\"י התקשרותו בה יוכל להבין ולהשכיל בהרחבה כל דבר הנעלם ולא נגלה רק אפס קציהו כו' וזה נק' יחוד חו\"ב שע\"י דעת עליון המזווגם יחד כו' וד\"ל), ובחי' דעת תחתון הוא המתפשט במדות חו\"ג להחיותם מאור וחיות שכלי שבחו\"ב כי בחי' דעת זה הוא בחי' התקשרות והרגשת שכל המושג בבינה כמ\"ש<sup data-n=\"135\">24</sup> במ\"א בענין דעת דגניז בפומא כו' וע\"כ הוא ממוצע להביא ולהמשיך למדות כמו דעת נוטה לחסד כו' וע\"כ ביכולתו לחבר חו\"ג להיותו למעלה מהם ולמטה הוא מחו\"ב כו' וד\"ל.\n<b>והנה</b> ידוע שיש ג\"כ ב' מדריגות במדות הא' בחי' המדות חג\"ת כו' שנולדים מן השכל וההתבוננו' דוקא עד שאם לא הי' מתבונן בטוב הדבר ההוא לא יהי' מתפעל באהבה כלל לאותו הדבר ולפי שכלו יהולל איש שלפי ערך השכל כך ערך מציאת התפעלות המדות כידוע להיות עיקר מציאתן רק מן השכל כידוע, והב' בחי' המדות שעיקר מציאותם הוא למעלה מן השכל דוקא דהיינו שאין התהוות עיקר מציאותם נולדה מן השכל כי גם אם השכל יחייב ההיפוך ממש מ\"מ לא תזוז התפעלות המדה אפי' כמלא נימא להיות שרשם בבחי' הכתר שנק' רצון כמו האהבה שברצון העצמי שלמעלה מן השכל כי כאשר ירצה ברצון לקרב ולדבק איזה דבר הנאהב לו ברצונו שלמעלה מן השכל נק' אהבה זו אה\"ר בלתי מוגבלת בשכל כלל וכלל כידוע וכן יש כל המדות שלמטה מן השכל למעלה ברצון כידוע ונק'<sup data-n=\"136\">25</sup> ימי קדם או הרי קדם ובזוהר<sup data-n=\"137\">26</sup> נק' טורי חשוכא כו' ויש לבחי' המדות שלמטה מן השכל שרש במדות הללו שבכתר וז\"ש<sup data-n=\"138\">27</sup> בזוהר בכמה דוכתי דז\"א דאצי' בעתיק אחיד ותלי' פי' יותר מאו\"א אחיד ז\"א בעתיקא לפי ששרש המדות דז\"א הוא ממש בחי' המדות דע\"י וא\"א ושם אחידן ותלי' ושרש או\"א אינו אלא מבחי' הארת נה\"י דא\"א כו' רק שאו\"א מלבישים לזרועו'<sup data-n=\"139\">28</sup> דא\"א כו' אבל ז\"א בעתיקא עצמו אחיד כו' אך הנה מ\"מ כאשר יוצאין בחי' המדות דע\"י וא\"א למטה בהכרח שיהיו עוברין דרך השכל בדרך מעבר עכ\"פ אבל לא שיהי' עיקר מציאותן מן השכל וכמ\"ש במ\"א",[["134","23","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["135","24","<b>כמ\"ש במ\"א בענין דעת דגניז בפומא</b>: זח\"ב קכג, א."],["136","25","<b>ונק' ימי קדם</b>: זח\"ג רח, ב. קלד, ב. וראה ג\"כ תו\"א ויקהל פז, ד. אוה\"ת דרושים לחנוכה כרך ה' תתקס, ב. אוה\"ת תזריע ע' רסה."],["137","26","<b>ובזוהר נק' טורי חשוכא</b>: זח\"ג רח, ב. רמט, ב. וראה ביאוה\"ז שם. לקו\"ת מטות פז, ג. דרושים לשמ\"ע פו, ד. אוה\"ת דרושים לסוכות ע' א'תשסט."],["138","27","<b>וז\"ש בזוהר בכמה דוכתי דז\"א דאצי' בעתיק אחיד ותליא</b>: זח\"ג רצב, א. וראה בארוכה להלן בהביאורים לד\"ה זכור את יום השבת. לקו\"ת ס\"פ שמיני. ובכ\"מ."],["139","28","<b>שאו\"א מלבישים לזרועות דא\"א</b>: ע\"ח שער או\"א פ\"א. שער הולדת או\"א פ\"ו. שער הנסירה פ\"ו. פע\"ח שער חגהמ\"צ פ\"ז."]]],[2101000045,"באריכות וד\"ל. ואחר הקדמה זאת יובן ענין ההפרש בב' דברי' אשר בין שני האופנים המחולקים הנ\"ל ששניהם אמת ואינם מחולקי' כלל וכלל דהנה אופן הא' הנז' בפרד\"ס וע\"ח שהע\"ס זה למטה מזה והדעת ממוצע למטה מחו\"ב ולמעלה מן המדות כנ\"ל הוא מדבר בבחי' המדות שלמטה מן השכל כנ\"ל ולהיות עיקר מציאותם מן השכל כנ\"ל ע\"כ בחי' הדעת עומד עליהם להמשיך בהן השכל מחו\"ב וא\"כ בהכרח שדעת זה עומד למטה מבינה כנ\"ל ונק' דעת תחתון דעת דבין כתפין כו' כנ\"ל. אבל אופן הב' הנז' בפרד\"ס וע\"ח דהדעת עומד בין חו\"ב תחת הכתר כנ\"ל היינו מפני שמדבר בבחי' המדות שאין עיקר מציאותם מן השכל אלא מלמעלה מן השכל דהיינו במדות שבכתר שלמעלה הרבה מחו\"ב כנ\"ל בפי' המאמר דז\"א בע\"י אחיד כו' ונמצא בחי' דעת זה נק' דעת עליון דכתר כמ\"ש ויודע<sup data-n=\"140\">29</sup> דעת עליון כו' שמחבר לחו\"ב כנ\"ל להמשיך הארת הכתר במדות כנ\"ל והוא ענין ציור הג' קוין חח\"נ מימין כו' והדעת שבין חו\"ב שרשו בכתר להמשיך אור הכתר בחו\"ב כי עולה עד דעת שבכתר עצמו כו' (היינו כמו הסגול העליון כזה. .. ובאופן הא' מתהפך ונעשה סגול התחתון כזה. .. שהדעת למטה מחו\"ב שנק' דעת תחתון ושניהם אמת כי שרש א' להם וז\"ש ישראל<sup data-n=\"141\">30</sup> לסגולתו מפני שבחי' דעת דז\"א שרשו בדעת העליון כו' (ומארז\"ל גדולה דיעה שניתנה בין ב' אותיות י\"ה יתפרש ג\"כ בב' אופנים הא' כשהדעת למעלה מחו\"ב והב' כשהוא למטה מחו\"ב להאיר במדות כמ\"ש כי אל דעות ה' כו' ב' דיעות ושרשם א' וד\"ל) ונמצא יש ג' אופנים הא' כמו סגול העליון. .. שהוא בדעת עליון שלמעלה מחו\"ב כנ\"ל והב' סגול התחתון שהדעת למטה מחו\"ב כזה. .. והג' כאשר הדעת למעלה מחו\"ג ונק' דעת המתפשט במדות שהוא כמו סגול העליון ג\"כ כזה. .. וז\"ש ישראל לסגולתו לסגול העליון כי מה שהדעת מחבר לחו\"ג הוא מפני שרשו בדעת עליון שמחבר לחו\"ב כו' וד\"ל).\n<b>ואמנם</b> <sup data-n=\"142\">31</sup> י\"ל בתוס' ביאור ענין ובחי' מהות הדעת מהו, ומתחלה י\"ל בבחי' דעת התחתון הנ\"ל המתפשט במדות ומתוכו יובן ג\"כ בבחי' ד\"ע הנ\"ל דהנה מבואר למעלה באופן הא' דהע\"ס הן זת\"ז והדעת ממשיך הארת השכל במדות עד שיהי' לפי ערך השכל ממש כנ\"ל וא\"כ לכאורה אינו מובן מה צריכים לבחי' הדעת הלא מן השכל וההתבוננו' עצמה כשיתבונן בטוב הדבר הרי יתפעל באהבה לדבר ההוא ומהו ענין הדעת ואם להיות ממוצע בין השכל ובין ההתפעלות מה צורך לבחי' ממוצע כלל. אך הענין הוא דתועלת הדעת אינו בשביל ממוצע בלבד אלא כדי להיות בחי' המשכה פנימי' במדות מן השכל ולא בחי' המשכה חיצוניו' ואם לא בחי' הדעת הממוצע בין השכל והתפעלו' המדו' הי' בחי' התפעלו' המדות מן התבוננות בבחי' המשכה חיצוניו' אך בחי' הדעת הוא הממשיך בחי' המשכה פנימיו' במדות והיינו דעת תחתון שהוא בחי' הדעת המתפשט במדות שממשיך בהן בחי' המשכה פנימיו' להיות כי הדעת בכל מקום הוא נמשך מבחי' הפנימי' והמופת לזה ידוע",[["140","29","<b>ויודע דעת עליון</b>: במדבר כד, טז."],["141","30","<b>ישראל לסגולתו</b>: תהלים קלה, ד."],["142","31","<b>ואמנם י\"ל בתוס' ביאור ענין ובחי' מהות הדעת</b>: ראה בהנסמן לעיל ע' טו בקטע: ולהבין כללות סדר ההשתלשלות. תניא פ\"ג ובליקוט פירושים ומ\"מ שם."]]],[2101000046,"מאשר אנו רואים בהפרש התפעלות המדות של התינוק להתפעלות של המדות של הגדול דגם שמצד תולדות המדות מן השכל וההתבוננו' אחת היא בקטן כמו בגדול אך ורק ההפרש ביניהם הוא הדעת שבקטן עדיין אין הדעת מתפשט במדות כמארז\"ל קטן<sup data-n=\"143\">32</sup> אין לו מחשבה שהוא הדעת ע\"כ אין בהתפעלו' מדותיו המשכה פנימיו' מן השכל רק חיצוניו' ההארה וע\"כ אין תוקף כלל במדותיו כמו שידוע שבנקל לפתות הקטנים והנשים מפני<sup data-n=\"144\">33</sup> שדעתן קלות כו' משא\"כ בגדול שהתפעלו' מדותיו עפ\"י בחי' הדעת יש תוקף גדול למדותיו כי הדעת ממשיך בהן חיות פנימי ביותר ולא יתפתו להתהפך מלאו להן או להיפך ולכך אין הקטן פחות מי\"ג בר עונשין (כי שס\"ה ל\"ת נמשך מצד היראה ורמ\"ח מ\"ע מצד האהבה שהן ה\"ח וה<sup data-n=\"145\">34</sup>\"ג ובקטן לא נשלמו חו\"ג שלו עפ\"י הדעת אבל יותר מי\"ג גם שהוא ע\"ה דעתו מתפשט בחו\"ג כו' וד\"ל).\n<b>ועוד</b> זאת יש הפרש בין התפעלו' המדות מן השכל וההתבוננו' בלא דעת להתפעלו' המדות ע\"י הדעת בעצם התפעלו' המדות שמתפעלי' ע\"י הדעת בבחי' פנימי' יותר והוא הנק' פנימי' המדות ובלא דעת מתפעלי' רק בבחי' חיצוני' בלבד (והא בהא תלי' משום שהדעת ממשיך חיות פנימיות בהן מן השכל ע\"כ מוליד בהן בחי' הפנימי' שלהן כי פנימי' המדות תלוי בפנימי' השכל כו' והכל שרש וענין א' וד\"ל) וההפרש בין בחי' פנימי' המדות לחיצוני' שלהם ידוע דבפנימי' שלהם מובדל הטוב מן הרע ואין שם בחי' תערובו' כלל אלא בתכלית הבירור כי הדעת המתפשט בהן מברר אותם בתכלית הבירור (וע\"כ נק' הדעת דרך כלל בשם פנימי' המדו' להיותו מבדיל בהן בחי' הפנימי' כו' אעפ\"י דלגבי השכל עצמו נק' הדעת עצמו בחי' חיצוני' כנ\"ל שנק' ממוצע כו' וכמ\"ש במ\"א) ובלא דעת מקבלים המדות מן השכל בבחי' תערובו' בלי בירור כלל להיות כי נמשך בהן הארה חיצוני' בלבד אך ע\"י הדעת נמשך בהן בחי' פנימי' כנ\"ל והוא המבדיל ומברר במדות בין טוב לרע שלא יתערבו כ\"כ עד שיוכל להיות מן האמת שקר כו' וד\"ל.\n<b>וביאור</b> ענין בחי' התערובו' הזאת במדות הנה יובן בדוגמא למעלה מהמדות אוי\"ר בעבודה שבלב זו תפלה דהנה אנו רואים דגם שיתפעל אדם באהבה כרשפי אש בתפלה הנה מיד אחר התפלה בשומו לבו בעניני' גשמיי' יתלהב לבו ג\"כ אליהם או כאשר יפגע אדם בכבודו או בממונו יתפעל בכעס כידוע ואם היתה התפעלו' האהבה בתפלה בתכלי' הבירור רק לה' לבדו כו' מאין יבא לו התלהבות לדבר זר מיד או לכעוס בעבור כבודו וממונו אלא מוכרח לומר שגם בעת התפעלותו בתפלה לא הי' בתכלית הבירור אלא שהי' מעורב טו\"ר דהיינו שלא הי' אמת רק לה' לבדו אלא בתערובו' דבר זר כדי להיות איזה דבר ויש וכדומה וגם בעצם התפעלותו איננה לתכלית האמת לעומקא דלבא אלא רק בבחי' חיצוני' הלב",[["143","32","חולין יב, ב."],["144","33","<b>מפני שדעתן קלות</b>: ראה שבת לג, ב. ובכ\"מ."],["145","34","<b>ה\"ח וה\"ג</b>: תיבות אלו אינן ברורות בהכת\"י. ובכת\"י ב: שהן הח' והג'. ובכת\"י ג: חסדי' וגבורו'."]]],[2101000047,"בלבד ע\"כ תתפעל הלב מיד גם להיפך כו' אבל אם הדעת הוא המתפשט במדות עושה בהתפעלו' הלב בירור גדול להיותו בחי' פנימי' המדות (וז\"ש ישראל <sup data-n=\"146\">35</sup> לא ידע כו' הוי גוי חוטא דהא בהא תלי' וכמ<sup data-n=\"147\">36</sup>\"ש במ\"א ע\"פ דע את אלקי כו') וזהו ההפרש בין בחי' מוחין דקטנות לבחי' מוחין דגדלות למעלה שמבחי' מוחין דקטנות יש אחיזה ויניקה לחיצוני' כענין אברהם<sup data-n=\"148\">37</sup> יצא ממנו ישמעאל כו' לפי שבחי' אחוריי' דשם אלקים הוא המסתיר על אור האלקי עד שיוכל להיות נפרד כידוע ובבחי' מוחין דקטנות שבלא דעת הרי בחי' הפנימי' מוסתר ונעלם ומבחי' חיצוני' ואחוריי' של המדות העליונים יכולים גם החיצונים לקבל אבל בבחי' מוחין דגדלות שהוא הארת הדעת במדות אין שם מקום ליניקת החיצונים כלל מפני שבבחי' הפנימי' של המדות אין שם מקום לחיצונים להיותם רק מבחי' אחוריי' וחיצוניו' כידוע<sup data-n=\"149\">38</sup> בענין בא נחש על חוה שהוא בחי' אחוריי' דשם ב\"ן וכמ\"ש מלך<sup data-n=\"150\">39</sup> אלקים על גוים כו' (וזהו שנאמר בגלות מצרים וידע<sup data-n=\"151\">40</sup> אלקים כו' ולזה רמזו רז\"ל יעקב<sup data-n=\"152\">41</sup> משמש במרום וכמ\"ש שאו <sup data-n=\"153\">42</sup> מרום וראו מי ברא אלה פי' אלה הן ו\"ק דז\"א בבחי' הקטנות ולהעלות שרשם במ\"י דבינה היינו ע\"י הדעת שנק' מרום לגבי המדות וזהו שאו מרום כו' וז\"ש ואתה<sup data-n=\"154\">43</sup> מרום לעולם ה' כו' ואז כי הנה אויביך יאבדו כו' וכמ\"ש במ\"א וד\"ל) וז\"ש לא<sup data-n=\"155\">44</sup> יחפוץ כסיל בתבונה מפני שהוא מתאחד עם הדעת כמ\"ש מפיו<sup data-n=\"156\">45</sup> דעת ותבונה פי' מפיו מפומא דאימא כו' שנק'<sup data-n=\"157\">46</sup> קולו של משה כמ\"ש במ\"א) וז\"ש ג\"כ איש<sup data-n=\"158\">47</sup> בער לא ידע כו' כי<sup data-n=\"159\">48</sup> אל אחר אסתרס כו' כמארז\"ל צינן<sup data-n=\"160\">49</sup> את הזכר כו' לפי שאינם יכולים לקבל מבחי' הדעת מטעם הנ\"ל.\n<b>ולהבין</b> בתוס' ביאור ענין בחי' תערובות טו\"ר שבמדות גם שמתפעל באהבה ודביקות כנ\"ל הנה יש להקדי' ההוא<sup data-n=\"161\">50</sup> עובדא דר\"י בן קסמא עם ר\"ח בן תרדיון הנז' בגמרא ששאל רחב\"ת לריב\"ק מה אני לעוה\"ב והשיבו כלום מעשה בא לידך וא\"ל רחב\"ת מעות של פורים נתחלפו לי במעות של צדקה כו' ולכאורה יש",[["146","35","<b>ישראל לא ידע. . חוטא</b>: ישעי' א, ג-ד."],["147","36","<b>וכמ\"ש במ\"א ע\"פ דע את אלקי כו'</b>: דה\"א כח, ט. וראה סידור שער הלולב רסג, ד."],["148","37","<b>אברהם יצא ממנו ישמעאל</b>: פסחים נו, א. ויק\"ר פל\"ו, ה. ספרי ואתחנן ו, ד. ועוד. וראה ג\"כ לקו\"ת ואתחנן ה, א (נסמן לעיל). תו\"ח ר\"פ תולדות. ובכ\"מ. להלן ד\"ה יונתי."],["149","38","<b>כידוע בענין בא נחש על חוה</b>: שבת קמו, א. זח\"א כח, ב. קכו, ב. ובכ\"מ. וראה סה\"מ תקס\"ו ע' ר."],["150","39","<b>מלך אלקים על גוים</b>: תהלים מז, ט."],["151","40","<b>וידע אלקים</b>: שמות ב, כה."],["152","41","<b>יעקב משמש במרום</b>: זח\"א קלג, א. וראה בארוכה ביאוה\"ז יג, ד ואילך. אוה\"ת קדושים ע' קי. ובכ\"מ."],["153","42","<b>שאו מרום עיניכם וראו מי ברא אלה</b>: ישעי' מ, כו. וראה לקו\"ת פקודי ד, ג. ובכ\"מ."],["154","43","<b>ואתה מרום. . כי הנה אויביך</b>: תהלים צב, ט ואילך."],["155","44","<b>לא יחפוץ כסיל בתבונה</b>: משלי יח, ב."],["156","45","<b>מפיו דעת ותבונה</b>: משלי ב, ו."],["157","46","<b>שנק' קולו של משה</b>: ראה ברכות מה, א. וראה תו\"א יתרו סז, ד. תו\"ח ואוה\"ת שם. סה\"מ תקס\"ו ע' רד."],["158","47","<b>איש בער לא ידע</b>: תהלים צב, ז."],["159","48","<b>כי אל אחר אסתרס</b>: זח\"ב קג, א."],["160","49","<b>צינן את הזכר</b>: ראה ב\"ב עד, ב."],["161","50","<b>ההוא עובדא דר\"י בן קיסמא</b>: ע\"ז יח, א. וראה ג\"כ לקו\"ת ראה כב, ב."]]],[2101000048,"כאן דקדוקים גדולים דהלא רחב\"ת הי' מוסר נפשו על עסק התורה כמ\"ש ריב\"ק לרחב\"ת חושש אני שלא ישרפו אותך וס\"ת שבחיקך כו' וא\"כ איזה צד ספק הי' לרחב\"ת לשאול מהו לעוה\"ב ועוד יפלא על התשובה מה זו שהשיבו כלום מעשה בא לידך וא\"ל מעשה הצדקה ואז א\"ל ריב\"ק א\"כ מחלקך יהא חלקי כו' שמובן מזה דכל מס\"נ שלו על התורה עדיין לא נודע ברור שהוא בן העוה\"ב אלא דוקא ע\"י מעשה הצדקה שלו כו'. אך כ\"ז יובן בהקדי' מארז\"ל ע\"פ ושבתם וראיתם<sup data-n=\"162\">51</sup> בין עובד אלקי' לאשר לא עבדו דאינו דומה שונה פרקו מאה פעמי' לק' פעמי' וא' צא ולמד מחמרים י' פרסא בזוזא י\"א פרסא כו' דלכאורה אין מהראוי לומר על השונה ק' פעמים שלא יהי' נק' עובד אלקי' בשביל חסרון פ\"א שישנה עוד ומיד שישנה פ\"א יתר על ק' בזה יקרא עובד אלקי' אך הענין ידוע ומבואר<sup data-n=\"163\">52</sup> ג\"כ בלק\"א שהכונה אינה בשביל הוספת הלימוד פ\"א אלא מפני שהוא יותר על הרגילות כי<sup data-n=\"164\">53</sup> ההרגל נעשה טבע שני כידוע ובמספר החזרה שהוא רגיל בו נעשה אצלו כמו טבעי' והעיקר של עובד אלקי' הוא להפוך הטבע דוקא כי<sup data-n=\"165\">54</sup> הטבע בגי' אלקי' ובהיפוך הטבע ללמוד יותר מטבע רגילותו נק' עובד אלקים פי' עובד שמתקן לשם אלקים שבנוגה והיינו ע\"י אתכפי' ואתהפכ' חשוכא כו' אז נק' עובד אלקי' דהיינו להפוך טבע המדות דנוגה אבל כשעובד ה' עפ\"י טבע מדותיו הבהמיו' דנוגה גם ששונה פרקו ק' פעמים אינו נק' עובד אלקים מטעם שאינו מתקן דבר חדש בשם אלקים המלובש בנוגה כנ\"ל וד\"ל ועפי\"ז יובן ג\"כ בכל הפלגת הטוב גם בהפלאה גדולה כמו מי שתשוקתו מאד נפלאה לעסוק בתורה יום ולילה גם כבן<sup data-n=\"166\">55</sup> עזאי שנפשו חשקה בתורה כו' הרי יוכל להיות שמוטבע בנפשו הבהמיו' ג\"כ להפלגת שקידה זאת בחכמה אחרת שאינה תורה ובעסק התורה גם שעוסק בה לשמה ובמס\"נ כרחב\"ת ובן עזאי כו' הרי מצורף בזה הסכם טבעו הגשמי' ומפני הסכם טבע נפשו הבהמי' דנוגה לעסק זה ע\"כ יוכל לפקפק גם בנפשו האלקי' אם היא מס\"נ אמיתי' הגם שכוונתו רצויי' לה' לבדו בדביקו' ותשוקה נפלאה וכמו ששונה פרקו ק' פעמים שאינו נק' עובד אלקי' מטעם הנ\"ל כי לא נהפך טבעו עדיין ולא תיקן ועשה כלום והעיקר הוא לאהפכ' חשוכא לנהורא כו' שהוא למסור נפשו הבהמי' ג\"כ והוא כאשר יהא נגד הטבע האנושי' דוקא כמו ק\"א פעמים שהוא יותר על הרגילות כנ\"ל וד\"ל, ובכיוצא בזה יובן ג\"כ דגם בהפלגת עבודה שבלב זו תפלה דכאשר הפלגות ההתפעלו' אוי\"ר היא לפי הסכם טבע נפשו הבהמיו' אינו נק' עובד אלקי' כי טבעו מסכים בזה אלא דוקא כשמתפעל באוי\"ר שכנגד הטבע האנושי' וכמ\"ש כלה<sup data-n=\"167\">56</sup> שארי ולבבי כו' מי לי בשמי<sup data-n=\"168\">57</sup>ם ועמך לא חפצתי כו' שמבטל כל רצונות הזרות הטבעיי' כמא' בטל<sup data-n=\"169\">58</sup> רצונך מפני רצונו כו' וכיוצא בזה וד\"ל.",[["162","51","<b>מארז\"ל ע\"פ ושבתם וראיתם</b>: מלאכי ג, יח. חגיגה ט, ב."],["163","52","<b>ומבואר ג\"כ בלק\"א</b>: פט\"ו. וראה ליקוט פירושים ומ\"מ שם."],["164","53","<b>כי ההרגל נעשה טבע שני</b>: שבילי אמונה נ\"ד ש\"ב. וראה שו\"ת הרמ\"ע מפאנו סל\"ו. תניא פי\"ד (וראה ג\"כ פמ\"ד)."],["165","54","<b>כי הטבע בגי' אלקים</b>: פרדס שי\"ב פ\"ב. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"א ע' 150."],["166","55","<b>כבן עזאי שנפשו חשקה בתורה</b>: יבמות סג, ב."],["167","56","<b>כלה שארי ולבבי</b>: תהלים עג, כו."],["168","57","<b>מי לי בשמים</b>: תהלים עג, כה."],["169","58","<b>בטל רצונך מפני רצונו</b>: אבות פ\"ב מ\"ד."]]],[2101000049,"<b>ולהבין</b> בתוס' ביאור ענין עובד אלקי' ולמה נק' בשם עובד דוקא ולא בשם אוהב ולמה לא אמר עובד הוי' כו' הנה יש להקדים מ\"ש כי<sup data-n=\"170\">59</sup> שמש ומגן ה' אלקים פי' שם אלקים נק' בחי' מגן ונרתק לשם הוי' והענין הוא כי שם הוי' כולל כל האצי' יו\"ד בחכ' ה\"א בינה כו' כידוע ובאצי' אמרו דאיהו<sup data-n=\"171\">60</sup> וחיוהי וגרמוהי חד פי' חיוהי וגרמוהי הן או\"כ כי גם בחי' הכלים שהן האותיו' שבאצי' אינם מסתירים לגמרי על אא\"ס שבאצי' וכולם מתאחדי' בעצמו' המאציל כשלהבת<sup data-n=\"172\">61</sup> הקשורה בגחלת כמ\"ש בס\"י אבל שם אלקים נק' מגן ונרתק לשם הוי' דאצי' להעלים ולהסתיר האור העצמי כידוע ומבואר בע\"ח דבחי'<sup data-n=\"173\">62</sup> מל' דאצי' שהוא שם אלקי' נק' כסא והיינו כס א' שמכסה ומעלים לאורו' דאצי' והוא הנק' מסך ופרגוד שבין אצי' לבריאה שנעשה ע\"י בחי' מל' דאצי' והוא הנק' מגן ונרתק לשם הוי' אך התהוות הנשמות ומלאכים דבי\"ע מאין ליש הוא נמשך מבחי' יחוד הוי' ואלקי' כאשר עדיין לא נבדל במסך ופרגוד והיינו בחי' ע\"ב צירופי' העליוני' דמל' אשר בשם אלקים אבל מ\"ח צירופי' התחתונים שבשם אלקי' מתלבש להיות ראש ומקור לע' שרים דנוגה וזהו אותות ומופתים באדמת בני חם שהם מ\"ח צירופי' האחרונים שמקבלים מאלקי' דקדושה ונק' אלקים אחרים להיותם מקבלים מבחי' אחוריי' דשם אלקי' כנ\"ל בפי' מלך אלקים על גוים כו' ולזה רמזו רז\"ל בכמה דוכתי באמר' שמעתי<sup data-n=\"174\">63</sup> אחורי הפרגוד כו' והיינו עוצם בחי' ההסתר להסתיר ולהעלים אור אלקי ונק'<sup data-n=\"175\">64</sup> לבוש שק וכמ\"ש ושק<sup data-n=\"176\">65</sup> אשים כסותם עד שיוכל להיות מציאת נפרד גמור כו' כידוע וד\"ל.\n<b>והנה</b><sup data-n=\"177\">66</sup> ידוע דשרש נה\"ב שבאדם נמשכה מנוגה דעשי' פני שור כו' שבבחי' אחוריי' דשם אלקי' במ\"ח צירופי' האחרונים שמאיר בשר של אותה המדינה כו' ושרש נה\"א נמשכה מבחי' פנימי' יחוד דה' אלקים שנק' אדם כמ\"ש וזרעתי<sup data-n=\"178\">67</sup> כו' זרע אדם כו' אתם<sup data-n=\"179\">68</sup> קרויים אדם כו' וא\"כ בכל ניצוץ האלקי מאיר מבחי' שם הוי' שמתייחד בשם אלקים וז\"ש כי<sup data-n=\"180\">69</sup> חלק הוי' עמו כו' אשרי<sup data-n=\"181\">70</sup> העם שה'",[["170","59","<b>כי שמש ומגן ה' אלקים</b>: תהלים פד, יב. וראה שעהיחוה\"א פ\"ד ואילך. תו\"א בראשית ד, ד ואילך. ובכ\"מ."],["171","60","<b>דאיהו וחיוהי וגרמוהי חד</b>: ת\"ז בהקדמה לפני ד\"ה קום יחזקאל."],["172","61","<b>כשלהבת הקשורה בגחלת כמ\"ש בס\"י</b>: פ\"א מ\"ז."],["173","62","<b>דבחי' מל' דאצי'. . נק' כסא</b>: ראה ג\"כ סה\"מ תקס\"ח ע' קנב. ביאוה\"ז להצ\"צ כרך ב' ע' תתח ואילך. ובכ\"מ."],["174","63","<b>שמעתי אחורי הפרגוד</b>: ראה חגיגה טו, א. סנהדרין פט, ב. ובכ\"מ."],["175","64","<b>ונק' לבוש שק</b>: ראה תניא פי\"ט ובליקוט פירושים ומ\"מ שם."],["176","65","<b>ושק אשים כסותם</b>: ישעי' נ, ג. וראה סידור שער המילה קמה, ג. תו\"א וישלח כד, ג. לקו\"ת שה\"ש יח, ד. ובכ\"מ."],["177","66","<b>והנה ידוע דשרש נה\"ב שבאדם</b>: ראה זח\"א כ, ב. ובכ\"מ."],["178","67","<b>וזרעתי כו' זרע אדם</b>: ירמי' לא, כז."],["179","68","<b>אתם קרוים אדם</b>: זח\"א שם. ובכ\"מ. וראה תניא פכ\"ט ובליקוט פירושים ומ\"מ שם."],["180","69","<b>כי חלק ה' עמו</b>: דברים לב, ט."],["181","70","<b>אשרי העם שה' אלקיו</b>: תהלים קמד, טו. בכמה כת\"י: אשרי הגוי אשר ה' אלקיו עמו. ראה תהלים לג, יב."]]],[2101000050,"אלקיו וכידוע ובכל נה\"ב שורה מבחי' צמצום והסתר דאלקים אחרים דנוגה וכאשר האדם עובד ה' בנה\"א באוי\"ר בתורה ותפלה אזי מאיר גילוי אור הוי' דאצי' בנפשו כמ\"ש כי<sup data-n=\"182\">71</sup> אתה תאיר נרי כי נר<sup data-n=\"183\">72</sup> הוי' נשמת אדם כו' אך אם התפעלו' האוי\"ר יש בה ג\"כ מתערובו' הסכם נה\"ב ששרשה מאלקי' אחרים דנוגה הרי לא נתהפך בחי' ההסתר דנוגה עדיין והרי בחי' צמצום והסתר זה מסתיר ומעלים על גילוי אור שם הוי' שמאיר בנפשו האלקי' וא\"כ אינו נק' עובד אלקים אלא עובד הוי' וגם לא עובד אלא אוהב כי<sup data-n=\"184\">73</sup> פי' עבודה הוא כמו עורות עבודין שמתקנן ומסיר מהם כל פסולת עד שנעשו בתכלית הבירור כו' וגם כאן פי' עובד אלקים היינו שמתקן להסיר כל סיג ופסולת של יניקות החיצוני' שיונקים ומקבלים ממנו שהוא להסיר כל בחי' צמצום והסתר דאלקי' אחרים ואין זה אלא ע\"י אתכפי' כו' דהיינו להתפעל נגד הטבע האנושי' להיות בנפשו הבהמי' בחי' ביטול היש בתכלית והיינו כענין הנ\"ל בפי' שונה פרקו ק\"פ שאינו נק' עובד אלקי' אלא בק\"א פעמים שהוא לנגד הטבע כו' וגם בהפלגת התשוקה לתורה ותפלה במס\"נ אם הסכם הטבעי מצורף בזה לא נתברר עדיין כל סיג ופסולת דנה\"ב ששרשה בנוגה ולא נק' עובד אלקי' להסיר ההסתר כו' כי אין זה רק מצד בחי' גילוי אלקות שבנפשו האלקי' כ\"א גם מצד הסכם נפשו הבהמיות שהוא בחי' הישות והפירוד שמעורב ג\"כ בזה ע\"כ לא נק' עובד ולשם אלקי' דוקא אלא השונה ק\"א פעמים יותר מכפי טבעו הגשמי שבזה מתקן לשם אלקים דוקא מטעם הנ\"ל וד\"ל. ובכ\"ז יובן ג\"כ עובדא הנ\"ל בריב\"ק ורחב\"ת דהנה רחב\"ת הגם שמסר נפשו על התורה הי' מפקפק ומסתפק מאד פן יש במס\"נ זאת האלקי' תערובות הסכם הטבעי דנה\"ב שאינו נק' עובד אלקים עדיין כנ\"ל וע\"כ שאל מהו לעוה\"ב שלא יזכה בו רק העובד אלקי' דוקא שבירר בירורי' דנוגה כמא' מאן<sup data-n=\"185\">74</sup> דלא מהפך חשוכא כו' לית לי' חולקא בההוא עלמא משום דעוה\"ב לאחר הבירור הוא דוקא כו' וכמ\"ש במ\"א, והשיבו כלום מעשה בא לידך בהיפוך הטבע לגמרי וא\"ל ממעות של פורים כו' להיות שטבע השקידה וההתמדה בתשוקה על דברי חכ' שרשה באה ממרה השחורה שהיא גורמת עוצם בחי' הכיווץ בעצמו והיא הגורמת מדת הקמצנות בממון כנראה בחוש בטבעי בנ\"א אך מדת הפזרנות שהוא בחי' ההתפשטו' היפך הכיווץ שרשה ממרה הלבינה והוא היפך טבע השקידה וההתמדה לצמצם ולכווץ א\"ע כו' וכאשר א\"ל ממעשה פיזור הצדקה הבין בטבעו הגשמי שהוא פזרן שהוא מנגד גדול לטבע השקידה וההתמדה ואז א\"ל א\"כ מחלקך יהא חלקי כו' דהיינו מפני שראה שאין תערובו' הסכם טבעי כלל במס\"נ שלו על התורה ונק' עובד אלקים כנ\"ל וראוי הוא לעוה\"ב מצד הבירור דשם אלקים וע\"כ אמר הלואי יהא חלקי מחלקך כו', ובכ\"ז מתורצים כל הדקדוקים הנ\"ל וגם מה ששאלו מה אני לעוה\"ב אחר שהזהירו על נפשו שלא ישרפו אותו וא\"ל מן השמים ירחמו כו' וד\"ל. ועם כל הנ\"ל יובן גם בהתפעלו' אוי\"ר שבתפלה דהגם שנולדה מהתבוננו' באור א\"ס והרי בודאי מאיר בחו\"ב שבנפש האלקי' מבחי' אור שם הוי'",[["182","71","<b>כי אתה תאיר נרי</b>: תהלים יח, כט."],["183","72","<b>נר ה' נשמת אדם</b>: משלי כ, כז."],["184","73","<b>כי פי' עבודה הוא כמו עורות עבודין</b>: שבת מט, ב ובכ\"מ. וראה תו\"א ה, ב. עו, א. לקו\"ת ראה כב, ב. שה\"ש לה, ד. ובכ\"מ."],["185","74","<b>מאן דלא מהפך</b>: ראה זח\"א ד, א."]]],[2101000051,"דאצי' כנ\"ל מ\"מ תולדות המדות אוי\"ר שנולד מן ההתבוננו' יוכל להיות בהן תערובות זר מטבע נפשו הבהמיו' שמסתיר על אור ה' כנ\"ל אם לא שנתהפך הטבע ג\"כ בבחי' ביטול היש כנ\"ל והיינו כאשר איננו מרגיש ההתפעלו' לבחי' יש ודבר כו' כידוע ואם לאו יש יניקה לחיצונים כנ\"ל וכ\"ז כאשר המדות נולדי' מן השכל בלא אמצעו' הדעת אבל באמצעו' הדעת שממשיך בהן פנימי' הארת השכל וגם מצד עצמו שנעשה בחי' פנימי' למדות כנ\"ל הנה אז נבררו המדות מכל סיג ומכל בחי' יש וגסות אלא בבחי' ביטול היש בתכלי' ולא יש בהם תערובות זר כלל וכמ\"ש לב<sup data-n=\"186\">75</sup> טהור ברא לי כו' נקי<sup data-n=\"187\">76</sup> כפים ובר לבב כו' וכמארז\"ל לב<sup data-n=\"188\">77</sup> א' לאביו שבשמים וכנ\"ל שהוא ביטול כל רצון זר וכמ\"ש מי לי בשמי<sup data-n=\"189\">78</sup>ם כו' וד\"ל.\n<b>והנמשל</b> מכ\"ז יובן ג\"כ למשכיל למעלה בהיות ידוע שבחי' מדות דאצי' נמשכו מבחי' ג\"ר חב\"ד וכנ\"ל באופן ציור הא' בסדר הע\"ס דאצי' שהן זה למטה מזה ומן הדעת נמשכו הו\"ק כו' וע\"י הדעת דוקא נמשך הארה פנימיו' מחו\"ב דאצי' במדות דאצי' עד שלא יהי' שום מקום שרש יניקה לחיצונים מאחוריי' כנ\"ל באריכו' אך לאחר הבדל המסך והפרגוד שבין אצי' לבריאה הוא שיש מקום להם לקבל וע\"כ באצי' דוקא אמרו דאיהו<sup data-n=\"190\">79</sup> וחיוהי וגרמוהי חד כו' וכנ\"ל באריכות וד\"ל.\n<b>והנה</b> כ\"ז בבחי' הדעת התחתון המתפשט במדות אוי\"ר כו' והאהבה שנולדה מן ההתבוננו' ע\"י הדעת נק' אהבת עולם כמ\"ש אהבת עולם אהבת<sup data-n=\"191\">80</sup>יך ובזוהר נק' אהבה זוטא כידוע ומתוך זה הדעת התחתון נוכל להבין ג\"כ בבחי' הדעת העליון שמחבר לחו\"ב כנ\"ל כי הנה מבואר למעלה שיש ב' מיני מדות א' למטה מן השכל והב' למעלה מן השכל דהיינו בחי' מדות דא\"א וע\"י כמא' ז\"א בע\"י אחיד ותלי' וכנ\"ל באורך ובחי' האהבה שבכתר נק' אהבה רבה (והוא שם ב\"ן שלפני האצי' שנק' בהמה רבה כמ\"ש בלק\"ת) אך שהן עוברין ומתגלין בחו\"ב דאצי' בדרך מעבר והוא ע\"י בחי' דעת העליון שלמעלה מהן כו' וכנ\"ל שזהו ציור אופן הב' בג' קוין חח\"נ מימין כו' ואופן המשכתן למטה הוא ע\"י דעת עליון כמו בדעת התחתון שמתפשט במדות שלמטה מן השכל רק שלמעלה הוא המשכת הכתר במדות ונק' מדות שבכתר ולמטה הן מדות שלמטה מחו\"ב וע\"י דעת התחתון נמשך בהן הארת חו\"ב כנ\"ל וכמו שמבואר בדעת תחתון שהוא בחי' פנימי' המדות שלמטה כך בחי' דעת העליון הוא בחי' פנימי' המדות שלמעלה (וגם הוא פנימית חו\"ב להיותו עומד תחת הכתר וע\"י נעשה יחוד חו\"ב בבחי' הפנימי' כמו שאין יחוד תחתון דזו\"נ בלא דעת המתפשט כו' וכמ\"ש והאדם<sup data-n=\"192\">81</sup> ידע",[["186","75","<b>לב טהור ברא לי</b>: תהלים נא, יב."],["187","76","<b>נקי כפים ובר לבב</b>: תהלים כד, ד."],["188","77","<b>לב א' לאביו שבשמים</b>: ראה ברכות נז, א. תנחומא במדבר, טו. תבא, א."],["189","78","<b>מי לי בשמים</b>: תהלים עג, כה."],["190","79","<b>דאיהו וחיוהי וגרמוהי חד</b>: ראה ת\"ז בהקדמה לפני ד\"ה קום יחזקאל."],["191","80","<b>אהבת עולם אהבתיך</b>: ירמי' לא, ב. ובכל הבא להלן ראה בארוכה ספר הערכים — חב\"ד כרך א' ע' תקסג ואילך."],["192","81","<b>והאדם ידע</b>: בראשית ד, א. וראה תניא פ\"ג ובליקוט פירושים ומ\"מ שם."]]],[2101000052,"כו' וד<sup data-n=\"193\">82</sup>\"ל) וכמו שדעת התחתון הוא פנימי' ז\"א כך דעת עליון פנימי' או\"א עד שאין חיצוני' חו\"ב מסתירים כלל כו' וד\"ל), והנה בחי' אה\"ר הנ\"ל שנמשכה ע\"י דעת עליון ישנה גם בכל ניצוץ האלקי שבכאו\"א מישראל כמ\"ש דוד ואני<sup data-n=\"194\">83</sup> בהמות הייתי עמך כו' א' בהמה בגי' ב\"ן שהוא אהבה זוטא שלמטה מן השכל והב' בהמה רבה שלמעלה מן ההתבוננו' הנק' אהבת בכל מאדך בלי גבול בכלי כו' ונק' ג\"כ עומקא דלבא או רעותא דלבא שהיא בהעלם ברצון הנעלם רק שיציאתה לידי גילוי בלב עוברת ע\"י ההתבוננו' כנ\"ל דהמדות שבכתר עוברין דרך מעבר עכ\"פ דרך השכל כו' אבל לאחר שיצא דרך השכל הנה מצד עצמה וטבעה היא למעלה מן ההתבוננו' אלא יוצאת ע\"י דעת העליון הנ\"ל וד\"ל (והיינו מפני שהמל' עומדת נגד קו אמצעי דת\"י ולכך יש בה דעת עליון שממשיך אה\"ר וד\"ת שממשיך אהבה זוטא וז\"ש דוד דוקא ואני בהמות כו' וכן בכללות נש\"י ששרשם במל' כידוע יש ב' מיני דעת הנ\"ל וב' מיני אהבות הנ\"ל וד\"ל).\n<b>ובכ\"ז</b> יובן שרש בחי' רבקה<sup data-n=\"195\">84</sup> שהוא בחי' קשר וחיבור של שלש וארבע בקר כו' (וגם מקום מעמד הבקר נק' רבקה כידוע במשנה) דהיינו בחי' אה\"ר שהוא ב\"ן הנק' בהמה רבה כנ\"ל ובחי' הקשר וחיבור משלש וארבע בקר היינו להיות שבחי' התפעלו' המדות שלמעלה מן הטעם והשכל אין בהם בחי' התחלקו' כלל וכלל להיותם כלולים בבחי' העלם עצמי' הרצון הנעלם בעצמו' כו' משא\"כ בחי' המדות שנולדי' מן השכל הן באין דוקא בבחי' התחלקו' נפרדת זו מזו כי אותו השכל שמוליד אהבה לא יוליד יראה ואותו השכל שמוליד יראה לא יוליד אהבה אבל למעלה מן השכל והטעם הרי ממקור אחד יצאו אוי\"ר שברצון הנעלם אחר שאין להם שכליי' וטעמים מחולקי' והיינו להיותם כלולים שם בתכלית היחוד כו' וזהו ההפרש בין בחי' עולם העקודים לעולם הנקודי' שעולם העקודי' הע\"ס דשם כלולים כ\"א זב\"ז ועקודי' כולם בכלי א' והגם שמדות חו\"ג שני הפכים המה מ\"מ מתאחדי' ושורין בכלי א' אבל בחי' הנקודי' הן י' נקודות מחולקי' בי' כלים כידוע והענין הוא משום דבחי' העקודי' הוא בבחי' הכתר דע\"ס דשם כלולים יחד ויכולים לשכון בכלי א' גם ב' הפכים חו\"ג כנ\"ל אבל בחי' הנקודי' הוא מחכ' ולמטה שהן מתחלקי' בכלים רבים וע\"כ בחי' המדות שנולדי' מן השכל באין בבחי' ההתחלקות אבל בחי' המדות שבכתר המה מתאחדי' וקשורי' יחד והיינו כמו רבקה של שלש או ארבע בקר שקשורי' ומתאחדי' בכלי א' לכולם יחד כו' להיותו בבחי' עקודי' שעקודי' בכלי א' כו' וד\"ל (ויובן זה ע\"ד שאמר יה\"ר מלפניך שיכבשו רחמיך<sup data-n=\"196\">85</sup> את כעסך כו' לפי שברצון יש ב' מדריגו' הא' רצון הפשוט שנק' כשב\"כ שאין טעם לרצון זה גם לא בחי' טעם כמוס הנק' ח\"ס שבא\"א כו' ובחי' דעת עליון דא\"א מגיע לבחי' כשב\"כ שלמעלה מחו\"ב שבכתר להיותו בריח התיכון שמבריח אל הקצה היותר עליון שלא יוכל להתגלות בשני הקוין חח\"נ כו' ובחי' המשכת רצון זה",[["193","82","<b>וד\"ל)</b>: בכת\"י ב וכת\"י ג אין כאן מוסגר."],["194","83","<b>ואני בהמות הייתי עמך</b>: ראה תהלים עג, כב."],["195","84","<b>רבקה. . קשר וחיבור של שלש וארבע בקר</b>: עירובין יז, ב."],["196","85","<b>יה\"ר מלפניך שיכבשו רחמיך</b>: ברכות ז, א."]]],[2101000053,"הפשוט למטה הוא דוקא ע\"י בחי' דעת עליון הנ\"ל וזהו שאו' יה\"ר מלפניך דוקא ואז יכבשו רחמיך כו' כי שרש בחי' האה\"ר זאת שברצון הפשוט הנמשך ע\"י ד\"ע למטה בהתגלות לג'<sup data-n=\"197\">86</sup> הקוין כו' ביכולתו לכבוש את היפוכו שהוא מדה\"ד שבקו השמאל בג\"ה כו' וז\"ש יה\"ר שיכבשו רחמיך כו' והוא הנק' בחי' רבקה שמקשרת ועוקדת לכל ההפכים אם משלש או מארבע יחד דהיינו אם מג' מדריגות חב\"ד או חג\"ת או גם מד' מדריגות דהיינו כאשר נחלק הדעת לחו\"ג או דעת שמתפשט בחו\"ג שיש ד' מדריגות דעת חג\"ת כידוע (או בחי' נהי\"מ או תנהי\"מ וגם כוללת ד' מדריגות דכחב\"ד כו' וד\"ל) (והוא כמו בחי' חפץ חסד שבעצמו' המאציל שבעבורו רצה להאציל שנמצא בחי' התעוררו'<sup data-n=\"198\">87</sup> מרצה\"פ מחמת חפץ חסד זה כו' וע\"כ שם עקודי' בכלי א' כל מה שיתחלק אח\"כ ברצון כו' וד\"ל).\n<b>ובכ\"ז</b> יובן מ\"ש ברבקה ותרד<sup data-n=\"199\">88</sup> העיינה ותמלא כדה ותעל. דהנה החכ' נק' מעיין כי כמו מעיין הנובע בהעלם מתחת התהום ואח\"כ בא לידי גילוי בנהרות הנמשכין<sup data-n=\"200\">89</sup> כך שרש בחי' החכ' דהיינו נביעתה ממקור חוצבה הוא בבחי' ההעלם והיינו בבחי' ההעלם דכתר עליון וכמ\"ש והחכ'<sup data-n=\"201\">90</sup> מאין תמצא עיקר מקור חוצבה ופי' מאין מאין דכתר דהיינו מבחי' ח\"ס דא\"א (וגם בחי' ח\"ס דא\"א נק' חכ' ותמצא מבחי' אין שלמעלה ממנו דהיינו מהעלם עצמות חכ' הקדומה שבעצמו' אא\"ס כו') והנה בחי' רבקה הנ\"ל להיותו בחי' אה\"ר שלמעלה מן החכ' והטעם עד רום המעלות כנ\"ל ע\"כ נאמר בה ותרד העיינה לשון ירידה והשפלה משום דלגבי בחי' רבקה הנ\"ל ירידה גדולה היא להתלבש בחכ' שנק' עין או מעיין מטעם הנ\"ל (וגם אל בחי' ח\"ס ירידה היא מאחר שנאמר בה והחכ' מאין כו' ושרש בחי' רבקה הוא בבחי' העלם העצמו' ממש כנ\"ל בפי' יה\"ר מלפניך כו' וד\"ל). אך אם בחי' ירידה היא לאיזה טעם תרד ותשפיל א\"ע אבל הענין הוא דבחי' ירידה זאת לצורך עלי' היא וז\"ש ותמלא כדה ותעל פי' ותעל שהייתה לה בחי' עלי' גדולה בסיבת הירידה שירדה אל העין דחכ' כו' והענין הוא כידוע דאוריי'<sup data-n=\"202\">91</sup> מח\"ע נפקת ופי' נפקת שיצאה מח\"ע אבל שרשה למעלה מח\"ע והענין הוא כי עיקר חכמת התורה היא לבאר מעשה המצות בהכשירן ובפיסולן באופן כך וכך יוכשר לסוכה וא\"ל פסולה וכן בציצית ותפילין וכל המצות וכן במצות ל\"ת כו' וכ\"ז הבירור הרי הוא בבחי' חכ' וטעם כמוס לרצה\"ע שבמצוה לומר שזה הטעם הכמוס ירצה ה' ומזה הטעם לא יהי' לרצון כלל ואינו מצוה כו' א\"כ בהכרח שיש מקום ושרש בתורה למעלה גם מן הטעם הכמוס דהיינו בעצם הרצה\"פ שנק' כשב\"כ ששם עיקר שרש תרי\"ג<sup data-n=\"203\">92</sup> מצות דאוריי' וז' דרבנן גי' תר\"ך שהן תר\"ך עמודי אור כידוע אך שיורדי' ומתלבשי' בח\"ס שנק' טעם כמוס",[["197","86","<b>לג'</b>: בכת\"י ב: בב'."],["198","87","<b>התעוררו' מרצה\"פ</b>: בכת\"י ב וכת\"י ג: התעוררות הרצון."],["199","88","<b>ותרד העיינה ותמלא כדה ותעל</b>: בראשית כד, טז."],["200","89","<b>הנמשכין</b>: בכת\"י ב: המושכין."],["201","90","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["202","91","<b>דאוריי' מח\"ע נפקת</b>: זח\"ב פה, א. קכא, א."],["203","92","<b>תרי\"ג מצות דאורייתא וז' דרבנן גי' תר\"ך</b>: ראה אגה\"ק סכ\"ט. פרדס ש\"ח פ\"ג. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 165."]]],[2101000054,"אבל עליו נאמר והחכ' מאין תמצא מאין האמיתי שבעצמו' כו' וז\"ש אוריי' מח\"ע נפקת אבל שרשה מאין העצמי כו' וזהו ותרד העיינה בחי' רצה\"פ שבמצות ירד ונתלבש בח\"ע שנק' עיינה ותמלא כדה פי'<sup data-n=\"204\">93</sup> כד\"ה כ\"ד ספרי' דאוריי' והרי זה עד\"מ מי ששואב בכד קטן בים הגדול כך כ\"ד ספרי' דאוריי' אינו אלא ערך כ\"ד קטן לגבי הים הגדול דח\"ע כמא' חכים<sup data-n=\"205\">94</sup> ולא בחכ' ידיע' וכמ\"ש לתבונתו<sup data-n=\"206\">95</sup> אין חקר (ועד\"מ המשכות כמה מיני חכמות חכמות פלוסופי' וחכמת הרפואה וחכמת התכונה וכיוצא שנמשכו כולם ממקור א' דלגבי אותו המקור כלא חשיבי כו' כך כל כ\"ד ספרים מיני חכמות עליונות כלא חשיבי לגבי מקור כולם הנק' ח\"ס כו' וד\"ל) ועד\"מ השואב בכד מן המעיין ששואב הוא את המובחר והזך והנקי הנק' מים צלולים כך מ\"ש ותמלא כדה כ\"ד ספרי' ממעיין ח\"ס דא\"א הוא בחי' המובחר שבו והוא מים דאוריי' שהוא בחי' פנימי' החכ' בכל עולם עד למטה (כידוע דחכמות חיצוניו' כפלסופי' ותכונה כו' נפלו בשבה\"כ מבחי' אחוריי' דאו\"א כו') והיינו בחי' הארת הכתר אשר בחכ' עד רום המעלות וכמ\"ש והחכ' מאין כו' דהיינו בחי' אין דכתר המלובש בחכ', והנה בחי' ירידה זאת דרבקה שהוא חסד עצמי של המאציל אשר ברצונו הפשוט כנ\"ל לבחי' מעיין דח\"ס למלאות כ\"ד ספרים דאוריי' לברר כל דין ומצוה עפ\"י החכמה כנ\"ל הי' רק בשביל עלי' דהיינו בשביל העלי' שתתעלה כנ\"י אחר הבירורי' דרפ\"ח שבהן נעשו מעשה המצות שנק' רצונו של מקום בחי' רצה\"פ הנ\"ל שלמעלה לגמרי מבחי' חכ' גם מבחי' טעם כמוס וכמ\"ש כי<sup data-n=\"207\">96</sup> תהיו אתם ארץ חפץ כו' כי סוף מעשה זאת דהיינו גילוי רצה\"ע הפשוט שיהי' במעשה המצות למטה עלה במח\"ת ברצה\"פ ולזאת ירדה בחי' רבקה הנ\"ל העיינה ותמלא כדה כ\"ד ספרי' דאוריי' דהיינו שיהי' הכשר כל מצוה עפ\"י החכ' אבל הכונה העיקר<sup data-n=\"208\">97</sup>ית הוא העלי' שאחר הירידה דהיינו כדי שיגיע לעצמו' הרצון הפשוט כמו שהוא למעלה ממש וה\"ז עד\"מ הבונה בנין מפואר מצד עצמות רצונו שבהכרח להשפיל א\"ע בהתבוננו' שכל איך לבנותו בחכ' אבל אחר תשלום הבנין הרי עיקר אינו אלא מה שגמר ועשה את אשר כבר עלה ברצונו תחלה כו' וכך הרי נתאוה<sup data-n=\"209\">98</sup> הקב\"ה שהוא עצמו' המאציל להיות לעצמות רצונו בחי' דירה והשראה בתחתוני' ע\"י מעשה המצות וכאשר נגמר זאת המעשה שעלה במח\"ת ה\"ז גילוי בחי' העונג והחפץ שנתאוה ברצונו הפשוט תחלה וד\"ל<sup data-n=\"210\">99</sup> (היינו בחי' רבקה הנ\"ל שירדה ועלתה כו' וד\"ל) ועלי' לרבקה היינו מה שאותו העונג וחפץ חסד שנתאוה אחר תשלום המעשה עולה הוא בבחי' עצמות ממש כי הרי מה שנתאוה כו' הוא רק בחי' עונג פרטי מן העצמות כידוע וד\"ל).\n<b>ואחר</b> כל הנ\"ל יובן שרש הפסוק דאם יתן איש את כל הון ביתו באהבה בוז יבוזו לו כו'. ותחלה יש לבאר הפסוק דלעיל מיני' מים רבים לא יוכלו לכבות את",[["204","93","<b>פי' כד\"ה כ\"ד ספרים דאורייתא</b>: ראה ת\"ז תכ\"א (מו ב). אוה\"ת בראשית מח, א."],["205","94","<b>חכים ולא בחכ' ידיעא</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."],["206","95","<b>לתבונתו אין חקר</b>: ראה ישעי' מ, כח."],["207","96","<b>כי תהיו אתם ארץ חפץ</b>: מלאכי ג, יב."],["208","97","<b>עיקר</b>: בכת\"י ב וכת\"י ג: עיקר התענוג."],["209","98","<b>נתאוה הקב\"ה</b>: ראה תנחומא נשא טז. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו."],["210","99","<b>וד\"ל)</b>: בכת\"י ב וכת\"י ג' אין כאן מוסגר."]]],[2101000055,"האהבה כו' מהו מים רבים ומהו האהבה שלא יכבוה מים רבים ואיזה שייכו' יש לפסוק זה עם שלאחריו אם יתן איש את כל הון ביתו באהבה כו'. דהנה מבואר למעלה שיש ב' מיני אהבה הא' אהבה זוטא שלמטה מן השכל ונק' אהבת עולם והב' אה\"ר שלמעלה מן השכל דהיינו בעצמו' הרצון כו' שהוא בבחי' הכתר שנק' יחידה (שאין שם בחי' כלים כמו לנר\"נ ולכך זהו הנק' בכל מאדך בלי הגבלה בכלי כנ\"ל) ופי' מים רבים הוא בחי' חכ' עילאה מקור כל מיני חכ' שלמטה (וכנ\"ל בפי' ותמלא כדה כמו כ\"ד מים הגדול כו' והיינו בחי' ח\"ס או חכ' הקדומה כו') וז\"ש דגם בחי' מים רבים דח\"ע לא יוכלו לכבות בחי' אה\"ר הנ\"ל כי כל בחי' כיבוי הוא כמו הצימאון שהוא מיסוד האש ובשתותו המים יכבה הצמאון הזה כי כמו שהמים מכבים האש כך המים מכבים לצמאון כי הרי נתרווה צמאונו במים וכך הענין למעלה שבחי' מים רבים דח\"ע המה מרוים צמאון באהבה ותשוקה הנק' אהבה זוטא שלמטה מן השכל כי להיותה למטה מן השכל כנ\"ל ע\"כ ביכולת מים דחכ' שלמעלה הימנה לכבותה ולרוות צמאונה כו' ודוקא לבחי' אה\"ז אבל לבחי' אה\"ר שבבחי' יחידה ולמעלה הוא בחי' הכתר אין ביכולת גם במים רבים דח\"ע לכבותה ולרות צמאונה דמ\"ש הוי<sup data-n=\"211\">100</sup> כל צמא לכו למים היינו רק בצמאון שנלקח מן השכל ע\"י הדעת המתפשט כנ\"ל אבל לבחי' אה\"ר ששרשה למעלה מן השכל לגמרי והרי היא למעלה גם מבחי' מים רבים (שהוא בחי' ח\"ע הנק' ח\"ס כי אין טעם כלל לאה\"ר שברצון העצמי אפי' טעם כמוס כדלעיל) לא יש בכח המים רבים לכבותה (וכנראה בחוש שגם אם כח שכלו הוא חזק מאד בכחו לא יוכל לכבות עצם התענוג הפשוט הנק' אהבה בתענוגי' וכאשר אין האהבה מגעת בשרש התענוג העצמי יוכל בחי' תוקף כח המשכיל להעלימה ולכבותה לגמרי כו') מפני שבחי' האה\"ר גובר על כל מים רבים דח\"ע מטעם שהוא למעלה הרבה מהם וד\"ל וזהו שסמך לפסוק זה פסוק דאם יתן איש את כל הון ביתו באהבה כו' דהיינו לומר שאם יתן איש את כל הון ביתו בחילוף האה\"ר הנ\"ל אז ודאי בוז יבוזו לבחי' אה\"ר ג\"כ וה\"ק הגם שבחי' מים רבים לא יוכלו לכבותה אבל אם יתן איש את כל הון ביתו ודאי יכבו לאה\"ר ויבוזו כו' וזהו שפי' אם יתן כו' הוא לשון עתיד דוקא כאשר עתיד ליתן כל הון ביתו וכמו אם כסף תלוה כנ\"ל משום דמדבר על העתיד דוקא כאשר יתן איש זה הקב\"ה שהוא עצמו' המאציל את כל הון ביתו כולל ג' מדריגות חב\"ד כי בחכ' יבנה גוף ועצם הבית ובתבונה יתכונן הבית כנ\"ל ובדעת חדרי הבית ימלאון מכל הון יקר ונעים כנ\"ל וזהו אם יתן איש את כל הון ביתו שנתמלא ע\"י הדעת בכל חדרי ביתו כו'.\n<b>וביאור</b> כ\"ז הנה ידוע דהחכ' נק' בונה בית כנ\"ל הטעם משום דצירופי אותיות דתשב\"כ נמדדו עפ\"י החכ' וכמ\"ש ורב<sup data-n=\"212\">101</sup> שלום בנייך כו' ואוריי' מח\"ע נפקת היינו שיצאה מח\"ע אבל בה גנוז מבחי' אור הכתר שלמעלה מן הח\"ע שהן תר\"ך עמודי אור שבתר\"ך מצות כנ\"ל והן הנק' בשם הון ביתו למעלה דהיינו כל בחי' אורות עליוני' הסתומים שבכתר שהמה מתלבשי' למטה בחכ' שבתורה שנק'",[["211","100","<b>הוי כל צמא לכו למים</b>: ישעי' נה, א."],["212","101","<b>ורב שלום בנייך</b>: ישעי' נד, יג. וראה ברכות סד, א. שבת קיד, א."]]],[2101000056,"בית בכלל, אך עדיין לא נגלה שום אור מאורות הללו בחכ' שבתורה רק הן סתומי' ונעלמי' עד\"מ שסתום ונעלם אוצר הטמון בחדרי הבית ונק' מטמון כי הנה מבואר למעלה דאותי' תשב\"כ למעלה נקראו בתים והחכ' גנוזה בצירופי' הללו ובהן גנוז כל אורו' הסתומים ונעלמים בפרט בנגינות והטעמים כו' (וגם על<sup data-n=\"213\">102</sup> כל קוץ וקוץ הי' ר\"ע דורש כו') ולמטה באותיו' הכתובי' שבתורה הרי ג\"כ לא מובן ומושג מהם כלל ענין וטעם לאיזה מצוה וגם לא ידוע איך לעשות המצוה אלא סתום ונעלם בתורה כל פרטי הרצון שברצה\"ע הנק' כתר אך בתושבע\"פ בהלכות ודינין המבוארין שמה בטעמיהם שמה באין בבחי' גילוי והיינו בתבונה יתכונן שהוא תשבע\"פ שהיא בבחי' בינה כידוע שתשב\"כ בבחי' חכ' ונק' ספר ובחי' תושבע\"פ<sup data-n=\"214\">103</sup> נק' סיפור להיותה בבחי' בינה ותבונה כו' והוא בחי' יסוד וקיום לתשב\"כ כו' וד\"ל, אבל בדעת חדרים ימלאון כל הון יקר ונעים פי' בדעת הוא בחי' דעת עליון הנ\"ל שלמעלה מחו\"ב שהן תשב\"כ ותשבע\"פ והוא המחבר לחו\"ב דאצי' כי שרשו בפנימי' הכתר דוקא וע\"כ בדעת זה דוקא כל חדרים של בית זה דחכ' ימלאון מכל הון יקר ונעים פי' מכל הון ביתו הנ\"ל שהוא כל בחי' אורות עליונים הסתומי' ונעלמי' בכתר, ודרך כלל הן שית סדרי משנה שנק' ששה מדות שבחכ' ובפרט הן ס' מסכתות, ויותר בפרט הן כל פרטי הדיני' וההלכות דתושבע\"פ שבכאו\"א הרי יש גילוי רצה\"ע ממש איך להביאו לידי גילוי במעשה או בדיבור כו' והוא עצם רצה\"ע שהוא גנוז בחדרי הבית שהוא תשב\"כ ושבע\"פ ודוקא ע\"י בחי' ד\"ע מתגלה להיותו מביא וממשיך לרצה\"פ לידי גילוי למטה בחו\"ב דאצי' כנ\"ל וזהו ובדעת חדרי' ימלאון כל הון יקר ונעי' פי' יקר הוא בחי' אור הכתר שנק' יקר ונק' נעים מב' טעמי' הא' מענין יוקר שהוא הפלגת דבר הטוב והוא הפלאת העונג שנק' נעים והב' מענין הפלגת כבוד שנק' יקר כמ\"ש למי<sup data-n=\"215\">104</sup> יחפוץ המלך לעשות יקר כו' והכל שרש וענין א' כי הכתר לשון עטרה כמו כתרו<sup data-n=\"216\">105</sup> כו' כידוע וד\"ל.\n<b>וזהו</b> אם יתן איש את כל הון ביתו באהבה כו' דהנה בחי' אה\"ר הנ\"ל הגם ששרשה בבחי' הכתר דהיינו בעצמו' הרצון הפשוט כנ\"ל מ\"מ כלא חשיבי לנגד המצות ששרשם למעלה מבחי' האה\"ר שברצה\"פ אלא בעצם הרצון עצמו הנק' רדכ\"ר (והוא בחי' כשב\"כ בכלל וכמ\"ש במ\"א בענין הציץ והי'<sup data-n=\"217\">106</sup> על מצחו תמיד לרצון כו' וד\"ל) ע\"כ אם יתן איש כל הון ביתו שהוא בחי' התגלות פנימי' הרצון הפשוט והתענוג הפשוט אשר במעשה המצות שגנוזים בחכ' שבתורה שנק' ביתו כנ\"ל אז ודאי בוז יבוזו לו פי' יבוזו עד\"מ אדם שבוזז וחוטף בשלל דברי' היקרי' והנפלאי' בעיניו ביותר, דהיינו דברים מחודשים בפלאות גדולות שלא ראה עין ולא ימצא גם אצל שרים גדולים כו' ולא יבוז לדברי' השכיחים ונמצאי' ואינם ביוקר",[["213","102","<b>על כל קוץ וקוץ הי' ר\"ע דורש</b>: מנחות כט, ב. ובכ\"מ."],["214","103","<b>תושבע\"פ שהיא בבחי' בינה. . נק' סיפור</b>: ראה זח\"ב רעו, ב. וראה ג\"כ תו\"א שמות נב ב. לקו\"ת דרושים לסוכות פ, ב. שם שה\"ש ז, א. מו, ג. ביאוה\"ז קיג, ג ואילך. תו\"ח שמות יז, א ואילך. ובכ\"מ."],["215","104","<b>למי יחפוץ המלך לעשות יקר</b>: אסתר ו, ו."],["216","105","<b>כתרו כו'</b>: שופטים כ, מג."],["217","106","<b>והי' על מצחו תמיד</b>: שמות כח, לח."]]],[2101000057,"מופלג כו' כך למעלה בחי' הון ביתו שהוא בחי' האוצרות העליוני' המכוסים ונעלמי' בפנימי' הכתר שנק' תר\"ך עמודי' כו' כאשר יתגלו למטה יבוז אותם הכל ולא ישאר מאומה מכל הון ביתו כו' ואז גם שירצה האיש ליתן להם האה\"ר בחילוף הון זה היוקר, בוז יבוזו בבזיון כי כלא חשיבי מטעם הנ\"ל אך מ\"ש באהבה משמעו דהאה\"ר הנ\"ל מתאחדת עם בחי' הון ביתו הנ\"ל כי גם היא הרי שרשה בבחי' כתר ונמשכה ג\"כ ע\"י בחי' ד\"ע הנ\"ל רק שהון ביתו הנ\"ל נמשך ע\"י דעת העליון כמ\"ש ובדעת חדרים כו' וממקום עליון יותר אבל יש להאה\"ר איזה ערך עמהם וגם היא נכללת בהון ביתו וז\"ש באהבה שיתן כל הון ביתו ויכלול בהם גם בחי' אה\"ר הנ\"ל, ועכ\"פ א\"א לומר שהון ביתו הנ\"ל מכבים להאה\"ר הנ\"ל כמו שמים רבים מכבים לבחי' אהבה זוטא הנ\"ל, כי אה\"ז היא למטה הרבה מן החכ' שנק' מים רבים ע\"כ תכבה שם לגמרי אבל אה\"ר אינה למטה כ\"כ מן הרצון העצמי והפנימי שבמצות בדינין והלכות הנגלות כנ\"ל כי הרי גם באה\"ר יש בחי' פנימי' הרצון אלא שהוא חלק פרטי כנ\"ל וד\"ל (שהרי נק' אהבה בתענוגים פי' חלק האהבה שיש בתענוג הפשוט אבל המצות שרשם בעצם התענוג שכולל כמה פרטי' יחד כו') (והיינו שאמר בוז יבוזו לו ולא אמר להא\"ר כי אינה נכבית לגמרי וד\"ל ותיבת לו קאי על הון ביתו ולא כפשוטו דקאי על הון ביתו אבל יבוזו לשון בזיון אלא הוא לשון ביזה והיינו מטעם כי תיבת אם יתן לשון עתיד הוא כמשי\"ת).\n<b>וזהו</b> אם יתן איש כו' אם זה לשון עתיד הוא כנ\"ל דהנה בחי' פנימי' התענוג והרצון הפשוט שבדינין והלכות כנ\"ל אינו מתגלה עתה אלא מלובשים המה בהעלם לבוש מעשה המצוה (שהרי מצוה בחילוף א\"ת ב\"ש המ\"ם יו\"ד והצדי\"ק ה' והוא אותיו' י\"ה דשם הוי' הגנוז במעשה המצות ולע\"ל כתיב ביום ההוא יהי' ב\"פ י\"ה דיחוד זו\"נ ו\"ה יהי' דומה ליחוד או\"א י\"ה כו' וכמ\"ש במ\"א וד\"ל) ולעתיד כתיב ולא<sup data-n=\"218\">107</sup> יכנף עוד מוריך כו' עין בעין נראה אתה<sup data-n=\"219\">108</sup> כו' וע\"כ לעתיד דוקא יתגלה בחי' העונג והרצה\"פ שבמצות שנק' הון ביתו וכדפרש\"י ע\"פ ישקני מנשיקות פיהו<sup data-n=\"220\">109</sup> שהוא בחי' פנימי' טעמי המצות שלא יתגלו אלא לעתיד דוקא ולכך אמר ישקני לשון עתיד וגם כאן אמר אם יתן איש שעתיד ליתן את כל הון ביתו הנ\"ל בבחי' הגילוי ואז בוז יבוזו לו (ואדסמיך לי' קאי מים רבים לא יוכלו לכבות כו' אבל אם יתן איש לעתיד כו' בוז יבוזו כו' וכנ\"ל וד\"ל).\n<b>ובכל</b> זה יובן מארז\"ל דחייב<sup data-n=\"221\">110</sup> אדם לברך מאה ברכות בכל יום ולכאורה למה מספר מאה דוקא אך הענין הוא דעיקר עונג הפנימי ברצונו הפשוט הוא שיתגלה פנימי' רצון שלו במעשה המצות ולהיות כי אור הכתר כלול מי\"ס וכל אחד ואחד כלול מי' ע\"כ הן מספר מאה כי ק' המשכות צריך אדם להמשיך מאור",[["218","107","<b>ולא יכנף עוד מוריך</b>: ישעי' ל, כ."],["219","108","<b>עיו בעין נראה אתה</b>: במדבר יד, יד. וראה ישעי' נב, ח."],["220","109","<b>וכדפירש\"י ע\"פ ישקני מנשיקות פיהו</b>: פירש\"י לשה\"ש א, ב."],["221","110","<b>דחייב אדם לברך מאה ברכות</b>: מנחות מג, ב."]]],[2101000058,"הכתר במל' ולזה רמזו רז\"ל א\"ת<sup data-n=\"222\">111</sup> מה אלא מאה שהוא בחי' הכתר שצריך להמשיך במל' וזהו כל עיקר כוונות ברכות המצות ברוך אתה ה' פי' ברוך ממקור הראשון שהוא עצמי' הרצון שיתגלה ויומשך למטה באו\"א שנק' ה' אלקינו יח\"ע וביחו\"ת דזו\"נ שנק' מלך העולם כידוע וכ\"ז ע\"י המצות וזהו אשר קדשנו במצותיו פי' מצותיו בחי' רצונו העצמי כמו שהוא למעלה בעצמותו ממש שיומשך למטה והיינו בחי' גילוי התענוג והרצה\"פ וזהו אשר לשון עונג ולשון להבא כמו אהי'<sup data-n=\"223\">112</sup> אשר כו' וזהו שלעתיד דוקא יתגלה ועכשיו מאיר במצות בהעלם כנ\"ל וד\"ל. וזהו<sup data-n=\"224\">113</sup> שאו' לפני כל מצוה לשם יחוד קוב\"ה ושכינתי' שהוא בחי' יחוד סוכ\"ע וממכ\"ע כי הנה בכללות כל ההשתלשלו' דקו\"ח כו' הרי בחי' העונג והרצה\"פ הנ\"ל הוא בחי' סובב הכללי להקיף את כל ההשתלשלו' מריש כל דרגין עד סוף העשי' ובחי' ממכ\"ע הוא בחי' המל' וזהו שאומר ה'<sup data-n=\"225\">114</sup> ימלוך לע\"ו ותיבת ועד<sup data-n=\"226\">115</sup> הוא בחילופי אתוון דאחד כמ\"ש בזהר דהיינו בחי' אחדות הפשוטה שבעצמו' המאציל יומשך במל' שנק' ועד והוא בחי' יחוד סוכ\"ע בממכ\"ע וזהו כללות הכונה במעשה המצות כנ\"ל ולכך או' לשם יחוד כו' וזהו ג\"כ ענין המאה ברכות שבכל יום כנ\"ל וד\"ל.\n<b>אך</b> הנה י\"ל בתוס' ביאור איך יהי' בחי' סוכ\"ע בבחי' הגילוי בממכ\"ע אחר שבחי' סובב הכללי הוא נבדל בערך לגמרי גם מהיות בחי' מקור להשתלשלות כידוע ובחי' ממכ\"ע הרי הוא במדריגות השתלשלות מעילה לעילה כידוע ואיך יוכל להיות חיבור ויחוד זה. אבל הנה יש להקדי' תחלה להבין היטב ההפרש בין בחי' סוכ\"ע לבחי' ממכ\"ע דהנה מבואר בכמה דוכתי שאין פי' סובב שהוא סובב ומקיף מלמעלה דוקא ולא נמצא למטה בגילוי כלל שהרי נאמר את<sup data-n=\"227\">116</sup> השמים ואת הארץ אני מלא וכמאמר הידוע דלית<sup data-n=\"228\">117</sup> אתר פנוי מיני' ופי' מיני' משמע מעצמותו כמ\"ש אני מלא ועיקר ההפרש בין בחי' סובב לבחי' ממלא אינו אלא שבבחי' סובב אין חילוק מדריגות מטה ומעלה כלל ונמצא הארתו בעליונים ותחתוני' בשוה ממש וכמ\"ש בע\"ח דאו\"מ הכללי שלפני הקו נוגע לכל העולמות בשוה כו' אבל בבחי' ממלא יש חילוק מדריגות מעילה לעילה עד העולם השפל הזה כמ\"ש במ\"א באריכות. אך הנה לכאורה יש להפליא מאד על היות בחי' סובב הכללי בהשואה א' למטה כמו למעלה ממש דאיך יתכן שיהי' השראת עצמו' אא\"ס שהוא אח\"פ בתכלי' גם בדברים השפלים ביותר כמו חומריות הארץ הלזו וכל אשר בה מחלקי דצ\"ח כו' וגם בהיותו מלא קליפות וסט\"א",[["222","111","<b>א\"ת מה אלא מאה</b>: מנחות שם (ראה רש\"י ותוס' שם). זח\"ג קעט, א. ובכ\"מ."],["223","112","<b>אהי' אשר</b>: שמות ג, יד."],["224","113","<b>וזהו שאו' לפני כל מצוה לשם יחוד</b>: ראה ג\"כ לקו\"ת דרושים לר\"ה נה, ג. הערת כ\"ק אדמו\"ר זי\"ע במפתחות והערות הנדפס בסו\"ס לקו\"ת ע' יח, ובסה\"מ תש\"ב ע' 27."],["225","114","<b>ה' ימלוך לע\"ו</b>: שמות טו, יח."],["226","115","<b>ועד הוא בחילופי אתוון דאחד כמ\"ש בזוהר</b>: זח\"ב קלד, א. וראה אוה\"ת וארא כרך ז' ע' ב'תקס ואילך. הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 242. תשובות וביאורים סי\"ג."],["227","116","<b>את השמים ואת הארץ אני מלא</b>: ירמי' כג, כד."],["228","117","<b>דלית אתר פנוי מיני'</b>: ת\"ז תנ\"ז (צא, ב). ת\"ע (קכב, ב)."]]],[2101000059,"שנק' צואה כמ\"ש על ע\"ז צא<sup data-n=\"229\">118</sup> תאמר לו כו'. אך הענין הוא דאין הארת בחי' סובב הנ\"ל באה בבחי' הגילוי ממש להיות בבחי' צורה וחומר שנק' או\"כ אבל בחי' ממכ\"ע שבא להוות מאין ליש ה\"ז בא בבחי' גילוי ממש וע\"כ מתחלק בכל עולם לפי ערכו דוקא משא\"כ בחי' סובב שורה בכולם בהשואה א' לפי שאינו שורה אלא בהעלם ואעפ\"כ יש הארתו במציאות ממש בכל עולם עד היותר תחתון מכולם והיינו עיקר ההפרש שבין בחי' סובב לבחי' ממלא שהוא ההפרש בין בחי' גילוי לבחי' העלם.\n<b>אך</b> י\"ל ביאור אופן מציאות כזה איך יוכל להיות שבחי' סובב יהי' שורה בהשראה ממש ואעפ\"כ אינו אלא בהעלם וגם י\"ל איך יתורץ הקושי' עדיין הנ\"ל דלא יתכן לומר שישרה בחי' סובב גם בהעלם בדצ\"ח אחר שנק' בשם השראה ממש. אבל הנה דבר זה יובן עד\"מ מבשרי אחזה כו' דהנה אנו רואים באדם למטה שכח המח' תתפשט גם באברי' גשמיי' כמו הכרס והקרביי' הגם שהמח' עצמה רוחניות היא ולא יש יחוס ערך לומר שישכון הרוחניות של המח' בגשמייו' הכרס והרי אנו רואים שכאשר יעלה במחשבה לכווץ את כריסו או לכווץ ידו ורגלו מיד בלי שיהוי יכווץ כי כח המח' ממש פועל שם ע\"י גידי המוח שמתפשטין בכל האברים או מאשר אנו רואים שיש התלבשות המח' והשכל באצבע גשמיו' הכותבת דברי חכ' וכן כשמרמז בידו דבר חכ' וכיוצא וכ\"ז מופת והוראה שיש התלבשות השכל והמח' באברי' גשמיי' וא\"א לומר שיהיו הכרס והיד והרגל כמו חומר לצורה לקבל חיות ממש מן המחשבה כשאר חיות האברים שהרי הכרס או היד ורגל חיותם מהדם מובדל בפ\"ע בהגשמה בלתי ערוך להם לחיות הרוחניות שבמח' כידוע אלא בהכרח צ\"ל דגם שיש למציאת פעולת המחשבה ממש בכרס יד ורגל אבל אינה מאירה שם בגילוי כפי מזג החומר של הכרס כמו שמאירה בכלי חומר המוח אלא משכנה שמה בהעלם וע\"כ א\"א לומר שיתטנף המח' הרוחניו' בטינוף הכרס בעודינה שם לפעול פעולתה לכווץ או לעצר כו' כמו שלא יתכן לומר שיטונף הארת השמש כאשר מאירה בבית הכסא ויותר מזה כי אור השמש גשמי גם הוא אלא שאיננו בגדר גשם גמור אבל הרוחניות מובדלת לגמרי מן הגשמיות כמו שא\"א לומר שימששו ביד לאור השכל הרוחני וכיוצא וד\"ל וא\"כ הרי מובן עכ\"פ שיוכל להיות בחי' התלבשות אור בהעלם שלא לפי ערך קבלת המקבל כלל ואעפ\"כ ישנו שם במציאות ממש ולזה יתכן ג\"כ שישכון בהשוואה א' מבלתי חילוקי מדריגות כלל וכמו המח' שמשכנה בכל האברים בשוה כו', וככל המשל הזה יובן למעלה בבחי' סוכ\"ע הכללי הנ\"ל דהיינו רק בחי' מח' א' הקדומה בעצמות<sup data-n=\"230\">119</sup> ונק' ידיעה כללית דהיינו מה שבידיעת עצמו הוא יודע את כל ההשכלות<sup data-n=\"231\">120</sup> הנה בידיעה זאת מקיף לכולם בשוה בסקירה א' כמ\"ש<sup data-n=\"232\">121</sup> בלק\"א וביאור הדברי' היינו כמשל הנ\"ל במחשבה שבמוח שמתפשטת בכל הגוף בשוה (חסר<sup data-n=\"233\">122</sup>).",[["229","118","<b>צא תאמר לו</b>: ישעי' ל, כב."],["230","119","<b>בעצמות</b>: בכת\"י ב: באצילות."],["231","120","<b>ההשכלות</b>: בשאר הכת\"י: ההשתלשלות."],["232","121","<b>כמ\"ש בלק\"א</b>: פמ\"ח."],["233","122","<b>חסר</b>: כן רשום בהכת\"י. ובכת\"י א' רשום: חסר בגוף כתיבת ידי קדשו של אדמו\"ר נבג\"מ."]]],[2101000060,"<h3>ביאור ד\"ה מים רבים</h3>\n<b></b><b>ביאור על התורה דמים רבים שהי' בעת החתונה תקס\"ט</b>\n<b>להבין</b><sup data-n=\"234\">1</sup> שרשי הדברים הנ\"ל ע\"פ אם<sup data-n=\"235\">2</sup> יתן איש את כל הון ביתו כו' הנה אם הוא לשון עתיד כמו אם<sup data-n=\"236\">3</sup> כסף תלוה, ואם<sup data-n=\"237\">4</sup> יהי' היובל כו', כמו\"כ בחי' הון ביתו אינו מתגלה עתה כ\"א לעתיד יתגלה כו'. הנה ענין הון ביתו כו' היינו כמו ענין האוצרות והמטמוני' שמונחים בתוך הבית והוא ע\"ד מ\"ש ובדעת<sup data-n=\"238\">5</sup> חדרים ימלאון כל יקר ונעים כו', דהנה כתי' בחכמה יבנה בית ובתבונה יתכונן ובדעת חדרים ימלאון כל הון יקר ונעים כו', פי' בחכמה הוא רק בנין עצם הבית בלבד שהן אותיות התורה שנק' בתים כידוע וכמשי\"ת, ובתבונה יתכונן פי' עיקר קיום והעמדת הרחב הבית בריבוי חדרים הוא ע\"י בחי' הבינה דוקא אבל בדעת חדרים ימלאון בהון יקר ונעים פי' ע\"ד דוגמת האוצרות שמונחים בתוך חדרי הבית כו'.\n<b>וכדי</b> להבין את זה היטיב צריך לבאר הקדמה אחת בענין סדר השתלשלות הי\"ס דאצי' זמ\"ז איך הוא סדרם ואופנם שמצינו בזה בדברי המקובלים בשני אופנים אשר לכאורה נראה כמחולקים דהנה בע\"ח מבואר בכמה מקומות וגם<sup data-n=\"239\">6</sup> בלק\"א שסדר ההשתלשלות הוא בדרך זה חב\"ד זה למעלה מזה דהיינו שבחי' בינה נמשך מבחי' חכמה ובחי' דעת נמשך מבחי' בינה ונק' ג' אלה בשם ג' ראשונות ומהם נמשכים כל המדות, שהם חו\"ג ונק' בלשון המקובלים ו\"ק או בשם ז\"ת, וכאשר מבואר סדר אופן זה ע\"י ציור גשמי שבחי' ג\"ר עומדים בקו א' מלמעלה למטה ואח\"כ כל הו\"ק ביחד למטה מהן כמבואר בלק\"א ע\"ד מבשרי אחזה כו' שהן עשר כחות הנפש שמתלבשים בגוף שנחלקים לב' בחי' שכל ומדות והשכל כולל ג\"ר שהן חב\"ד והמדות נחלקים לששה שהן אהבה ויראה וענפיהן שהן נמשכים מבחי' ג\"ר הנ\"ל, כי בחי' חכמה הוא בחי' הברקת נקודת השכל שנופל לו מלמעלה מהשכל ונק' בחי' חכמה כ\"ח מ\"ה לפי שעדיין אינו מושג בשום השגה ולכן נק' בחי' יו\"ד שהוא בחי' נקודה לבד והוא ראשית הגילוי של הנפש, אכן בחי' בינה הוא התפשטות נקודת השכל שמתפשטת אח\"כ לאורך ורוחב להבינה ולהשיגה היטיב על בורי' לכן נק' בחי' ה' שהוא התפשטות לאורך ורוחב, ומבחי' בינה נתעורר אח\"כ בחי' המדות שבלב אהוי\"ר כאשר נראה שכאשר יתבונן האדם בטובת איזה דבר אזי יוליד בלבו התפעלות האהבה לאותו דבר וכן להיפוך וכמו\"כ בגדולת ה' כאשר יתבונן האדם בגדולת ה' אזי יתפעל ויוליד בלבו בחי' אהבה וכן בחי' יראה שיהי' בחי' פחד ה'",[["234","1","<b>להבין שרשי הדברים הנ\"ל ע\"פ אם יתן</b>: נוסח אחר מהנדפס לעיל ע' יג ואילך. (שם חסר סיום, וכאן המאמר בשלימות). ונו\"א קצר יותר נדפס בתו\"א תולדות יט, א. וראה עוד להלן ברשימת המאמרים."],["235","2","<b>אם יתן איש</b>: שה\"ש ח, ז."],["236","3","<b>אם כסף תלוה</b>: משפטים כב, כד."],["237","4","<b>ואם יהי' היובל</b>: מסעי לו, ד: אם יהי' היובל לבנ\"י ונוספה נחלתן גו'. [כן הובא בתו\"א שם יח, ב. יט, א]. ובכת\"י ב כאן נרשם במקום זה: וכתי' אם קרבה שנת היובל. [וכ\"ה גם לעיל בס' זה ע' יג. ונראה כוונתו ג\"כ לפסוק זה בפ' מסעי בשינוי לשון]."],["238","5","<b>ובדעת חדרים ימלאון</b>: ע\"פ משלי כד, ג."],["239","6","<b>וגם בלק\"א</b>: תניא פ\"ג. ועוד."]]],[2101000061,"עליו וכן עד\"מ למעלה בעולם האצי' סדר השתלשלות י\"ס שמן המאציל בחי' ח\"ע דאצי' הוא בחי' ראשית הגילוי שמן המאציל לנאצלים וכמ\"ש והחכמה<sup data-n=\"240\">7</sup> מאין תמצא ונק' ראשית האצי' כו' והוא בחי' יו\"ד שבשם הוי' שעדיין אינו בבחי' גילוי ישות כלל כ\"א כ\"ח מ\"ה כו' וכן התלבשות אוא\"ס בבחי' חכמה דוקא ומבחי' חכמה נמשך לבחי' בינה דאצי' מאין ליש שהוא בחי' גילוי ההתפשטות לאורך ורוחב ונק' ה' בחי' בינה אם הבנים ומקור המולידם לפי שמבחי' בינה דוקא הולדת המדות העליונות שהן חו\"ג שנק' ששה קצוות.\n<b>וסדר</b> הב' של השתלשלות הע\"ס הוא מ\"ש<sup data-n=\"241\">8</sup> בפרדס באריכות וגם נז' בע\"ח שהן ע\"ד ג' קווין חח\"ן קו ימין בג\"ה קו שמאל כדתי\"מ קו אמצעי, ונמצא לפי סדר הזה בחי' חב\"ד אין נמשכין זה מזה וגם לא המדות כולן אין עיקר המשכתן מהג\"ר כפי הסדר הא' כ\"א בחי' חב\"ד עומדין בג' קוין כל א' ראש הקו שלו כו'.\n<b>והנה</b> ענין ההפרש שבין ב' הדעות בסדר ההשתלשלות הוא בב' אופנים, א' שלפי סדר הא' שחב\"ד הם זה למטה מזה ונמצא שהדעת עומד למטה מבחי' בינה ובין המדות חו\"ג, והיינו שהדעת ממשיך הארת חו\"ב לתוך המדות, משא\"כ לפי סדר הב' שהדעת הוא בחי' קו אמצעי נמצא שאינו עומד כלל למטה מבחי' בינה כ\"א תחת בחי' הכתר בין חו\"ב והיינו שממשיך הארת הכתר לבחי' חו\"ב וחו\"ג כמשי\"ת, והב' שלפי סדר הא' עיקר הולדת המדות הוא רק מבחי' חו\"ב ע\"י הדעת שממשיך בהם הארת חו\"ב, משא\"כ לפי סדר הב' אין עיקר הולדת המדות מבחי' חו\"ב כ\"א מבחי' הכתר וג\"כ ע\"י הדעת שממשיך בם הארת הכתר.\n<b>והענין</b> הוא דשניהם אמת. ויובן זה עפ\"י ענין הידוע שיש ב' בחי' דעת, הא' הוא הנק' דעת עליון שנמשך מבחי' הכתר שמחבר ומיחד לבחי' חו\"ב ע\"י הארת הכתר, והב' הוא הנק' דעת תחתון שמחבר לחו\"ג ונק' דעת המתפשט במדות להמשיך בם הארת חו\"ב כו', וגם ידוע דיש ב' בחי' מדות הא' בחי' המדות שעיקר מציאותן הוא רק מבחי' חו\"ב עד\"מ באדם למטה שהמדות הן באין ונמשכין רק מהשכל ולפי ערך השכל כך יהי' ערך המדות, והב' בחי' המדות שעיקר שרשן הוא מהמדות שלמעלה מהשכל רק שיוצאין ונמשכין דרך השכל וכמ\"ש<sup data-n=\"242\">9</sup> ברע\"מ דז\"א בעתיקא אחיד ותלי' שהן המדות דז\"א ששרשן ומקורן הוא מהמדות דא\"א ודעתיק אחידן<sup data-n=\"243\">10</sup> ותליין בהם כמבואר כ\"ז במ\"א.\n<b>ומעתה</b> יתפרשו הב' דעות הנ\"ל בענין סדר השתלשלות הע\"ס דאצי' על נכון שאינם מחולקים כלל כ\"א שניהם אמת רק שהפרדס מדבר בענין המדות",[["240","7","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["241","8","<b>מ\"ש בפרדס</b>: ש\"ו פ\"א ואילך."],["242","9","<b>וכמ\"ש ברע\"מ דז\"א בעתיקא אחיד ותליא</b>: ראה זח\"ג רצב, א."],["243","10","<b>אחידן ותליין בהם כמבואר כ\"ז במ\"א</b>: ראה ס' מאמרי אדה\"ז ענינים ע' תיז ואילך, ובהמ\"מ שם."]]],[2101000062,"שאין עיקר מציאות לידתן מבחי' חו\"ב כ\"א מבחי' הכתר שמאיר בהם וכמאמר הרע\"מ ז\"א בעתיקא אחיד ותלי' כו', והיינו ע\"י בחי' דעת עליון ששרשו מבחי' הכתר ומייחד ומחבר בחי' חו\"ב יחד להיות נמשך הארת הכתר בתוך המדות והיינו ע\"ד ציור הנ\"ל בג' קווין חח\"ן קו כו' שנמצא שהדעת עומד בין חו\"ב ותחת הכתר משא\"כ סדר הב' הנז' בע\"ח חב\"ד ו\"ק ובחי' חב\"ד זה למטה מזה, היינו שמדבר בבחי' המדות שהן באין ונמשכי' רק מן השכל והיינו ע\"י בחי' דעת תחתון שממשיך בם הארת חו\"ב ולכן נק' דעת המתפשט בתוך המדות.\n<b>ולהבין</b> את כל זאת בתוס' ביאור צ\"ל בתחלה בעיקר בחי' הדעת מה הוא, ומתחלה צריך לבאר בענין דעת תחתון שמתפשט בתוך המדות, ויובן כמ\"כ בבחי' דעת העליון המחבר לבחי' חו\"ב יחד דהנה כבר נתבאר למעלה בענין סדר השתלשלות הי\"ס דאצי' שהם חב\"ד זת\"ז ואח\"כ כל המדות שהן ו\"ק נמשכים מבחי' חו\"ב והן ע\"ד דוגמת המדות באדם למטה שהם נולדים ונמשכים רק מן השכל ולפי ערך התפשטות נקודת השכל באורך ורוחב הבינה כך יהי' ערך המדות וכמו\"כ עד\"מ למעלה כנ\"ל באריכות וא\"כ אינו מובן מהו בחי' הדעת הלא עיקר הולדת המדות הוא מחו\"ב לבד. אך הענין הוא דהדעת הוא בכ\"מ בחי' הפנימיות וכמו\"כ כאן בחי' הדעת המתפשט בתוך המדות הוא בחי' הפנימי' של המדות ותכלית הבירור שלו. והענין כי הדעת הוא בחי' התקשרות לבחי' הארת חו\"ב בתוך המדות ומבררן ומבדילן בתכלית שלא יהי' מעורבין טו\"ר להיות שהמדות הם יכולים להיות מעורבין מטו\"ר, וע\"כ שרש יניקת החיצוני' הוא מבחי' המדות וכידוע מאברהם<sup data-n=\"244\">11</sup> שיצא ממנו ישמעאל, וכמו\"כ בעבודת הוי' מבחי' אהבה והתפעלות רשפי אש ע\"י התבוננות בגדולת ה' שבשעת התפלה יכול לבוא אחר התפלה לידי כעס, ומוכרח להיות שגם בשעת התפילה הי' קצת תערובות זר בבחי' אהבה ורשפי אש, כי אם היתה אהבה הנ\"ל רק מבחי' אלקות לבד שהוא בחי' גילוי אור ה' בנפשו בשעת התפלה מאין הוא בא אח\"כ לכעס וכדומה שהוא בחי' יניקת החיצוני' כידוע שאין יניקת החיצוני' אלא מבחי' אחוריים דשם אלקים שהוא בחי' הסתר.\n<b>ולהבין</b> ענין זה בתוס' ביאור איך שיתפעל באהבה לה' ויהי' בזה תערובות זר, צריך להקדים ענין מאמר<sup data-n=\"245\">12</sup> חז\"ל על ר\"ח בן תרדיון ששאל את ר' יוסי בן קיסמא מה אני לעוה\"ב והשיבו כלום מעשה בא לידך והשיבו<sup data-n=\"246\">13</sup> שפעם א' החליף כו' והשיבו א\"כ יהא חלקי עם חלקך. ולכאורה יפלא זה מאד על ר\"ח ב\"ת שעסק בתורה לשמה כל ימיו והי' לו מס\"נ בתכלית כל ימיו כידוע ממארז\"ל וא\"כ איך הי' מסופק ע\"ע אם מוכן הוא לעוה\"ב, וביותר יש להפליא על התשובה כלום מעשה באה לידך",[["244","11","<b>מאברהם שיצא ממנו ישמעאל</b>: פסחים נו, א. וראה לעיל במ\"מ לע' כ."],["245","12","<b>מאמר חז\"ל על ר\"ח בן תרדיון</b>: ע\"ז יח, א."],["246","13","<b>והשיבו שפעם א' החליף כו'</b>: בגמ' שם: אמר לו ר\"ח מעות של פורים נתחלפו לי במעות של צדקה וחילקתים לעניים (וברש\"י: מעות של פורים, שהנחתים לסעודת פורים נתחלפו לי וחילקתים לעניים וסבור הייתי שארנקי של צדקה היא ולא נפרעתי מארנקי של צדקה) אמר לו אם כן מחלקך יהא חלקי ומגורלך יהא גורלי."]]],[2101000063,"כו', מזה מובן שגם שהי' לו מס\"נ בתכלית עכ\"ז אינו מוכח מזה שיהי' מוכן לעוה\"ב רק מזה שבא לידי מעשה הצדקה, ויובן זה עפ\"י<sup data-n=\"247\">14</sup> משארז\"ל ההפרש שבין עובד אלקים לאשר לא עבדו שמי ששונה פרקו מאה פעמים ואחד נק' עובד אלקים ואשר לא עבדו היינו מי ששונה ק' פעמים, והטעם כמ\"ש<sup data-n=\"248\">15</sup> בלק\"א לפי שהפעם הא' היותר על מאה שהוא רגיל בזה הוא היפוך הטבע ונק' עי\"ז עובד אלקים משא\"כ מי ששונה ק' פעמים בלבד שהוא הרגילות ונעשה כמו טבע אצלו אינו נק' עובד אלקים. ונמצא מובן מזה שאף שיעסוק האדם בתורה לשמה ודביקות לה' עכ\"ז יוכל להיות שגם הטבע שהוא מבחי' נפש הבהמית שלו מעורב ג\"כ בזה ולא נהפך לגמרי אשר לזאת מי ששונה פרקו ק' פעמים לבד הגם שלומד בדביקות לה' עכ\"ז לא נק' עובד אלקים כ\"א דוקא כששונה ק\"א פעמים היפך הטבע לגמרי אז נק' עובד אלקים, ופי' עובד אלקים הוא מלשון עורות עבודים שמעבדן ומתקנן לגמרי כמו\"כ עובד אלקים היינו שמתקן ומהפך את בחי' אלקים שלא יכסה ויסתיר על בחי' גילוי אור ה' שמאיר בנפש אלקית.\n<b>דהנה</b> כתי' כי<sup data-n=\"249\">16</sup> שמש ומגן הוי' אלקים שבחי' שם אלקים הוא המגן ונרתק להעלי' ולהסתיר את אור ה' הנמשך משם הוי' מאצי' לבי\"ע שלא יאיר ויתגלה בבחי' א\"ס כמו בעולם האצי' ששם איהו<sup data-n=\"250\">17</sup> וחיוהי וגרמוהי חד בבחי' א\"ס שאין הכלים שנק' גרמוהי מסתירים כלל כ\"א להתהוות יש מאין שהם מלאכים ונשמות דבריאה שהם בע\"ג עד שברוב הצמצומים והסתרות שמתהווה עולם העשי' הגשמי שהם נבראים נפרדים עד שיוכל להיות ג\"כ יניקת החיצוני' וס\"א כנ\"ל וכנודע שיניקת החיצונים הוא מבחי' אחוריים דשם אלקים וכמ\"ש באדמת בני חם שהם מ\"ח צירופי אלקים כי ק\"ך צירופי אלקים המתלבשים בבי\"ע ומבחי' ע\"ב צירופי הראשונים עדיין אין להם שום יניקה כידוע, וכידוע שבחי' מל' דאצי' נק' מסך ופרגוד המפסיק בין אצי' לבי\"ע שהוא בחי' שם<sup data-n=\"251\">18</sup> אלקים בגי' כסא כס א' כמ\"ש במ\"א ונמצא מובן מכל הנ\"ל שבחי' נפש הבהמית שבאדם הוא מבחי' שם אלקים המסתיר על נפש אלקי' שהוא אור הוי' המאיר בנפשו וכמ\"ש כי<sup data-n=\"252\">19</sup> חלק הוי' עמו כו', וזהו פי' עובד אלקים שמתקן ומהפך את שם אלקים שהוא הישות והפירוד שמבחי' נפש הבהמית להיות בבחי' ביטול היש בתכלית ע\"י בחי' גילוי אור הוי' שבנפש אלקית ואזי נק' עובד אלקים ולכן דוקא כששונה פרקו ק\"א פעמים שהוא היפוך הטבע והרגילות שמבחי' נפש הבהמית ואין בזה שום תערובות טבע שהוא מנפש הבהמית כלל כ\"א מצד גילוי אלקות שבנפשו בלבד ולכן נק' עובד אלקים, משא\"כ כששונה ק' פעמים לבד שכבר הורגל בזה הגם שלומד בדביקו' עכ\"ז יוכל להיות",[["247","14","<b>עפ\"י משארז\"ל ההפרש שבין עובד אלקים</b>: חגיגה ט, ב. מלאכי ג, יח."],["248","15","<b>כמ\"ש בלק\"א</b>: פט\"ו."],["249","16","<b>כי שמש ומגן הוי' אלקים</b>: תהלים פד, יב."],["250","17","<b>איהו וחיוהי וגרמוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["251","18","<b>שם אלקים בגי' כסא כס א' כמ\"ש במ\"א</b>: ראה ת\"ז בהקדמה ד, ב. יג, א. ראה תו\"א עז, א ואילך. פג, ב. צה, ג ואילך. לקו\"ת האזינו מד, ד. סידור עם דא\"ח רפב, ג ואילך. תו\"ח בראשית קל, ב. ועוד. וראה בהמ\"מ לעיל ע' ד."],["252","19","<b>כי חלק ה' עמו</b>: האזינו לב, ט."]]],[2101000064,"שגם הטבע מעורב בזה ונמצא שאינו מצד גילוי אלקות שבנפשו לבד כ\"א גם טבע נפש הבהמית שהוא הישות והפירוד שמבחי' שם אלקים שמעלים ומסתיר מעורב ג\"כ ולכן לא נק' עובד אלקים. וזהו ג\"כ מאמר רז\"ל על ר\"ח ב\"ת שהגם שהי' עוסק בתורה לשמה כל ימיו וגם הי' לו מס\"נ בתכלית עכ\"ז הי' מסופק אם מוכן לעוה\"ב שהוא גילוי אור הוי' להיות נהנין מזיו ולא בבחי' הסתר ואין זה אלא למי שהוא עובד אלקים בתכלית והי' מסופק אולי הי' עדיין מעורב בלימודו מבחי' הסתר של שם אלקים שהוא מבחי' טבע שבנפש הבהמי' שלא נהפך לגמרי ולכן השיבו כלום מעשה בא לידך וכשסיפר לו מעשה הצדקה השיבו יהי' חלקי כו' שנתינת הצדקה הוא היפוך ממש מטבע המתמיד בלימודו שהוא הכיווץ וצדקה הוא התפשטות ומוכח שלא הי' מצד הטבע כ\"א כבר נהפך וע\"כ אמר יהא חלקי וכו'.\n<b>ועם</b> כל הנ\"ל יובן בענין המדות אהוי\"ר בהתפעלות לה' שנולדים מהתבוננות בגדולת ה' ויכולין להיות ג\"כ מעורב טו\"ר כנ\"ל הגם שנולדים ונמשכין מהתבוננות בגדולת ה' שהוא גילוי אור ה' שמאיר בנפשו בבחי' חכמתו ובינתו שמהם נולדים המדות עכ\"ז בחי' חיצוני' המדות שהוא בחי' ישות והרגשת המדות יש מי שאוהב בחי' תערובות זר שהוא בחי' ישות שהם בחי' העלם והסתר ומגבילין ואינו בבחי' ביטול היש בתכלית כ\"א ע\"י הדעת המתפשט בתוך המדות שהוא בחי' פנימית המדות דייקא וע\"י דווקא הוא עיקר הבירור שלהם שלא יהי' נגבלי' בבחי' חיצוני' והרגשה כו' כ\"א בבחי' ביטול היש בתכלית והיינו ע\"י התקשרות שמקשר וממשיך בחי' הארת חו\"ב בתוך המדות שהוא בחי' הפנימיות של המדות שמתחברים ומתקשרים בתכלית בבחי' גילוי אור ה' שמאיר בבחי' חו\"ב בלבד ולא יהי' מעורבין שם תאוותיו. וכמו\"כ עד\"ז למעלה בעולם האצי' ג\"כ בענין סדר ההשתלשלות י\"ס חב\"ד זת\"ז והמדות עליונים שנק' ו\"ק חו\"ג נמשכו מבחי' ג\"ר הנ\"ל היינו ע\"י בחי' הדעת דוקא שמקשר ומחבר את הארת חו\"ב לתוך המדות שלא יגבילו כלל על אור א\"ס שמאיר בבחי' ח\"ע דאצי' ולכן באצי' אף שיש שם בחי' אורות וכלים שנק' חיוהי וגרמוהי עכ\"ז עדיין בבחי' א\"ס שאין הכלים מגבילים כלל ולכן אין שם יניקה לחיצוני' היינו מפני דעת שמתפשט בתוך המדות משא\"כ בהתלבשות המדות דאצי' בבי\"ע שהוא ע\"י מסך ופרגוד המפסיק שהוא בחי' שם אלקים שמבחי' מל' דאצי' אז אין הדעת העליון מתפשט בבי\"ע ולכן הם בבחי' בע\"ג לפי שהכלים מגבילים.\n<b>והנה</b> כ\"ז הוא בדעת התחתון שהוא בסדר ההשתלשלות די\"ס שהן חב\"ד זת\"ז ואח\"כ הו\"ק נמשכין ונולדין מבחי' ג\"ר וכמו\"כ עד\"ז בכל נפש מישראל בעבודת ה' הם בחי' המדות אהוי\"ר וכדומה שנולדין ונמשכין מבחי' התבוננות בגדולת הוי' כנ\"ל ונק' בחי' אהבה זו אהבת<sup data-n=\"253\">20</sup> עולם אהבתיך אהבה זוטא עולם<sup data-n=\"254\">21</sup> ו\"ק מעלה ומטה כו' וכמו\"כ יובן עד\"ז בבחי' המדות דז\"א שעיקר מציאותן הוא מבחי' המדות דא\"א ודע\"י וכמ\"ש ברע\"מ דז\"א בעתיקא אחיד ותליא כו' רק שעוברים",[["253","20","<b>אהבת עולם אהבתיך</b>: ירמי' לא, ב."],["254","21","<b>עולם ו\"ק מעלה ומטה כו'</b>: בכת\"י ב ליתא."]]],[2101000065,"ומתגלים ע\"י בחי' חו\"ב בבחי' מעבר בלבד שמקבלים מן המוחין דאו\"א ג\"כ אבל עיקר מציאותן הוא למעלה מבחי' חו\"ב כ\"א מבחי' המדות דא\"א ודע\"י כו'. והיינו ג\"כ ע\"י בחי' דעת עליון שמחבר לבחי' חו\"ב יחד והיינו ע\"י סדר ההשתלשלות הנז' בפרדס שהוא ע\"ד ג' קווין חח\"ן מימין כדתי\"מ קו אמצעי נמצא שהדעת הוא למטה מבחי' הכתר ובין חו\"ב שמקשר את בחי' הארת הכתר לבחי' חו\"ב והוא בחי' הפנימי' דחו\"ב ע\"ד הנ\"ל בבחי' דעת התחתון המתפשט בתוך המדות.\n<b>והנה</b> ידוע דאו\"א שרשן מבחי' הכתר ונמצא שבחי' הארת הכתר הוא בחי' פנימי' דאו\"א שנק' חיצוני' לגבי הארת הכתר שמאיר ומתלבש בהם וע\"י בחי' דעת עליון ששרשו מבחי' הכתר שמחבר לבחי' או\"א בבחי' פנימיות שהוא בחי' התקשרות בהארת הכתר ואזי ממילא מאיר ומתגלה בבחי' המדות דז\"א בחי' הארת הכתר שהם בחי' המדות דא\"א ודעת\"י ע\"י אמצעות או\"א וכ\"ז היינו ע\"י בחי' דעת עליון שהוא בחי' הפנימי' דאו\"א ששרשו מבחי' הכתר ונק' בחי' אהבה זו אה\"ר שהיא למעלה מעלה מבחי' חו\"ב דאצי' כו' כנ\"ל כ\"א מבחי' חסד דא\"א וע\"י כו'<sup data-n=\"255\">22</sup>. וכמו\"כ בעבודת ה' בנשמות ישראל יש ג\"כ אה\"ר כי נשמות ישראל נמשכו מבחי' מל' דאצי' ויש בהם ב' סדרי השתלשלות שכולם נמשכו מבחי' מל' והם ב' אהבות הנ\"ל עם ב' בחי' דעת הנ\"ל כו'. והיינו בחי' רעותא דליבא שהוא בחי' ואהבת<sup data-n=\"256\">23</sup> בכל מאודך שהוא בלי גבול ושיעור לבחי' מהותו ועצמותו ממש למעלה מבחי' התבוננות רק שעכ\"ז יציאתו לידי גילוי צ\"ל ע\"י אמצעות התבוננות דוקא אבל אחר יציאתו לידי גילוי בבחי' רעותא דליבא הוא למעלה מבחי' התבוננות והיינו ע\"י בחי' דעת עליון.\n<b>והנה</b> בחי' אה\"ר הנ\"ל למעלה נק' בשם רבקה שהוא רבקה<sup data-n=\"257\">24</sup> של שלש כו' כמו\"כ בחי' המדות דא\"א ודע\"י הוא למעלה מבחי' התחלקות כ\"א עקוד בכלי א' משא\"כ בחי' המדות דז\"א שמבחי' חו\"ב שהם בבחי' התחלקות כו', וזהו ותרד<sup data-n=\"258\">25</sup> העיינה ותמלא כדה ותעל פי' שבחי' רבקה יורדת לתוך עיינה שהוא בחי' ים החכמה שנק' מעיין ע\"ד דוגמא המעיין שנובע ומתגלה מתוך התהום שעדיין אינו נראה כלל כמו\"כ בחי' ים החכמה שרשו מבחי' אין דכתר כמ\"ש והחכמה<sup data-n=\"259\">26</sup> מאין תמצא כו' הגם שהוא בחי' ירידה לגבי בחי' רבקה הנ\"ל עכ\"ז ירדה בבחי' מעיין הנ\"ל בכדי שעי\"ז ותעל שירידה צורך עליה הוא והיינו ע\"י ותמלא כדה שהן<sup data-n=\"260\">27</sup> ך\"ד ספרים דאורייתא שנמשכים מבחי' חכמה כמ\"ש אורייתא<sup data-n=\"261\">28</sup> מחכמה נפקת.\n<b>וביאור</b> הדברים הנה התורה הוא בחי' ביאור וגילוי המצות שכך יהי' התפילין וציצית וכך יהי' פסול היינו הלכות התורה. והנה ידוע שהמצות שרשן",[["255","22","<b>וע\"י כו'</b>: בכת\"י ב: וע\"י משא\"כ אהבת עולם כנ\"ל."],["256","23","<b>ואהבת בכל מאודך</b>: ואתחנן ו, ה."],["257","24","<b>רבקה של שלש כו'</b>: עירובין יז, ב [בכת\"י ב כאן: רבקות של שכל]."],["258","25","<b>ותרד העיינה ותמלא כדה</b>: חיי\"ש כד, טז."],["259","26","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["260","27","<b>שהן ך\"ד ספרים דאורייתא</b>: ראה ת\"ז תכ\"א (מו, ב)."],["261","28","<b>אורייתא מחכמה נפקת</b>: זח\"ב פה, א. קכא, א."]]],[2101000066,"מבחי' הכתר כי תרי\"ג מצות עם ז' דרבנן עולה בגי' תר\"ך שהן תר\"ך עמודי אור הוא בחי' כתר שלמעלה מבחי' ח\"ע רק שיוצאין ומתגלין ע\"י אמצעות בחי' ח\"ע דוקא שמשם נמשכו בחי' חכמת התורה וזהו אורייתא מחכמה נפקת פי' שיוצאת ונפקת לידי גילוי ע\"י בחי' ח\"ע אבל שרשה הוא למעלה מבחי' ח\"ע שהוא מבחי' הכתר, וזהו ותמלא כדה ותעל שהן ך\"ד ספרין דאורייתא שאין זה אלא ד\"מ ששואב כד קטן מים הגדול כמו\"כ בחי' ח\"ע נק' ים החכמה שהיא מקור כל החכמה וכמו עד\"מ חכמת שכל אנושי וחכמת פלוסופי' שכולם שרשם מבחי' אחוריי' דח\"ע ע\"י שבה\"כ ונמצא שך\"ד ספרי דאורייתא שהוא בחי' חכמת התורה אינו אלא בחי' כד קטן נגד ים הח\"ע אכן כמו עד\"מ השואב כד קטן מים הגדול בורר את תכלית המובחר הזך והנקי כמו\"כ בחי' חכמת התורה הגם שהוא בחי' כד קטן עכ\"ז הוא בחי' תכלית המובחר והפנימי' של בחי' ח\"ע דאצי' היינו בחי' הארת הכתר בח\"ע וכמ\"ש החכמה מאין תמצא שהוא בחי' אין דכתר ונמצא שיש הארת הכתר בחכמה ונק' בחי' פנימי' דחכמה ובו מתגלין דווקא המצות ששרשן מבחי' הכתר, וזהו ותרד העיינה ותמלא כדה ותעל שבחי' רבקה הנ\"ל היא יורדת לתוך בחי' המעיין שהוא בחי' ח\"ע דאצי' ותמלא את כדה שהן ך\"ד ספרין דאורייתא פנימי'<sup data-n=\"262\">29</sup> המל' שבכתר שבח\"ע בכדי שעי\"ז ותעל שהוא בחי' העלי' שאח\"כ ע\"י המצות שמתגלין למטה בהלכות התורה.\n<b>ועתה</b> יובן הפסוק אם יתן איש את כל הון ביתו באהבה בוז יבוזו לו, דהנה לעיל מיני' כתי' מים רבים לא יוכלו כו' אם יתן כו'. כי הנה מבואר למעלה שיש בנש\"י ב' בחי' אהבה א' אהבה הנמשך רק ע\"י התבוננות בגדולת ה' ונק' אהבת עולם, וב' אהבה בכל מאדך שהוא בחי' רעותא דליבא שלמעלה מהתבוננות כ\"א שרשה מבחי' הכתר וע\"י שהוא בחי' יחידה שבנפש ונק' אה\"ר. והנה על בחי' אה\"ר זו נאמר מים רבים לא יוכלו לכבותה פי' מים רבים הוא בחי' ח\"ע דאצי' שנק' ים החכמה ולכן אינה יכולה לכבותה את אה\"ר ששרשה למעלה מבחי' ח\"ע רק מבחי' הכתר אבל בחי' אהבת עולם ששרשה מבחי' חו\"ב ע\"י הדעת המתפשט בזה יכול לרוות צמאונו בבחי' מים רבים הנ\"ל שהוא בחי' ים החכמה שיכול לכבות את האהבה לפי שנמשכת משם משא\"כ בחי' אה\"ר הנ\"ל כו', אם יתן איש את כל הון ביתו פי' חכמה נק' בית והון ביתו היינו האוצרות והמטמונים שבתוך הבית והיינו בחי' הארת הכתר המאיר בבחי' פנימי' החכמה שהוא בחי' חכמת התורה שבהם מתגלים בחי' המצות ששרשן מבחי' הכתר שנק' הון ביתו וכמ\"ש ובדעת חדרים ימלאון כל הון יקר ונעים פי' בחכמה יבנה בית שהוא רק בנין הבית לבד שהן אותיות התורה שבכתב שעדיין אינו מובן לגמרי ובתבונה יתכונן הוא בחי' תושבע\"פ אכן בדעת חדרים ימלאו כל הון יקר, הון בחי' הלכות התורה שבהם מתגלים המצות ששרשן מבחי' פנימי' רצון תענוג עליון שנק' הון יקר ונעים פי' שמתגלין בחכמת התורה ע\"י בחי' דעת העליון כנ\"ל. והנה בבחי' הון בית הזה שהוא גילוי רצון",[["262","29","<b>פנימי' המל' שבכתר שבח\"ע</b>: בכת\"י ב: שהוא הפנימיות והמובחר שבח\"ע."]]],[2101000067,"ותענוג המצות שבבחי' חכמת התורה יכול להתאחד גם בחי' אה\"ר הנ\"ל הגם ששרשו מבחי' כתר ע\"י בחי' דעת עליון מפני שגם בחי' הון ביתו שרשו מבחי' כתר ע\"י בחי' דעת עליון הנ\"ל שע\"י ימלאו כל החדרים בהון ונעים כו', וזהו אם יתן כל הון ביתו באהבה שהוא בחי' אה\"ר הנ\"ל אזי בוז יבוזו לו פי' עד\"מ כאדם הבוזז וחוטף דבר שאינו שלו שלא עמל בזה כמו\"כ בחי' רצון ותענוג המצות שמתגלה בהלכות התורה הוא למעלה מהשתלשלות וד\"ל. אך עכ\"ז אין בחי' הון ביתו מכבה את האהבה הנ\"ל לגמרי כי גם האה\"ר הנ\"ל שרשה מבחי' הכתר הנ\"ל כ\"א בחי' אהבה הנ\"ל מתאחדת עם הון ביתו הנ\"ל ואזי נק' אהבה בתענוגים וזהו יבוזו לו ולא כתי' אותי<sup data-n=\"263\">30</sup> כ\"א לו לאהבה הנ\"ל שגם האהבה רבתה<sup data-n=\"264\">31</sup> ובטילה משא\"כ בבחי' אהבת עולם גם מים רבים שהוא בחי' חכמה מכבה ומרווה את צמאונו לגמרי וכמ\"ש הוי<sup data-n=\"265\">32</sup> כל צמא לכו למים והיינו מפני שבחי' חכמה הוא למעלה מבחי' אהבת עולם הנ\"ל שנמשכו ממנו כו' משא\"כ בחי' אה\"ר שהוא משרש א' עם הון ביתו.\n<b>ועתה</b> יובן הלשון דאם יתן כל הון ביתו לשון עתיד דהנה בחי' הון ביתו הנ\"ל שהוא בחי' רצון ותענוג עליון של המצות שמתגלה בהלכות התורה אינה מתגלה עתה כ\"א לעתיד יתגלה בבחי' גילוי ממש כמ\"ש ישקני<sup data-n=\"266\">33</sup> מנשיקות פיהו שהוא בחי' פנימיות טעמי המצות שיתגלה לעתיד. וזהו חייב<sup data-n=\"267\">34</sup> אדם לברך ק' ברכות בכל יום פי' להמשיך בכל יום המשכות בחי' אור הכתר שנק' מאה כידוע בבחי' מל' שיתגלה לעתיד (יתגלה<sup data-n=\"268\">35</sup> בבחי' גילוי ממש) ע\"י עסקו בתורה ומצות בעוה\"ז ששרשן מבחי' הכתר הנ\"ל, כי זה כל האדם בעוה\"ז להמשיך מבחי' סוכ\"ע שהוא בחי' כתר בבחי' ממכ\"ע שהוא<sup data-n=\"269\">36</sup> בחי' יחו\"ע ביחודא תתאה וזהו ענין ברכות המצות ברוך אתה הוי' אלקינו שהוא בחי' יחו\"ע מלך העולם יחו\"ת, והכל נמשך ע\"י אשר קדשנו במצותיו שהוא בחי' הארת התענוג מכתר עליון שנק' אשר כידוע שבבחי' המצות שהם בבחי' מל' והיינו המשכות בחי' סוכ\"ע בבחי' ממכ\"ע, אמנם עיקר הגילוי יהי' לעתיד דייקא וכמ\"ש ה'<sup data-n=\"270\">37</sup> ימלוך לעולם ועד שהוא בחי' הארת סוכ\"ע בבחי' ממכ\"ע<sup data-n=\"271\">38</sup> הנק' ועד.\n<b>והנה</b> להבין את זאת היטיב איך יהי' בחי' גילוי בחי' סוכ\"ע שהוא למעלה מבחי' השתלשלות כ\"א סובב בהשוואה א' בבחי' ממכ\"ע שהוא בחי' השתלשלות, צריך לבאר ענין ההפרש שבין סוכ\"ע ובין ממכ\"ע. דהנה סוכ\"ע אין הפי' סובב ומקיף מלמעלה כ\"א שמתלבש ג\"כ בתוך כל העולמות וכמ\"ש את<sup data-n=\"272\">39</sup> השמים ואת",[["263","30","<b>אותי</b>: בכת\"י ב: אותו."],["264","31","<b>רבתה</b>: בכת\"י ב: נכבית."],["265","32","<b>הוי כל צמא לכו למים</b>: ישעי' נה, א."],["266","33","<b>ישקני מנשיקות פיהו שהוא בחי' פנימיות טעמי המצות</b>: שה\"ש א, ב ופירש\"י שם."],["267","34","<b>חייב אדם לברך ק' ברכות</b>: מנחות מג, ב."],["268","35","<b>יתגלה בבחי' גילוי ממש</b>: בכת\"י ב ליתא תיבות אלו."],["269","36","<b>שהוא בחי' יחו\"ע ביחודא תתאה</b>: בכת\"י ב: שהוא בחי' יחו\"ת."],["270","37","<b>ה' ימלוך לעולם ועד</b>: בשלח טו, יח."],["271","38","<b>ממכ\"ע</b>: בכת\"י ב נוסף: שמבואר בכ\"מ צריך לבארם היטב באריכות."],["272","39","<b>את השמים ואת הארץ אני מלא</b>: ירמי' כג, כד."]]],[2101000068,"הארץ אני מלא נמצא שגם בחי' אני שהוא מהותו ועצמותו ית' מלא בשמים ובארץ וכמאמר<sup data-n=\"273\">40</sup> הזהר לית אתר פנוי מיני' רק שמלא בכל עלמין בהשוואה א' ואין בו בחי' השתלשלות מעלה ומטה כ\"א<sup data-n=\"274\">41</sup> שווין ובחי' ממלא בחי' השתלשלות מעלה ומטה וכמבואר<sup data-n=\"275\">42</sup> במ\"א. ולכאורה יפלא איך יתכן מהותו ועצמותו ית' ממש שנק' אני שהוא בחי' אוא\"ס הפשוט בתכלית הפשיטות מלא ממש גם בבחי' הארץ הגשמי' החומרי' ומלא ג\"כ קליפות וסט\"א<sup data-n=\"276\">43</sup>, אך הענין הוא דעיקר ההפרש שבין בחי' ממלא לסוכ\"ע הוא כך שבחי' סוכ\"ע הוא בתוך כל עלמין בבחי' העלם ולכן הוא בהשוואה א' משא\"כ בחי' ממלא הוא שממלא כל עלמין בבחי' הגילוי ולכן הוא בבחי' השתלשלות מעלה ומטה.\n<b>וביאור</b> העלם וגילוי, יובן עד\"מ מבשרי אחזה דהנה אנו רואים באדם למטה המחשבה שבמוח מתלבשת ממש גם בכל אברי הגוף עד שגם בקיבה וכרס שמלא טינופת ישנו ג\"כ כח המחשבה ממש כאשר נראה כשיחשוב לכווץ הכרס אזי תיכף מתכווץ וכאשר יחשוב להתפשט אזי מתפשט ונמצא מובן מזה שבחי' המחשבה ישנה ג\"כ בכרס וקיבה ועכ\"ז לא יתכן לומר שיתטנף המחשבה מהכרס<sup data-n=\"277\">44</sup> וע\"כ היינו מפני שגם שישנה שם עכ\"ז אינו שם בבחי' גילוי והרגשה להיות מורגשת ונגלית בתוכה כמו שמתלבשת במוח הראש ששם הוא בבחי' גילוי והרגשה משא\"כ בשאר האברים הגם שישנו שם עכ\"ז אינו בבחי' גילוי אלא בבחי' העלם שאינה מתצמצמת שם כלל לפי אברי הגוף ההם כמו שמתצמצמת ונגלית לפי ערך המוח ולזאת בחי' העלם המחשבה יכולה להיות בכל האברים בהשוואה א' ממש גם בכרס וקיבה הנ\"ל. וע\"ד דוגמא משל זה יובן למעלה בחי' ממלא ובחי' סובב, ממלא הוא בחי' גילוי אור אלקי המאיר ונתגלה בכל עולם ועולם לפי מדריגתו ע\"י ירידות והשתלשלות החיות מאור א\"ס ב\"ה שמהווה אותם מאין ליש בריבוי השתלשלות וצמצומים להעלים ולהסתיר את אור הוי' הנמשך מאוא\"ס ב\"ה שהוא פשוט בתכלית הפשיטות בבחי' א\"ס ממש שלא יתגלה למטה בבחי' יש ומציאות ונבראים פרטים כאלו שהם בע\"ג בכל עולם ועולם לפי מדריגתו כמו מלאכים ונשמות דבריאה להיות נהנין ומתענגין מהשגתן שיש גבול להשגתן והאופנים וחיות שבעולם היצי' שהם בבחי' גבול יותר עד ירידת והשתלשלות בריבוי צמצומים והסתרות שגם עולם העשי' שהוא בבחי' יש ודבר נפרד לגמרי עכ\"ז יהי' נמצאים וחיים וקיימים מבחי' חיות הנמשך להם מאוא\"ס ב\"ה המחי' ומהוה אותם מאין ליש בבחי' יש ומציאות נפרדים והן השתלשלות לכל העולמות שהן ריבוי רבבות מדריגות פרטים ומיוחדים מובדלים זמ\"ז בתכלית שאין כ\"א דומה לחבירו אמנם כ\"ז אינו אלא בבחי' הגילוי לבד היינו גילוי אופן מציאותם",[["273","40","<b>וכמאמר הזהר לית אתר פנוי מיני'</b>: ת\"ז תנ\"ז (צא, ב). ת\"ע (קכב, ב)."],["274","41","<b>כ\"א שווין ובחי' ממלא בחי' השתלשלות מעלה ומטה</b>: בכת\"י ב ליתא כ\"ז."],["275","42","<b>וכמבואר במ\"א</b>: בכת\"י ב: וכמבואר כ\"ז בכ\"מ באריכות."],["276","43","<b>וסט\"א</b>: בכת\"י נוסף: (והוא ע\"ד קושי' הידוע שאיך יתכן שבחי' מהותו ועצמותו ית' ממש יהי' מלא כביכול גם בבה\"כ)."],["277","44","<b>מהכרס</b>: בכת\"י ב נוסף: וכל מי שיש לו מוח בקדקדו לא יאמר זה."]]],[2101000069,"והתהוותם מבחי' אוא\"ס ב\"ה שמחי' ומהווה אותם מאין ליש שבזה יש ריבוי רבבות מדריגות שבחי' גילוי החיות של עולם הבריאה הוא בבחי' ביטול והתכללות יותר באור ה' מבחי' גילוי החיות של עולם היצי' אלא הוא בבחי' ישות יותר עד שבחי' עולם העשי' הוא תכלית מדריגה התחתונה ממש מבחי' גילוי אור ה' שמצומצם בהן לגמרי ועל בחי' גילוי החיות זה נאמר מלא<sup data-n=\"278\">45</sup> כל הארץ כבודו שאינו אלא זיו יקרי' כו' שיש בזה ריבוי השתלשלות מדריגות מעלה ומטה משא\"כ בחי' ההעלם ועצם<sup data-n=\"279\">46</sup> החיות אלקי המהווה את כולם מאין ליש שהוא בבחי' אוא\"ס הפשוט בתכלית הפשיטות כנודע שבחי' התהוות מאין ליש אף בחי' ומדריגה התחתונה שבעשי' אינה אלא מבחי' א\"ס הפשוט וזאת נק' בורא ומאציל שאינו אלא בורא ומאציל אחד שבורא ומאציל לבחי' ומדריגה היותר תחתונה בבחי' גילוי ובחי' היותר עליונה כולם בהשוואה א' ממש מאחר שהוא בחי' א\"ס הפשוט אין לפניו כלל בחי' מעלה ומטה, ועל בחי' העלם זה נאמר את השמים ואת הארץ שהם כלליות כל ההשתלשלות אני מלא בהשוואה א' כו' שהוא בחי' אוא\"ס הפשוט בבחי' א\"ס ממש שהוא עצם החיות של כל הנאצלים ונבראים ממש שמהווה את כולם מאין ליש כו', ונמצא שהוא מלא ממש בשמים ובארץ בהשוואה<sup data-n=\"280\">47</sup> א' בבחי' סובב ומקיף עליהם מלמעלה בלבד ולא בתוכם ממש רק שאינה אלא בבחי' העלם החיות לבד ולא בבחי' הגילוי החיות אך<sup data-n=\"281\">48</sup> שמתגלים ונראים למציאות יש ודברים נפרדים שבזה יש ריבוי רבבות השתלשלות המדריגות שנק' ממכ\"ע בבחי' הגילוי שאין מתגלה בהם כלל בחי' אוא\"ס הפשוט שהוא בחי' העלם עצם החיות שלהן ולכן כינו המקובלים לבחי' העלם עצם החיות זה שמבחי' אוא\"ס הפשוט בשם סוכ\"ע שהוא ע\"ד דוגמת העיגול שסובב ומקיף מכל צדדיו בהשוואה ואין בו מעלה ומטה כלל.\n<b>ואחר</b> כל הנ\"ל יובן מ\"ש לעתיד ה' ימלוך לעולם ועד שהוא ענין גילוי בחי' דסוכ\"ע בבחי' ממכ\"ע שיהי' אז דהיינו שבחי' אור ה' שבבחי' א\"ס ממש שהוא בחי' העלם עצם החיות של כל הנבראים מאיר ומתגלה בהם בבחי' גילוי ממש אף שיהי' אז ג\"כ בחי' השתלשלות ומציאות נבראים פרטים ממש מבחי' ממלא עכ\"ז מאיר ומתגלה בהם בגילוי ממש בחי' העלם דסובב.\n<b>וביאור</b> הדברים יובן ע\"ד דוגמא מארז\"ל<sup data-n=\"282\">49</sup> בענין תחה\"מ שלא תהי' אכילה ושתי' גשמי' כלל ועכ\"ז יחיו ויתקיימו בגופים גשמיי' ממש עם כל פרטי האברים שיהי' אז ג\"כ כנודע מתענוג העליון האלקי שיתענגו בהשגתם כמ\"ש וראו<sup data-n=\"283\">50</sup> כל בשר כו' ועי\"ז יחיו ויתקיימו חיים גשמיים ממש, ולכאורה יפלא דבר זה",[["278","45","<b>מלא כל הארץ כבודו. . זיו יקרי'</b>: ישעי' ו, ג. ות\"י שם."],["279","46","<b>ועצם</b>: בכת\"י ב: מעצם."],["280","47","<b>בהשוואה א' בבחי' סובב ומקיף עליהם מלמעלה בלבד ולא בתוכם ממש</b>: בכת\"י ב: בהשוואה א' ולא בבחי' סובב ומקיף עליהם מלמעלה בלבד כ\"א בתוכם ממש."],["281","48","<b>אך</b>: בכת\"י ב: איך."],["282","49","<b>מארז\"ל בענין תחה\"מ שלא תהי' אכילה ושתי' גשמי' כלל</b>: ראה ברכות יז, א."],["283","50","<b>וראו כל בשר</b>: ישעי' מ, ה."]]],[2101000070,"מאד שיהי' גוף הגשמי ונפש החיונית חיים וקיימים שלא ע\"י אכילה ושתי' כ\"א מבחי' כח אלקי, דהנה נודע בספרי חכמי הפלוסופים שעיקר קיום נפש החיוני שהוא נפש הטבעית והבהמית להחיות את הגוף ממש להיות החי מתנענע הוא ע\"י אכילה דוקא להיות נפש החיונית הוא בחי' חיות רוחני ואיך ישרה ויתלבש באיברי הגוף הגשמי אם לא בהתלבשות בבחי' האדים הרוחני' הדקים היוצאים מהדמים שבתוך האברים וכמבואר שיש בהדמים כח החמימות שממנו יוצאים האדים אשר לזאת כשירבה החמימות בדמים יתרבו האדים ויחלה בחולי החמימות ועל היפוך כאשר יוחלש ויתמעט חמימות הדמים ביותר יחלה בחולי החלישות והקרירות להיות כי עיקר קיום והשראת חיות הנפש החיוני' הוא רק בתוך האדים היוצאים מחמימות הדמים שהם דקים רוחני' ולכן אמרו כי<sup data-n=\"284\">51</sup> הדם הוא הנפש לפי שבו דייקא משכן החיות וכאשר יכלו הדמים ממילא יסתלקו<sup data-n=\"285\">52</sup> האדים. והנה הלב הוא מקום<sup data-n=\"286\">53</sup> המשכן הדמים של כל האברים שבו נכנסין ויוצאין ומתפשטין לכל האברים כנודע שיש בלב ב' חללים א' שבו מתכנסין והב' שממנו יוצאין לכל האברים ולכן עיקר משכן נפש החיוני' הוא בלב דהיינו בתוך<sup data-n=\"287\">54</sup> האברים היוצאים מהדמים שעיקר משכנם הוא בלב ומן הלב נמשך ונתפשט החיות לכל האברים עד הדמים היוצאים מן הלב לכל האברים לכל אבר לפי מזגו ותכונתו, ולכן<sup data-n=\"288\">55</sup> אמרו שהלב פליג חיות לכל שייפין והיינו ע\"י אמצעות<sup data-n=\"289\">56</sup> האדים מהדמים שיוצאים ומתפשטין מן הלב לכל האברים. והנה נודע בספרי הרפואות שהדמים של האברים מתמעטין מעט מעט בטבען עד שיוכלו לכלות לגמרי וממילא מובן שכאשר יתמעטו הדמים ממילא יתמעט ויכלה בחי' החיות וע\"כ עיקר קיום החיות הנפש בגוף הוא ע\"י האכילה דייקא להיות שמן המאכל נעשה דם בכבד אחר הבירור שבקיבה שמברר את המאכל והפסולת נדחה לחוץ והמובחר נעשה דם בכבד ומן הכבד עולה מובחר הדם אל הלב ומן הלב מתפשט לכל האברים ונמצא שע\"י המאכלים מתרבים ומתחזקי' הדמים של כל האברים ובתוכם שורה בחי' כח החיוני שבנפש החיוני' וע\"כ<sup data-n=\"290\">57</sup> אמרו חכמים כאשר יפסוק האדם מלאכול בהכרחו למות שבלתי האכילה מתמעטין כל הדמים שבאברים וממילא יסתלקו כח החיות שלהם שאין שורה כ\"א באדים הרוחני' היוצאים מחמימות הדמים, והנה גם בחי' נפש השכלי' השורה במוח הראש א\"א לו להתקיים ג\"כ בלא אכילה להיות כי נפש השכלי' שהוא רוחני יותר אינו שורה בתוך המוח גשמי כ\"א באמצעות נפש החיוני' ששורה ומתלבש<sup data-n=\"291\">58</sup>",[["284","51","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג."],["285","52","<b>יסתלקו האדים</b>: בכת\"י ב: יסתלק החיות."],["286","53","<b>מקום</b>: בכת\"י ב: מקור."],["287","54","<b>בתוך האברים</b>: בכת\"י ב: בבחי' האידים הרוחניי'."],["288","55","<b>ולכן אמרו שהלב פליג חיות לכל שייפין</b>: זח\"ג קסא, ב."],["289","56","<b>אמצעות האדים מהדמים</b>: בכת\"י ב: אמצעות הדם."],["290","57","<b>וע\"כ אמרו חכמים כאשר יפסוק האדם מלאכול בהכרחו למות</b>: בכת\"י ב: וע\"כ אמרו חכמי הרפואה שכאשר יפסוק האדם מלאכול כמה ימים בהכרח למות יש מהן אומרים בעשרה ימים דוקא ויש מהן שגם בג' ימים וכו' והכל מטעם הנ\"ל."],["291","58","<b>ומתלבש כו' ובהחיות ההוא</b>: בכת\"י ב: ומתלבש בתוך האידים הדקים היוצאי' מהדמים שבתוך המוח כנ\"ל ומן החיות ההוא."]]],[2101000071,"כו' ובהחיות ההוא שורה ומתלבש בחי' חיות נפש השכלי' שהוא רוחני יותר וכמו\"כ אף בחי' חיות נפש אלקי שבכאו\"א מישראל אינו שורה כ\"א<sup data-n=\"292\">59</sup> באמצעי נפש השכליות ששורה באמצעות נפש החיוניות שהנפש החיוני' מתלבשת באמצעות הדמים הדקים כנ\"ל, וכנודע שיש ג' נפשות בכאו\"א מישראל והגם<sup data-n=\"293\">60</sup> שבלק\"א לא נז' רק ב' אבל עפ\"י אמת הם ג' והם נפש החיוני' ונפש השכלית ונפש האלקי' ונמצא לפי זה שעיקר קיום לכל הנפשות בתוך הגוף הוא ע\"י האכילה דייקא שע\"י מתרבים ומתחזקין הדמים והאברים משא\"כ בלתי אכילה שמתמעטין וכלין הדמים וממילא מסתלק כח החיות שמנפש החיוני' וממילא מסתלק ג\"כ נפש השכלית ונפש האלקי' שאינם שורין כ\"א בהתלבשותם זב\"ז כו'.\n<b>ואחר</b> כל זה יפלא מאד על לעתיד שיהי' גם אז גופי' גשמי' בכל פרטי האברים ובתוכם דמים גשמי' ממש כאשר מוכח ממארז\"ל<sup data-n=\"294\">61</sup> שגם קרבנות לא יתבטלו לעתיד ונודע ענין הקרבנות שהוא ענין בחי' העלאת דם הבהמה שהוא בחי' נפש החיוני' שלה כי<sup data-n=\"295\">62</sup> הדם כו' נותן ע\"ג המזבח שהוא בחי' מל' דאצי', וכדוגמת הקרבנות ע\"ג המזבח מוכרח להיות ג\"כ בכל נפש מישראל בפרט בעבודה שבלב זו תפלה שנק' מזבח להעלות אז בחי' דם ונפש החיוני' שלו, וא\"כ מוכרח מכ\"ז שיהי' אז בחי' דמים גשמי' ונפש החיוני' וא\"כ איך יתכן שיחיו ויתקיימו בלתי האכילה שמבואר מכל הנ\"ל שיכלו הדמים וממילא יכלה ויסתלק החיות כו'.\n<b>אך</b> הענין הוא ע\"ד הנ\"ל דכ\"ז הוא עתה שעיקר הגילוי הוא מבחי' ממכ\"ע לבד כנ\"ל שהן ריבוי ההשתלשלות והם חיים וקיימים בבחי' גילוי מציאות יש ונבראים פרטים ונפרדים שכולם הם בבחי' ממכ\"ע משא\"כ בחי' סוכ\"ע שהוא בחי' עצם החיות של כל העולמות שהוא בבחי' אוא\"ס הפשוט הוא בבחי' העלם והסתר החיות לגמרי שמוסתר ונעלם בבחי' ממכ\"ע שהם בחי' גילוי מציאות ונפרדים פרטים ומוגבלים שמגבילים ומסתירים על בחי' אוא\"ס הפשוט ובלתי מוגבל שהוא עיקר עצם החיות שלהם המהוה אותם כו' שאין מאיר בהם בבחי' גילוי כלל וכמו\"כ בכל נפש מישראל בחי' כח אלקי שבנפשו האלקי' ששרשו מבחי' סוכ\"ע כנודע וכמ\"ש כי<sup data-n=\"296\">63</sup> חלק ה' עמו כו' שהוא בחי' חלק משם הוי' הבלתי בע\"ג הוא בבחי' העלם והסתר בבחי' נפש החיוני' והשכלי' ששרשו מבחי' ממכ\"ע להיות בבחי' גילוי מציאות<sup data-n=\"297\">64</sup> יש וגילוי ונבראים פרטים ונפרדים כו' שכולם הם מבחי' ממכ\"ע כנ\"ל, יש ונפרד ומעלים ומסתיר על אור נפש אלקי' שהוא בחי' כח אלקי ובלתי מוגבל שאינו מאיר כלל בגילוי כ\"א בהתלבשותו בבחי' נפש השכלי' והחיוני' שמלבישים",[["292","59","<b>כ\"א באמצעי נפש השכליות ששורה באמצעות נפש החיונית שהנפש החיוני' מתלבשת באמצעות הדמים הדקים כנ\"ל</b>: בכת\"י ב: כ\"א באמצעות התלבשותו בנפש השכלי' ששורה ומתלבש באמצעות נפש החיונית ששורה ומתלבש באמצעות אידי הדמים הדקים וכו' כנ\"ל."],["293","60","<b>והגם שבלק\"א לא נז' רק ב'</b>: תניא פ\"א."],["294","61","<b>ממארז\"ל שגם קרבנות לא יתבטלו לעתיד</b>: ראה ויק\"ר פ\"ט, ז."],["295","62","<b>כי הדם כו'</b>: פ' ראה יב, כג."],["296","63","<b>כי חלק ה' עמו</b>: האזינו לב, ט."],["297","64","<b>מציאות יש. . מבחי' ממכ\"ע כנ\"ל</b>: בכת\"י ב ליתא שורה זו."]]],[2101000072,"ומסתירים עליו ולכן עתה א\"א לנפש החיוני' שהוא החיות בבחי' מציאות יש ונפרד להתקיים כ\"א ע\"י האכילה דוקא שע\"י מתרבים הדמים כנ\"ל משא\"כ לעתיד שיהי' גילוי בחי' ההעלם דסוכ\"ע בבחי' ממכ\"ע דהיינו שבחי' גילוי דממלא לא יעלים ולא יסתיר כלל על בחי' ההעלם אוא\"ס הפשוט דבחי' סוכ\"ע כ\"א אדרבה שבחי' הגילוי דממלא יהי' נכלל בתכלית היחוד בבחי' העלם דסובב שלא יעלימו ולא יגבילו ויסתירו כלל כ\"א יהי' הגילוי אוא\"ס בהם אף שיהי' בבחי' נבראים פרטים וכמשנ\"ת שזהו גילוי דסובב בבחי' ממלא שיהי' אז דהיינו שגם שיהי' בבחי' ממלא לא יגביל ויכסה על בחי' העלם דסובב שמאיר בהם בגילוי ממש וכמ\"ש וראו כל בשר כו' וכמו\"כ בכל א' מישראל בחי' חיות נפשו החיוני' והשכלית שמבחי' ממלא כנ\"ל לא יעלימו ולא יסתירו כלל על בחי' אור נפשו האלקי' כו' כ\"א אדרבה בחי' נפשו החיוני' והשכלית יהי' נכללים בתכלית בבחי' נפש האלקי' ויחיו ויתקיימו גם הם מבחי' חיות אלקי שנבפשו אלקית ולכן אף שיהי' אז ג\"כ בבחי' גופים גשמיים ודמים גשמיים ממש יחיו ויתקיימו ממש גם בלא אכילה גשמי' כלל מאחר שגם בחי' נפש החיוני' יהי' נכללים בתכלית בבחי' נפש האלקי' שיאיר בהם בבחי' גילוי כנ\"ל ע\"ד דוגמת בחי' הגילוי דבחי' סוכ\"ע בבחי' ממכ\"ע כנ\"ל.\n<b>וזהו</b> מ\"ש ה'<sup data-n=\"298\">65</sup> לאורך ימים שהוא בחי' אריכות ימים שיהי' אז וכמ\"ש מנוחה<sup data-n=\"299\">66</sup> לחי העולמים שהוא בחי' אלף הז' שנק' יום שכולו שבת יום<sup data-n=\"300\">67</sup> שכלו ארוך כו' דהנה<sup data-n=\"301\">68</sup> מבואר בע\"ח שעתה עיקר הגילוי הוא רק מבחי' הקו וחוט הנמשך ומאיר בתוך החלל אחר בחי' הצמצום ומק\"פ כו' וגם זה הקו אינו נמשך עד תחתיתו ממש כו' משא\"כ לעתיד יתגלה בתוך בחי' הקו וחוט הנ\"ל מבחי' עיגול הראשון שמקיף את כל החלל בהשוואה א' ויש מהמקובלים אומרים שגם בחי' הקו וחוט יהי' נמשך אז עד למטה בתחתיתו ממש ויתחבר העיגול עם ב' הצדדים וכ\"ז היינו ע\"ד הנ\"ל שבחי' העלם הסובב עצמו שבבחי' א\"ס יתגלה אז בבחי' ממלא ממש כנ\"ל<sup data-n=\"302\">69</sup>. ויובן זה קצת ע\"ד דוגמא מעט מבחי' האצי' עתה דהגם שיש שם ג\"כ אורות וכלים והיכלות כו' עכ\"ז אין הכלים מסתירים ומגבילים כלל על בחי' אור א\"ס כנ\"ל, וכמ\"ש איהו<sup data-n=\"303\">70</sup> וחיוהי וגרמוהי חד בבחי' א\"ס ממש וע\"ד דוגמת זה יהי' לעתיד גילוי בחי' סובב כ\"ע שלמעלה מעלה מכל ההשתלשלות בבחי' ממלא שלא יעלימו ולא יסתירו כלל כו', וזהו ה' לאורך ימים שנק' אריכות ימים וד\"ל.",[["298","65","<b>ה' לאורך ימים</b>: תהלים צג, ה."],["299","66","<b>מנוחה לחי העולמים. . יום שכולו שבת</b>: ע\"פ סוף מס' תמיד."],["300","67","<b>יום שכולו ארוך</b>: ראה קידושין לט, ב."],["301","68","<b>דהנה מבואר בע\"ח שעתה עיקר הגילוי הוא רק מבחי' הקו וחוט</b>: ע\"ח ש\"א ענף ב'."],["302","69","<b>ויש מהמקובלים אומרים. . בבחי' ממלא ממש כנ\"ל</b>: בכת\"י ב כל קטע זה הוא בקיצור יותר: (ויש מהמקובלים שאומרים שגם בחי' הקוה\"ח יהי' נמשך אז בבחי' ממלא ממש). וראה בכ\"ז גם אוה\"ת בראשית מא, ב. סה\"מ תרנ\"ט ע' קי ואילך. המשך תער\"ב ח\"א ע' קיז. סה\"מ תש\"ב ע' 122. לקו\"ש חל\"ה ע' 136."],["303","70","<b>איהו וחיוהי וגרמוהי חד</b>: ת\"ז בהקדמה (ג, ב)."]]],[2101000073,"<h3>זכור את יום השבת</h3>\n<b>זכור את יום השבת </b>\n<b>זכור</b><sup data-n=\"304\">1</sup> את יום השבת לקדשו<sup data-n=\"305\">2</sup> ובדברות האחרונות נאמר שמור<sup data-n=\"306\">3</sup> את יום השבת כו'. וידוע בדברי רז\"ל דזכור<sup data-n=\"307\">4</sup> ושמור בדיבור אחד נאמרו. והנה לכאורה יש להבין במ\"ש זכור את יום כו' דמשמע שזהו ענין ציווי ואזהרה לישראל שהם דווקא יקדשו את יום השבת הרי אמרו ז\"ל דשבת<sup data-n=\"308\">5</sup> מיקדשי וקיימא מששת י\"ב שהרי כל שבת נק' שבת בראשית כידוע ומפורש בכתוב ויברך<sup data-n=\"309\">6</sup> אלקים את יום השבת ויקדש אותו דקוב\"ה קדיש לשבת וישראל<sup data-n=\"310\">7</sup> הוא דקדשינהו לזמנים כמ\"ש אלה<sup data-n=\"311\">8</sup> מועדי ה' אשר תקראו אתם אתם אפי' שוגגין כו' אבל קדושת השבת אינה תלוי' בישראל כלל כי קדושת השבת הוא למעלה ממדריגות ישראל כי שורש השבת בבחי' חכמה עילאה ולכך נק' שבת בראשית משום שנאמר בשבת ושמרתם<sup data-n=\"312\">9</sup> את השבת כי קודש הוא כו' וכל קדש הוא בחי' חכ'<sup data-n=\"313\">11</sup> שבה מלובש אוא\"ס עצמו וכמ\"ש ה'<sup data-n=\"314\">10</sup> בחכ' כו' והחכ' נק' ראשי' כמ\"ש ראשי' חכ' כו' וכידוע ע\"כ נק' שבת בראשית ולכך אין ביכולת ישראל לקדש את השבת רק שישמרו את קדושת השבת שכבר מקדשא וקיימא מעצמו' אא\"ס כמ\"ש ויקדש אותו, וא\"כ לכאורה אינו מובן מה שמצוה לישראל זכור את יום השבת לקדשו מאחר דלאו בדידהו תלי' קדושתו (אבל שמור את יום כו' יתכן דאינו אלא שמירה לקדושה שכבר חלה כו' כמו ושמרתם את השבת כו' וכל<sup data-n=\"315\">12</sup> מקום שנאמר השמר פן ואל הוא מל\"ת אבל מ\"ע לקדש יום השבת הוא שיעשו את הקדושה מצד אתדל\"ת הרי לאו בדידהו תלי' כדלעיל). ועוד י\"ל דאם קדושת השבת תלוי בישראל למה אנו מברכי' בא\"י מקדש השבת דמשמע דקדושה זו צ\"ל מלמעלה (אבל במועדים דקדושייהו תלי' בישראל ע\"כ אנו או' בא\"י מקדש ישראל והזמנים ישראל תחלה ואח\"כ ישראל מקדשי לזמנים). והנה י\"ל עוד למה נאמר על השבת זכור ושמור שהן מ\"ע ומל\"ת כידוע דכל השמר פן כו' הוא מל\"ת וגם איך אמרו דזכור ושמור בדיבור א' נאמרו אחר שזה מ\"ע וזה מל\"ת כידוע בדרז\"ל בפי' זה שמי כו' וזה<sup data-n=\"316\">13</sup> זכרי כו' דשמי עם י\"ה גי' שס\"ה ל\"ת וזכרי עם ו\"ה גי' רמ\"ח מ\"ע וא\"כ גם פי' זכור הוא בבחי' מ\"ע ושמור הוא בבחי' ל\"ת (ולא יקשה מזה שאמרו דאנכי<sup data-n=\"317\">14</sup> ולא יהי' לך בדיבור א' נאמרו דמפי<sup data-n=\"318\">15</sup> הגבורה שמענו), ועוד י\"ל",[["304","1","<b>זכור את יום השבת</b>: נדפס בשינוים בתו\"א יתרו סט, ג. ובארוכה בתו\"ח שמות ח\"ב רסד, א. הערות וקיצורים נדפסו באוה\"ת יתרו ע' תתקמה (וראה שם ע' תתקכה). שם כרך ז' ע' ב'תרצ-ב'תשטו. וראה עוד בארוכה סה\"מ תרכ\"ז ע' קכה (ובהוצאה הקודמת ע' קטו), ובהמ\"מ שם."],["305","2","<b>זכור את יום השבת לקדשו</b>: שמות כ, ח."],["306","3","<b>שמור את יום השבת</b>: דברים ה, יב."],["307","4","<b>דזכור ושמור בדיבור אחד נאמרו</b>: ר\"ה כז, א."],["308","5","<b>דשבת מיקדשי וקיימא</b>: ביצה יז, א."],["309","6","<b>ויברך אלקים את יום השבת</b>: ראה בראשית ב, ג."],["310","7","<b>וישראל הוא דקדשינהו לזמנים</b>: ברכות מט, א."],["311","8","<b>אלה מועדי ה' אשר תקראו אתם אתם אפי' שוגגין כו'</b>: ויקרא כג, ד ועוד. ר\"ה כה, ב."],["312","9","<b>ושמרתם את השבת כי קודש הוא</b>: שמות לא, יד."],["313","11","<b>ראשית חכ'</b>: משלי ד, ז."],["314","10","<b>ה' בחכ'</b>: משלי ג, יט."],["315","12","<b>וכל מקום שנאמר השמר פן ואל הוא מל\"ת</b>: עירובין צו, א. ובכ\"מ."],["316","13","<b>זה שמי כו' וזה זכרי כו' דשמי עם י\"ה גי' שס\"ה</b>: שמות ג, טז. זח\"א כד, א ועוד. ת\"ז בתחלתו. וראה בארוכה לקו\"ת פקודי ג, ב."],["317","14","<b>דאנכי ולא יהי' לך בדיבור א' נאמרו</b>: מכילתא יתרו כ, ח. שו\"ע אדה\"ז או\"ח תצד, ח."],["318","15","<b>דמפי הגבורה שמענו</b>: מכות כד, א."]]],[2101000074,"מהו ההפרש בין זכור לזכרי ביו\"ד שהרי כמו שתיבת זכרי עם ו\"ה עולה גי' רמ\"ח מ\"ע כך זכור עם י\"ה עולה גי' רמ\"ח מ\"ע (וא\"כ לכאורה מצות השבת לפעמים בו\"ה שהן שרש מ\"ע ולפעמים בי\"ה שהן שרש הל\"ת כמ\"ש זה שמי כו' ושמי עם י\"ה גי' שס\"ה וידוע דאותיו' י\"ה גבוהים מאותיו' ו\"ה גם א\"כ למה נאמר זכור ושמור בשבת מאחר דגם זכור שרשו בל\"ת שהן בי\"ה כו' וד\"ל).\n<b>אך</b> הנה תחלה י\"ל שרש ענין השבת מהו. דהנה כתיב וירא<sup data-n=\"319\">16</sup> אלקי' את כל אשר עשה והנה טוב מאד פי' את כל אשר עשה בוימ\"ב ע\"י צירופי אותיות דע\"מ כמו מאמר יהי אור יהי רקיע יקוו המים תדשא הארץ וכו' שהן בחי' גילוי אור האלקי שנתגלה מאין ליש עד\"מ אותיו' הדיבור באדם אך שאין דיבורו כדיבורינו ולא מחשבתו כמחשבתינו כמ\"ש כי<sup data-n=\"320\">17</sup> לא מחשבותי מחשבותיכם כו' כי אין לו אפי' דמות הגוף כמ\"ש כי<sup data-n=\"321\">18</sup> לא ראיתם כל תמונה כו' אבל מפני שבצלם אלקי' עשה את האדם ע\"כ נאמר מבשרי אחזה אלוה ונוכל להבין בדוגמא מדיבורינו ומחשבתינו בבחי' דיבור ומח' העליונה שהן בחי' אותיו' די' מאמרות כמ\"ש ויאמר אלקי' יהי אור וכיוצא והוא הנק' עלמין דאתגליי' כידוע להיותם באין להמשכה והתגלות מאין ליש ממש כמשל אותיות הדיבור באדם ובתוך צירופי אותיו' הללו מלובש ונעלם אותיות מחשבותיו ית' הנק' עלמין דאתכסיי' עד\"מ המח' באדם שהיא סתומה ונעלמה (והוא ההפרש בין מ\"ם סתומה למ\"ם פתוחה וכמ\"ש במ\"א שיש הפרש בין מחשבה שבדיבור להמח' בעצמה כו') והנה במח' זאת מלובש השכל והמדות כנראה בחוש שאדם חושב מה שנולד בלבו התפעלו' איזה מדה והתפעלו' של המדות נמשכים מן השכל שבמוח שמלובש בהן כידוע דחו\"ב נק' אב ואם להוליד המדות וכך למעלה בחי' מדות עליונו' דאצי' שהוא הנק' בחי' ז\"א דאצי' מתלבשים בתוך בחי' אותיו' המחשבה ודיבור העליון די' מאמרות הנ\"ל ובתוך המדות דאצי' מלובש בחי' חו\"ב דאצי' שנק' או\"א כידוע וז\"ש בראשי' ברא אלקי<sup data-n=\"322\">19</sup>ם ואיתא<sup data-n=\"323\">20</sup> בזוהר אבא אמר לאימא שנק' אלקים עילאה ובראשי' הוא בחי' החכ' כידוע ולזה אמרו דבמאמר<sup data-n=\"324\">21</sup> א' יכול להבראות כו' והוא מאמר דבראשי' הכוללם יחד כמשל המדות ומחשבה ודיבור שכוללם שכל שבחכ' וז\"ש כולם<sup data-n=\"325\">22</sup> בחכ' עשית וכידוע ומבואר במ\"א. ואמנם הנה לא כמו המדות באדם כאשר יתפעל בהן שעושין שינוי והתפעלו' בנפש עצמה כמו מדת החסד והרחמים שיתפעל על עני וכיוצא שתתפעל הנפש להשפיע החסד וכן בהיפוך במה\"ד לענוש לרשע ולצמצם השפע למי שאינו ראוי שתתפעל הנפש ג\"כ וכן בשאר המדות אבל למעלה א\"א לומר כן שהרי באא\"ס נאמר אני<sup data-n=\"326\">23</sup> הוי' לא שניתי כו' וא\"כ א\"א לומר שיקבל שינויים מהתפעלו' מדותיו אעפ\"י שנק' רחום וחנון כו' כי אא\"ס",[["319","16","<b>וירא אלקים את כל אשר עשה</b>: בראשית א, לא."],["320","17","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח."],["321","18","<b>כי לא ראיתם כל תמונה</b>: דברים ד, טו."],["322","19","<b>בראשית ברא אלקים</b>: בראשית א, א."],["323","20","<b>ואיתא בזוהר אבא אמר לאימא שנק' אלקים עילאה</b>: ראה זח\"א כב, א."],["324","21","<b>דבמאמר א' יכול להבראות</b>: אבות פ\"ה מ\"א. ובכ\"מ."],["325","22","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["326","23","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."]]],[2101000075,"הוא בתכלי' האח\"פ כו' כידוע וא\"כ גם מדותיו אינם הכרחיי' כמו מדת האדם שהרי אמר לאו<sup data-n=\"327\">24</sup> דאית לך צדק ידיע' כו' ולאו מכל אינון מדות כלל אלא רק לאחזאה כו' לאתנהגא בהון עלמין פי' רק בשביל הנהגות העולמות בי\"מ בדיבור מאין ליש כנ\"ל לזה נאצלו המדות להיות בחי' מקוריות המשפיעי' לעולמות כמו כדי שיהא מציאו' נברא מאין ליש בבחי' החסד כמו מחנה מיכאל או נשמת אברהם איש החסד וכיוצא לכך נאצל אור חסד עליון להיות מקור למקור למציאותם ועד\"ז כל פרטי המדות דאצי' ואם לא בשביל הבריאה הרי בחי' אא\"ס פשוט בתכלית ולאו דאית לי' מכל אינון מדות כלל ולא כמו המדות שבאדם שהן מציאות נבדלי' מן הנפש ע\"כ עושין שינוי בנפש כו' אבל מדות עליונות מיוחדים וכלולים בעצמו' המאציל ואין עושין בו שינוי כלל משום דאיהו<sup data-n=\"328\">25</sup> וחיוהי חד כו' בבחי' א\"ס דהיינו לאו דאית לי' צדק ידיע' כו' ולאו מכל אינון מדות כלל וכמ\"ש כי<sup data-n=\"329\">26</sup> לא אדם הוא כו' וכמ\"ש במ\"א באריכות וד\"ל.\n<b>והנה</b> בחי' חו\"ב דאצי' שמתלבשי' במדות והמדות מתלבשי' במח' ודיבור העליון כנ\"ל הכל הוא בחי' ירידה ממדריגה למדריגה שהרי עד\"מ באדם כאשר ישים שכלו להתבונן בדבר מה הנה זהו בחי' ירידה לגבי עצם כח שכלו ומכ\"ש מה שמן ההתבונו' יומשך במדות שבלב בחי' ירידה גדולה יותר ומכ\"ש למחו\"ד כו' וה\"ז כמו שיעשה אדם מלאכה בידיו כמו מלאכת הכתיבה שכח תנועת ידו מתפשטת בפעולה זאת וירידה היא לגבי עצמו' כחו כך בחי' אותיו' המח' והדיבור שמלובש בהן המדות והשכל ה\"ז רק בחי' התפשטות כח השכל והמדות מעצמותם ממש וה\"ז בחי' ירידה גדולה להם כמו המלאכה ממש ולכך נאמר וירא אלקי' את כל אשר עשה גבי י' מאמרות אעפ\"י שאינן אלא בחי' דיבור כי בתוכן ירד אור החכ' והמדות בבחי' התפשטו' וה\"ז נחשב בחי' עשי' לגבי עצמותם וכמ\"ש כולם בחכ' עשית כו' וכנ\"ל וז\"ש ששת<sup data-n=\"330\">27</sup> ימים עשה ה' כו' פי' וי\"ו ימים הללו הן בחי' ו\"ק דז\"א דאצי' כנ\"ל והם עשו לשמים כו' מפני שמהן מקור הי\"מ במחו\"ד שנק' עלמין דאתכסיין ועלמין דאתגליי' כנ\"ל וכמ\"ש לאחזאה לאתנהגא בהון עלמין כו' וכנ\"ל וד\"ל. אך הנה כל בחי' ירידה זאת הייתה בוימ\"ב אבל אח\"כ נאמר וירא<sup data-n=\"331\">28</sup> אלקי' את כל אשר עשה והנה טוב מאד ויכולו השמים כו' פי' אחר שכבר גמר בחי' ירידה הנ\"ל שנמשלה למלאכה ממש ראה שכל אשר עשה בי\"מ טוב מאד שהוא בחי' העלאת התענוג מכל אשר עשה כו' ואז נאמר ויכולו השמים כו' ויכל אלקים כו' לשון תענוג כמו כלתה<sup data-n=\"332\">29</sup> נפשי כו' והוא הנק' שבת דמעלי שבתא שהוא בחי' או\"ח כמ\"ש כי בו שבת מכל מלאכתו עד\"מ אדם השובת ונח מפעולה ומלאכה גשמי' כך שביתתו",[["327","24","<b>לאו דאית לך צדק ידיעא</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."],["328","25","<b>דאיהו וחיוהי חד כו'</b>: ת\"ז בהקדמה לפני ד\"ה קום יחזקאל."],["329","26","<b>כי לא אדם הוא</b>: שמואל-א טו, כט."],["330","27","<b>ששת ימים עשה ה'</b>: שמות כ, יא. ועוד. וראה הנסמן בסה\"מ תש\"ח ע' 272."],["331","28","<b>וירא אלקי' את כל אשר עשה. . ויכולו</b>: בראשית א, לא ואילך. ובהבא להלן ראה ג\"כ סה\"מ תקס\"ח ע' קנג. ביאוה\"ז להצ\"צ כרך ב' ע' תתיא. לקו\"ת בשלח ב, ב ואילך. ובכ\"מ."],["332","29","<b>כלתה נפשי</b>: תהלים פד, ג."]]],[2101000076,"מטרדת השכל וירידתו במדות ומחו\"ד שהשכל והמדות חוזרים אל עצמותם ונק' נייחא דרוחא כו' וכמ\"כ למעלה כתיב כי בו שבת כו' דהיינו שעלה בחי' הארת החכ' לעצמיותו וכמ\"כ המדות כו' וזהו שרש ענין בחי' השבת למעלה שנק'<sup data-n=\"333\">30</sup> נייחא דרוחא כמ\"ש כי<sup data-n=\"334\">31</sup> בו שבת וינפש כו' וע\"כ הדיבור<sup data-n=\"335\">32</sup> אסור בשבת כמ\"ש ממצוא חפצך ודבר דבר כידוע לפי שגם בבחי' דיבור העליון יש בחי' שביתה כי בשבת הוא עליי' חכ' שבדיבור לגבי עצמות אור אבא שנק' מלכא עילאה כו' ואז לאו<sup data-n=\"336\">33</sup> אורחא דמלכא לאשתעי במילי' דהדיוטא שהן י' מאמרות יהי אור תוצא הארץ וכיוצא דגם שיש בהן בחי' חכ' ג\"כ כמ\"ש כולם בחכ' עשית אבל הרי כלא חשיבי לגבי עצמות החכ' כשמדבר דברי ח\"ע עד\"מ המלך שמדבר דברי חכמתו העצמי' שהן דברים עליונים הרבה מדברים שמדבר להנהגות המדינה הגם שהמה ג\"כ עפ\"י החכ' כו' (וגם בד\"ת בקושי<sup data-n=\"337\">34</sup> התירו כמ\"ש במ\"א וד\"ל).\n<b>ובכ\"ז</b> יובן מה שלא נזכר שם הוי' בכל וימ\"ב אלא שם אלקים דוקא כמו ויאמר אלקים כו' עד שגמר כל מלאכתו וקידש את השבת כתיב אלה<sup data-n=\"338\">35</sup> תולדו' השמים כו' ביום עשות ה' אלקי' כו' דהיינו אחר ויכולו שהי' בחי' או\"ח הנק' נייחא דרוחא כנ\"ל לפי ששם אלקי' הוא בחי' נרתק ומגן להסתיר ולהעלים אור דשם הוי' (שהוא בחי' חו\"ב שמלובשי' במדות דאצי' כנ\"ל והן ד' אותיו' דהוי' י\"ה חו\"ב ו\"ה מדות ודיבור כידוע) והיינו כל וימ\"ב שנבראו העולמות מאין ליש מבחי' דיבור שהוא ע\"י צמצום דשם אלקים דוקא אבל שם הוי' הוא עצמו' אור א\"ס שמיוחד עם מדותיו כמ\"ש דאיהו וחיוהי חד כו' כנ\"ל וע\"כ נאמר אני הוי' לא שניתי כו' כנ\"ל לא נתגלה בוימ\"ב רק אחר שגמר המלאכה והי' בחי' נייחא דרוחא שהוא בחי' עצמו' המדות וחו\"ב כמו שהן מיוחדי' בעצמו' המאציל כנ\"ל אז נזכר שם הוי' (ומ\"ש ביום עשות ה' אלקים כו' לפי שבהעלם עכ\"פ הי' מלובש שם הוי' באלקי' כל וימ\"ב רק שבשבת נתגלה שם הוי' וכמ\"ש שבת להוי' כו' וד\"ל).\n<b>והנה</b> כתיב אשר<sup data-n=\"339\">36</sup> ברא אלקי' לעשות וארז\"ל לעשות<sup data-n=\"340\">37</sup> לתקן כו' וכמ\"ש באדה\"ר<sup data-n=\"341\">38</sup> שהניחו בג\"ע לעבדה ולשמרה וארז\"ל לעבדה<sup data-n=\"342\">39</sup> זו רמ\"ח מ\"ע ולשמרה שס\"ה ל\"ת כו' וכן ע\"י בחי' התשובה יש בחי' תיקון לי' מאמרות שבכל ששת יומין דחול כי כל שבת הוא שבת בראשי' מאחר שמחדש בטובו בכל יום כו' כידוע והענין",[["333","30","<b>שנק' נייחא דרוחא</b>: ראה ת\"ז תי' וא\"ו (כא, א). תי' כ\"א (נד, ב). זח\"א ע, א."],["334","31","<b>כי בו שבת וינפש</b>: ראה בראשית ב, ג. שמות לא, יז."],["335","32","<b>הדיבור אסור בשבת כמ\"ש ממצוא חפצך ודבר דבר</b>: שבת קיג, א ואילך. ישעי' נח, יג."],["336","33","<b>לאו אורחא דמלכא לאשתעי במילין דהדיוטא</b>: ראה זח\"ג קמט, ב."],["337","34","<b>בקושי התירו</b>: ראה ירושלמי שבת פט\"ו ה\"ג. ובסוף ס' היראה לר\"י. תו\"א תשא קיג, א. לקו\"ת צו יא, ד. ובכ\"מ."],["338","35","<b>אלה תולדות השמים</b>: בראשית ב, ד."],["339","36","<b>אשר ברא אלקים לעשות</b>: בראשית ב, ג."],["340","37","<b>לעשות לתקן</b>: ראה מפרשי ב\"ר פי\"א, ו."],["341","38","<b>באדה\"ר שהניחו בג\"ע לעבדה ולשמרה</b>: ראה בראשית ב, טו."],["342","39","<b>לעבדה זו רמ\"ח מ\"ע ולשמרה שס\"ה ל\"ת</b>: ראה זח\"א כז, א. זח\"ב קסה, ב."]]],[2101000077,"הוא כי הנה ארז\"ל במקום<sup data-n=\"343\">40</sup> שבע\"ת עומדין כו' לפי שבע\"ת מבטלים א\"ע בבחי' ביטול רצון מלמטה למעלה בכל כחם לאהפכא<sup data-n=\"344\">41</sup> חשוכא לנהורא ומרירו למיתקא כו' שזה הי' כונת המאציל בתחלת המח' שבחכ' כי סוף מעשה עלה במ\"ת כו' וע\"כ מזה ג\"כ יבא בחי' אור חוזר מכל וימ\"ב להיות קבלת התענוג למעלה מכל אשר עשה כמ\"ש וירא אלקים את כל אשר עשה והנה טוב מאד ומאד הוא בלי גבול ושיעור וכמארז\"ל טוב<sup data-n=\"345\">42</sup> זה מלאך חיים מאד זה מ\"ה כו' וע\"כ דוקא בהיפוך חשוכא לנהורא כו' ע\"י בע\"ת יהי' למעלה ג\"כ בחי' טוב מאד שהוא העונג הבלתי מוגבל כו' וד\"ל וכמ\"כ ע\"י מעשה המצות בדברים גשמיי' דדצ\"ח דנוגה שהוא ג\"כ לאהפכא חשוכא לנהורא בסור מרע וע\"ט כו' כידוע וז\"ש אשר ברא אלקים לעשות לתקן כי ישראל עושין את השבת ע\"י מעשה המצות שהן עושין כל ו' ימות החול כו'.\n<b>וביאור</b> הדברי' הנה כתיב חכמות<sup data-n=\"346\">43</sup> בחוץ תרונה ואמרו<sup data-n=\"347\">44</sup> בזוהר חכמות תרי ח\"ע וח\"ת וביאור הענין הנה בחי' ח\"ע הוא בחי' עצמות חכמתו ית' שנק' חכים<sup data-n=\"348\">45</sup> ולא בחכ' ידיעה (ויש בזה ב' מדריגות הא' בחי' חכ' דאצי' שנק' ג\"כ ח\"ע לגבי התחתונים והב' בחי' ח\"ס דא\"א והוא ולא בחכ' ידיע' שנק' תעלומות חכ' כידוע) והנה ארז\"ל נובלות<sup data-n=\"349\">46</sup> חש\"מ תורה פי' חכמה של מעלה הוא מ\"ש חכים ולא בחכ' ידיע' הנ\"ל ובחי' הנובלות הוא בחי' אור ושפע אור החכ' הנמשך למטה מטה בבחי' נובלות כדי לברר בירורי' דנוגה כי בחכ'<sup data-n=\"350\">47</sup> אתברירו כידוע והיינו בחי' חכ' שבתורה שמתלבשת בדברי' גשמיי' להבדיל בין טמא לטהור וכיוצא בזה בכל מצות ל\"ת וכמ\"כ גם במעשה המצות עשה הרי נתלבשה החכ' במעשה גשמי' כמו במצות ציצית בצמר גשמי דטלית כו' ולמעלה הטלית הוא בחי' או\"מ וכמ\"ש לבושי'<sup data-n=\"351\">48</sup> כתלג חוור כו' שהוא בחי' סוכ\"ע הכללי והחוטין הן ל\"ב נ\"ח כו' וכמ\"ש במ\"א בפ' ציצית ועד\"ז בשאר המצות כמו אבני האפוד והחושן תרשיש שהם וישפה כו' אבנים גשמיי' ונחקק בהן שמות י\"ב השבטי' וכאשר ישא אותם אהרן כתיב ונשא<sup data-n=\"352\">49</sup> אותם אהרן לפני ה' כו' לזכרון כו' ולמעלה רומזים לבחי' אורות עליונים שעי\"ז בחי' אהרן כה\"ר דלעילא ימשיך מקור החסדים מלפני עצמות המאציל כו' ולמטה נתלבשה חכ' זו באבנים גשמייי' ובמעשה גשמי' דחשן ואפוד וכה\"ג יובן בכל מעשה המצות וע\"כ נק' בחי' חכ' זו שנתלבשה למטה במעשה המצות בשם חכ' תתאה והוא בחי' חכ' שבמל' דאצי' שמתלבשת בעולם הנפרד לאהפכא חשוכא לנהורא כו' שהוא ענין",[["343","40","<b>במקום שבע\"ת עומדין</b>: ראה ברכות לד, ב והערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ט ע' 183. לקו\"ש ח\"ד ע' 361."],["344","41","<b>לאהפכא חשוכא לנהורא ומרירו למיתקא</b>: ראה זח\"א ד, א."],["345","42","<b>טוב זה מלאך חיים מאד זה מ\"ה</b>: זח\"א יד, א. וראה ב\"ר ט, ה. ובכ\"מ."],["346","43","<b>חכמות בחוץ תרונה</b>: משלי א, כ."],["347","44","<b>ואמרו בזוהר חכמות תרי</b>: זח\"א קמא, ב."],["348","45","<b>חכים ולא בחכ' ידיעא</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."],["349","46","<b>נובלות חש\"מ תורה</b>: ב\"ר פי\"ז, ה."],["350","47","<b>בחכ' אתברירו</b>: ראה זח\"ב רנד. ב. ע\"ח שי\"ח פ\"ה ועוד. מבו\"ש ש\"ה ח\"א פ\"ב. אגה\"ק סכ\"ח. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 206."],["351","48","<b>לבושי' כתלג חוור</b>: דניאל ז, ט."],["352","49","<b>ונשא אותם אהרן לפני ה'</b>: שמות כח, כט."]]],[2101000078,"בירורי' והעלאות דנוגה מדברים גשמיי' והוא מ\"ש חכמות בחוץ תרונה בחוץ דוקא דהיינו בבחי' נוגה דעשי' שנק' חוץ כמ\"ש אמצאך<sup data-n=\"353\">50</sup> בחוץ אשקך כו' והיינו בדברי' גשמי' דמעשה המצות בין בסו\"מ דל\"ת בין בוע\"ט דמ\"ע (ומ\"ש חכמות שתים לפי שח\"ע יורדת בהתלבשות בח\"ת להתלבש במצות מאחר שנק' נובלות חש\"מ וע\"כ אמר דשתי החכמות בחוץ תרונה כו' וד\"ל). והנה כתיב ראשית<sup data-n=\"354\">51</sup> חכ' כו' פי' ראשית בתי\"ו מורה על בחי' נוק' כי ראש הוא לשון דכר וראשי' לשון נוק' והיינו מפני שהחכ' נק' בחי' מקבל לגבי עצמיות המאציל וכמ\"ש והחכ'<sup data-n=\"355\">52</sup> מאין תמצא פי' מאין והעלם עצמות המאציל נמצאת החכ' מאין ליש בדרך<sup data-n=\"356\">53</sup> עילה ועלול ויובן זה עד\"מ ממה שאנו רואים שכאשר ישכיל אדם ויחדש איזה שכל וסברא חדשה הנה יתענג בנפשו מאד עד שהוא מלא תענוג ושמחה כמו שמצינו בר'<sup data-n=\"357\">54</sup> אבהו שצהבו פניו מפני שמצא תוספת' חדתא כו' והנה מזה אנו רואים שבחי' העונג שבנפש הוא למעלה מבחי' שכל זה שחידש כי העונג שבנפש הוא מקור מוצא להשכלות השכליות וכידוע דיסוד המים הרוחניי' שבמוח ששם משכן העונג הזה הוא מקור כח המשכיל המחדש חידושי חכ' מאין ליש כו' וכמ\"ש במ\"א באריכות וד\"ל.\n<b>וככה</b> יובן למשכיל למעלה בבחי' ח\"ע שנאמר בה והחכ' מאין כו' שלזה הטעם היא בחי' מקבל להיותה נמשכת מבחי' עונג העליון שלמעלה מן החכ' כמובן ממשל הנ\"ל (והוא בחי' גבורה דע\"י שמתלבש בח\"ס שנק' משכיל ואז נק' מעיין דחכ' המתגבר להמציא חדשות כמ\"ש במ\"א) וזהו פי' ראשית חכ' שהחכ' נק' ראשית בחי' נוק' בחי' מקבל ובחי' עונג העליון מקורה נק' ראש בחי' דכר המשפיע לחכ' מאין ליש וכמ\"ש והחכ' מאין תמצא ואותיות ראש הוא אותיו' אשר שהוא ג\"כ לשון תענוג כמו באשרי<sup data-n=\"358\">55</sup> כו' (וזהו אהי' אשר אהי'<sup data-n=\"359\">56</sup> כי שם אהי' בכתר שהוא בחי' עונג העליון שנק' עתיקא כידוע) וזהו ענין ברכות המצות בא\"י אשר קדשנו כו' פי' אתה ה' אלקינו הוא בחי' יחו\"ע דחו\"ב דאצי' מלך העולם הוא בחי' יחו\"ת דמל' דאצי' ובכולם נמשך מבחי' אשר שהוא בחי' העונג העליון שבמצותיו שנק' רצה\"ע כידוע וזהו אשר קדשנו במצותיו כו' וד\"ל.\n<b>ומעתה</b> הנה יובן מ\"ש אשר ברא אלקים לעשות לתקן שע\"י התיקון בו' ימות החול במעשה המצות עושין ישראל ליום השבת כנ\"ל כי הנה שרש בחי' השבת הוא בבחי' החכ' כנ\"ל בענין השביתה דשבת שהוא בבחי' החכ' ולזה הטעם הדיבור אסור בשבת כי סיג לחכ' שתיקה שהשתיקה מורה על היות השכל טרוד בפנימי' חכ' וע\"כ אמרו סייג<sup data-n=\"360\">57</sup> לחכ' שתיקה כו' וז\"ש ממצוא חפצך ודבר דבר כו'",[["353","50","<b>אמצאך בחוץ אשקך</b>: שה\"ש ח, א."],["354","51","<b>ראשית חכ'</b>: תהלים קיא, י."],["355","52","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["356","53","<b>בדרך עלה ועלול</b>: אוצ\"ל: שלא בדרך עילה ועלול."],["357","54","<b>בר' אבהו שצהבו פניו</b>: ראה ירושלמי שבת פ\"ח ה\"א."],["358","55","<b>באשרי</b>: בראשית ל, יג."],["359","56","<b>אהי' אשר אהי'</b>: שמות ג, יד. וראה ג\"כ ת\"ז תל\"ט. פרדס ערך אשר. אוה\"ת דרושים ליוהכ\"פ ע' א'תקצד, ובכ\"מ."],["360","57","<b>סייג לחכ' שתיקה</b>: אבות פ\"ג מי\"ג."]]],[2101000079,"כנ\"ל וכ\"ז מפני שהשבת שרשו בבחי' פנימית אור החכ' כמ\"ש וביום<sup data-n=\"361\">58</sup> השביעי קודש לה' וכל קדש הוא בחכ' ואמנם הנה ע\"י מעשה המצות בימות החול הרי ממשיכין בחי' עונג העליון בחכ' כנ\"ל ואז נק' החכ' עדן לפי שמקבלת מבחי' עונג העליון כו' וכמ\"ש ונהר<sup data-n=\"362\">59</sup> יוצא מעדן להשקות את הגן ולשון עדן הוא ענין קבלת עונג והיינו מה שהחכ' מקבלת עונג מעונג העליון כנ\"ל בפי' אשר קדשנו במצותיו שזהו ע\"י המצות דוקא ולכך ארז\"ל דיפה<sup data-n=\"363\">60</sup> שעה אחת בתשובה ומע\"ט בעוה\"ז מכל חיי עוה\"ב כי חיי העוה\"ב הוא מה שהנשמות נהנין מזיו השכינה בעדן עליון דחה\"ע ועדן התחתון דח\"ת אבל הרי ע\"י מעשה המצות נמשך בחי' עונג העליון עצמו שלמעלה מבחי' העונג שבחכ' שנק' עדן שאינו אלא עונג פרטי והארה בעלמא מעצמו' העונג העליון הנק'<sup data-n=\"364\">61</sup> שעשוע המלך בעצמותו כו' וד\"ל ולפ\"ז יובן ג\"כ דמעשה המצות בחול שממשיכין לבחי' העונג העליון בעצמו הנה מזה יבא בחי' המשכת עונג גם לבחי' חכ' שהוא בחי' השבת כנ\"ל וזהו שאמר לעשות לתקן שע\"י תיקון המצות בימות החול נעשה יום השבת להיות גם בו המשכת עונג העליון כמ\"ש וקראת<sup data-n=\"365\">62</sup> לשבת עונג כו' וד\"ל.\n<b>וזהו</b> זכור את יום השבת לקדשו כו' זכור עם י\"ה עולה רמ\"ח מ\"ע ואע\"ג דשבת מיקדשא וקיימא מוימ\"ב כמ\"ש ויקדש אותו ולא תלי' בישראל מ\"מ ע\"י מצות שישראל עושין בחול עושין ליום השבת כנ\"ל בבחי' המשכת העונג העליון וז\"ש לקדשו בקדושת העונג העליון העצמי (ומ\"ש ויקדש אותו היינו רק בהארת עונג פרטי כמו שנק' עדן כו'). ולהבין ההפרש בין זכור לזכרי כנ\"ל וגם ענין זכור ושמור בדיבור א' נאמרו כו' כנ\"ל הנה יש להקדים עוד מ\"ש ששת<sup data-n=\"366\">63</sup> ימים תעבוד כו' פי' תעבוד כל עבודה הוא בחי' תיקון כמו עורות<sup data-n=\"367\">64</sup> עבודי' כידוע וגם כאן בוי\"ו ימוה\"ח העיקר הוא בחי' התיקון לתקן ולברר בירורי נוגה ע\"י המצות מעשיו' שנעשי' בדברי' גשמיי' דנוגה וכל ענין התפלה בחול אינה אלא בחי' העלאה ובירור מכל אשר נפל בנוגה כמו בעסקו במו\"מ ביגיעת נה\"ב כו' שיעלה הכל לה' באמצעות התפלה שהיא בחי' העלאה ע\"י התפעלות האהבה שבלב ונק' התפעלות אהבה זו להפוך חשוכא לנהורא כו' בשם עבודה כמ\"ש<sup data-n=\"368\">65</sup> בזהר לית פולחנא כפולחנא דרחימותא כו' וז\"ש ששת ימים תעבוד בפולחנא דרחימותא להעלות הכל מבירורי נוגה מלמטה למעלה וכל התפלות דחול עולין בשבת וזהו זכור עם י\"ה להעלות מלמטה למעלה ליכלל בי\"ה אבל בשבת הוא בחי' המשכה דזכרי עם ו\"ה כו'.",[["361","58","<b>וביום השביעי קודש לה'</b>: ראה שמות לה, ב."],["362","59","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["363","60","<b>דיפה שעה אחת בתשובה ומעש\"ט בעוה\"ז</b>: אבות פ\"ד מי\"ז."],["364","61","<b>הנק' שעשוע המלך בעצמותו</b>: ראה עמק המלך ש\"א. לקו\"ת שה\"ש כז, א."],["365","62","<b>וקראת לשבת עונג</b>: ישעי' נח, יג."],["366","63","<b>ששת ימים תעבוד</b>: שמות כ, ט. ועוד."],["367","64","<b>עורות עבודי'</b>: שבת מט, ב. ובכ\"מ. וראה בהמ\"מ לעיל ע' כג."],["368","65","<b>כמ\"ש בזוהר לית פולחנא כפולחנא דרחימותא</b>: זח\"ג רסז, א."]]],[2101000080,"<b>וביאור</b> הדברים הנה ארז\"ל ע\"פ מה ה' שואל מעמך א\"ת מה<sup data-n=\"369\">66</sup> אלא מאה הן מאה ברכות שחייב אדם לברך בכל יום כו' והענין הוא כי בחי' ההמשכה שנמשך מבחי' סוכ\"ע לבחי' ממכ\"ע נק' בשם ברכה כי הוא בחי' הגילוי מן ההעלם וידוע בע\"ח דבחי' ע\"ס דאצי' כאו\"א כלול מי\"ס שהן מספר מאה ע\"כ הן מספר מאה ברכות שחייב אדם לברך ולהמשיך מבחי' סובב לממלא וזהו א\"ת מ\"ה שהוא בחי' ממכ\"ע אלא מאה פי' כי בחי' ממכ\"ע הוא בחי' מל' דאצי' שנק' אחת כמ\"ש אחת<sup data-n=\"370\">67</sup> היא יונתי כו' ומספר אחת לגבי ע\"ס דז\"א דאצי' שכלולים כאו\"א מי' שנק' ק' ברכות ה\"ז רק חלק א' ממאה שנק' תרומות מעשר דהיינו מעשר מן המעשר וז\"ש תרומות<sup data-n=\"371\">68</sup> הוי' שהוא מעשר מן המעשר (כי<sup data-n=\"372\">69</sup> בחי' הוי' דז\"א כולל מאה ברכות כנ\"ל ומבחי' המלכיות דז\"א נבנה בנין הנוק' כמ\"ש בע\"ח דמבחי' מל' שבחסד דז\"א נבנה בחי' חסד שבמל' ועד\"ז כל בנין ע\"ס דנוק' וא\"כ בחי' ע\"ס דמל' היא חלק העשירית דז\"א וכמ\"ש שנק'<sup data-n=\"373\">70</sup> עשיראה דכולהו כו' ובבי\"ע אין ההמשכה מבחי' מל' רק חלק העשירית שהוא בחי' מל' שבמל' וזה החלק נק' מעשר מן המעשר לגבי ז\"א וז\"ש תרומות הוי' וכמ\"ש<sup data-n=\"374\">71</sup> בזהר פ' תרומה בפי' ויקחו לי תרומה מאי תרומה ארמותא כו' והיינו תר\"ו מ\"ה לרומם לבחי' מה שהוא בחי' המל' אך א\"ת מ\"ה אלא מאה ברכות דז\"א וכתיב העשירי<sup data-n=\"375\">72</sup> יהי' קודש לה' כי בבחי' ההעלאה מלמטה למעלה שנק' תרומה ארמותא כו' הרי בחי' המל' נק' כתר כידוע שבבחי' א\"ח הכתר הוא מל' כו' ולכך נק' המל' אחת בלשון חשיבות המעלה על כל ס' מלכות ופ' פלגשים שכולן בבחי' ז\"א כידוע דששים מלכות היינו בחי' ו\"ק דז\"א שכלולים כאו\"א מי' כו' אך אחת היא יונתי כו' וכמ\"ש רבות<sup data-n=\"376\">73</sup> בנות עשו חיל כו' ואת עלית על כולנה כו' ולכך נק' בשם תרומת הוי' כו' (וענין<sup data-n=\"377\">74</sup> תרומה גדולה של ישראל הוא תרי ממאה להיות כי מת\"ת דאימא כתר א' לזו\"נ ויש נ' שערים בבינה ובחי' תרומה א' מחמשים לזו\"נ הוא תרי ממאה כי ה\"ח וה\"ג דבינה הן מאה שערים כמ\"ש ביצחק וימצא<sup data-n=\"378\">75</sup> מאה שערי' כו' אבל תרומת מעשר דלוי לכהן הוא בבחי' א\"ח דמל' כו' ע\"כ הוא חלק א' ממאה אך א\"ת מה אלא מאה וד\"ל).\n<b>והנה</b> וי\"ו יומין דחול הוא בחי' ההעלאה מלמטה שנק' תרומת מעשר כו' והיינו פי' זכור עם י\"ה שעולה רמ\"ח בבחי' ההעלאה ליכלל בי\"ה דשם הוי' כנ\"ל אבל תכלית הכונה בהעלאה זאת הוא בשביל המשכה אח\"כ לברך ק' ברכות דע\"ס דאצי'",[["369","66","<b>מה ה' שואל מעמך א\"ת מה אלא מאה</b>: ראה דברים י, יב. מנחות מג, ב. וראה בהמ\"מ לעיל ע' לא."],["370","67","<b>אחת היא יונתי</b>: שה\"ש ו, ח."],["371","68","<b>תרומות הוי'</b>: ראה קרח יח, כו. ועוד. ובכ\"מ."],["372","69","<b>(כי</b>: בהכת\"י חסר סיום המוסגר."],["373","70","<b>שנק' עשיראה דכולהו</b>: ראה זח\"ג רנג, ב. ובכ\"מ."],["374","71","<b>וכמ\"ש בזוהר פ' תרומה</b>: ראה זח\"ב קמז, א."],["375","72","<b>העשירי יהי' קודש לה'</b>: ויקרא כז, לב."],["376","73","<b>רבות בנות עשו חיל</b>: משלי לא, כט."],["377","74","<b>וענין תרומה גדולה של ישראל הוא תרי ממאה</b>: ראה תרומות פ\"ד מ\"ג. זח\"ב ר, א. זח\"ג קפח, ב. ובכ\"מ."],["378","75","<b>וימצא מאה שערים</b>: בראשית כו, יב."]]],[2101000081,"ולהמשיכן למטה בבי\"ע וכמ\"ש א\"ת מה אלא מאה כנ\"ל והיינו בחי' זכרי עם ו\"ה שעולה רמ\"ח ג\"כ אבל הוא בבחי' רמ\"ח אברי' דמלכא דז\"א ונמשכין למטה והוא ענין וי\"ו שנמשך לה\"א שהוא בחי' המשכה מלמעלה למטה כידוע (אבל זכרי עם י\"ה עולה רנ\"ב והן רנ\"ב<sup data-n=\"379\">76</sup> אברי' דנוק' דהיינו צירי' ודלתות כו' שהן ד' אברי' הנוספי' על רמ\"ח שנבנו מבחי' או\"א שבאותיו' י\"ה וכמ\"ש ויבן<sup data-n=\"380\">77</sup> ה' אלקים את הצלע וכתיב באר<sup data-n=\"381\">78</sup> חפרוהו שרים כו' אך זכרי עם ו\"ה הוא בשביל המשכת בנין הנוק' באו\"כ להיות בבחי' פרצוף שלם דומה לקומת ז\"א כו' וד\"ל וההפרש בין זכור לזכרי היינו שהוי\"ו דזכור הוא בחי' ו\"ק דמל' שמקבלת מז\"א אבל זכרי ביו\"ד היינו י\"ס דאבא הכלולים בז\"א וכמשמעות הפשוט זה שמי לעלם וזה זכרי לדור ודור שהוא בחי' הזמן שבנוק' וד\"ל) וזהו ענין המצות שהן רמ\"ח והוא בבחי' ו\"ה וגם זהו ענין המשכות התורה דאוריי' מח\"ע נפקת והוא יו\"ד דזכרי ונמשך למטה בדיבור העליון וכמ\"ש ודברי<sup data-n=\"382\">79</sup> אשר שמתי בפיך כו' וכמ\"ש על שמאי והלל דאלו<sup data-n=\"383\">80</sup> ואלו דברי אלקים חיים כו' והיינו ו\"ה קול ודיבור דתורה וזהו ג\"כ שרש ענין השבת שהוא בחי' החכמה שהוא יו\"ד דזכרי ונק' זכרון למע\"ב כו'. וזהו זכור את יום השבת לקדשו, פי' (חסר<sup data-n=\"384\">81</sup>).",[["379","76","<b>רנ\"ב אברי' דנוק'</b>: ראה בכורות מה, א."],["380","77","<b>ויבן ה\"א את הצלע</b>: בראשית ב, כב. וראה זח\"א כח, א."],["381","78","<b>באר חפרוה שרים</b>: ראה במדבר כא, יח."],["382","79","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["383","80","<b>דאלו ואלו דברי אלקים חיים</b>: עירובין יג, ב."],["384","81","<b>(חסר)</b>: כן רשום בהכת\"י."]]],[2101000082,"<h3>קול דודי הנה זה בא</h3>\n<b>בעזר\"ה פ' ויקהל</b>\n<b>קול</b><sup data-n=\"385\">1</sup> דודי הנה זה בא מדלג על ההרים מקפץ על הגבעות וכו' דומה דודי לצבי<sup data-n=\"386\">2</sup> כו' וי\"ל שינוי לשון שבהרים נאמר לשון דילוג ובגבעות נאמר לשון קפיצה. והנה הענין הוא דבחי' דילוג זה קאי על יצי\"מ דכתיב ופסח<sup data-n=\"387\">3</sup> ה' על הפתח דפסיחה זאת ג\"כ דילוג הייתה והיינו כענין שארז\"ל<sup data-n=\"388\">4</sup> דזמן השעבוד גלות זה של מצרים הי' צריך להיות ד' מאות שנה אך דילג ה' והוציאם לזמן רד\"ו שנה כו'. אך י\"ל שינוי הלשון דבכאן אמר מדלג על ההרים מקפץ על הגבעות וכאן אמר ופסח ה' על",[["385","1","<b>קול דודי</b>: נדפס בשינויים בלקו\"ת שה\"ש יד, ב. קיצורים והגהות נדפסו באוה\"ת דרושים לפסח ע' תשסח ואילך. אוה\"ת שה\"ש כרך א' ע' רמה-רנח. כרך ג' ע' תתפד ואילך. לכמה מעניני המאמר ראה: בסה\"מ תרכ\"ט ע' קלה ואילך. סה\"מ תרל\"ב ח\"א ע' כ ואילך וע' כח ואילך. סה\"מ תרס\"ג ח\"ב ע' קנ ואילך. סה\"מ תש\"ח ע' 153 ואילך. פלח הרמון שה\"ש ע' יט-מא."],["386","2","<b>קול דודי הנה זה. . דומה דודי לצבי</b>: שה\"ש ב, ח-ט."],["387","3","<b>ופסח ה' על הפתח</b>: שמות יב, כג."],["388","4","<b>שארז\"ל דזמן השעבוד. . רד\"ו שנה</b>: שהש\"ר עה\"פ קול דודי."]]],[2101000083,"הפתח ולכאורה לא יש שייכות דליגה על ההרים והגבעות לדילוג ופסיחה על הפתח. אך הנה י\"ל עוד מה שאנו אומרים בהגדה מצה זו שאנו אוכלים על שום מה ע\"ש שלא הספיק בצקת של אבותינו להחמיץ עד שנגלה עליהם ממ\"ה הקב\"ה וגאלם כו', ולכאורה יש כאן קושי' גדולה וחזקה דהא מצות אכילת מצה בלילה הראשון שהיא חובה היינו משום שנאמר על<sup data-n=\"389\">5</sup> מצות ומרורי' יאכלוהו והוא חיוב אכילת מצה עם הקרבן פסח שהקריבו כידוע ומה שנאמר ויאפו<sup data-n=\"390\">6</sup> את הבצק אשר הוציאו ממצרים עוגות מצות כי לא חמץ כי גורשו ממצרים כו' דהיינו מ\"ש לא הספיק בצקת של אבותינו להחמיץ עד שנגלה עליהם הקב\"ה וגאלם כו' הי' זה אחר חצות הלילה שכבר אכלו הפסח עם מצות ומרורים קודם חצות ובצק זה שהוציאו עמהם הוא מצה אחרת שלשו אחר חצות ולא הספיק להחמיץ כי גורשו ממצרים ואפו אותה בדרך וכמ\"ש וישא<sup data-n=\"391\">7</sup> העם את בצקו טרם יחמץ כו' צרורות בשמלותם על כתפם (ומכאן יש ללמוד דבצק שאינו עוסק ביד בטלטול אלא מונח בלי טלטול אינו בא לידי חימוץ גם יותר משיעור מיל שהרי הלכו יותר משיעור מיל בבצק שצרור בשמלותם על כתפם) וא\"כ יש להפליא מאד על מה שאנו אומרים מצה זו שאנו אוכלים ע\"ש שלא הספיק בצקת כו' הרי מצה זו שאנו אוכלים קודם חצות היא לשם חובה לאכול המצות עם הפסח ואין זו מצה שלא הספיק בצקת כו' שהיא הייתה נאכלת בדרך אחר חצות כנ\"ל, וא\"א לומר דמצה אחת היא שהיו צריכים לאכול עם הפסח אך כי גורשו ממצרים כו' ולא הספיק להחמיץ כו' ואפוה בדרך ואכלוה עם הפסח דזה אינו דהא ידוע דאכילת<sup data-n=\"392\">8</sup> הפסח אינו אלא עד חצות לילה בלבד.\n<b>אך</b><sup data-n=\"393\">9</sup> הנה האמת הוא דשני מיני מצות<sup data-n=\"394\">10</sup> היו הא' מצה שאכלו קודם חצות עם הפסח לשם מצוה ומצה שני' עשו אחר חצות לצידה לדרך ולא הספיק להחמיץ עד שנגלה עליהם וגאלם וכמ\"ש ויאפו את הבצק כו' וכדלעיל אך אעפ\"כ יכולים אנחנו לומר מצה זו שאנו אוכלים הוא ע\"ש שלא הספיק בצקת כו' אעפ\"י שמצה זו שאנו אוכלי' היא לשם מצוה כמ\"ש על מצות כו' בערב תאכלו מצות כו' לפי שמצה זו שלנו יש בה אותה המדריגה שהי' במצה שלהם שלא הספיק להחמיץ כו' כי הנה יש ב'<sup data-n=\"395\">11</sup> מיני מצה הא' מצה שצריכה שימור מן החמץ וכמ\"ש ושמרתם את המצות כו' כידוע והב' שאינה צריכה שימור מצה שנילושה ביין ושמן ודבש הנק' מצה עשירה כידוע וכמו ב' מיני מצות הללו הי' גם אז בזמן יצי\"מ שהרי ודאי מצה שאכלו עם הפסח הי' שמור מן החמץ אך מצה השני' שלשו אחר חצות אחר שלא הספיק להחמיץ כו' ה\"ז כמו מצה עשירה שא\"צ שימור ומטעם שית' בעזר\"ה ואותה",[["389","5","<b>על מצות ומרורים יאכלוהו</b>: במדבר ט, יא."],["390","6","<b>ויאפו את הבצק אשר הוציאו ממצרים</b>: שמות יב, לט."],["391","7","<b>וישא העם את בצקו וגו'</b>: ראה שמות יב, לד."],["392","8","<b>דאכילת הפסח אינה אלא עד חצות</b>: פסחים קכ, ב. וש\"נ."],["393","9","<b>אך הנה האמת הוא דשני מיני מצות</b>: ראה ג\"כ אוה\"ת בא ע' שז."],["394","10","<b>בערב. . מצות</b>: בכת\"י ב וכת\"י ג ליתא."],["395","11","<b>ב' מיני מצה הא' מצה שצריכה שימור וכו'</b>: ראה פסחים לו, א. ובמפרשים שם. ירושל' שם פ\"ב ה\"ד."]]],[2101000084,"המדריגה במצה זו השני' שלא הספיק להחמיץ כו' ישנה ג\"כ במצה זו שאנו אוכלין לשם מצוה אעפ\"י שצריכה שימור מן החמץ מטעם שית' בעזר\"ה.\n<b>אך</b> תחלה יש להקדים ענין א' הידוע בפי' מארז\"ל דעד<sup data-n=\"396\">12</sup> שלא נבה\"ע הי' הוא ושמו בלבד פי' שמו הוא בחי' התגלות אור בלבד מן העצמות דהנה בחי' השפעה והמשכה שנמשך מא\"ס ב\"ה להוות העולמות אבי\"ע כו' אינה בחי' המשכה עצמי' מעצמותו ומהותו כלל וכלל אלא רק בבחי' זיו ואור בלבד כמשל זיו השמש<sup data-n=\"397\">13</sup> כידוע או כמשל אותיות המח' מן השכל שאינו אלא בחי' גילוי העצמות כידוע, ועיקר הענין הוא משום דאין התגלות אור וזיו פועל ועושה שום שינוי כלל וכלל בהעצמות עד\"מ זיו השמש איננו פועל שינוי כלל בעצם השמש וכן אותיות השכל בעצם השכל וגם שיפסיקו במסך ולא יתפשט האור יותר לא יעשה שינוי כלל בעצם השמש (וגם לא יעשה ויפעול שינוי כלל באור המאיר ג\"כ כי בעצם הזיו לא יהי' שינוי אם מאיר בי' חלונות או בפחות או בזכוכית אדומה או לבנה וגם שהאור בזכוכית אדומה אדום הוא ובלבינה לבן הוא זה השינוי אינו בעצם האור כלל רק הכלי שהיא הזכוכית מראה באור אותו הגוון כו' וכמ\"ש במ\"א) וכך למעלה כתיב בעצמות א\"ס ב\"ה אני<sup data-n=\"398\">14</sup> ה' לא שניתי פי' אני בעצמותי אינו פועל בבחי' גילוי אורו שום שינוי כלל וכלל (וגם לא באורו וזיוו כידוע בע\"ח דגם בחי' אא\"ס הנק' מל' דא\"ס למעלה מכל ההשתלשלו' דאבי\"ע ונוגע לכולם בשוה) ומזה הטעם נק' בחי' השפעה זאת בחי' שם עד\"מ שם האדם שאינו נוגע לעצמותו כלל כידוע ומבואר בכמה מקומות, וגם נק' השפעה זאת בשם מלך כי בחי' המלוכה ג\"כ אינו אלא ענין התגלות והתפשטות שם המלך על המדינה ולא מבחי' עצמותו כלל רק שנק' שם מלכותו עליהם כמבואר בכמה מקומות, וז\"ש יהללו<sup data-n=\"399\">15</sup> את שם הוי' שם דוקא, ומ\"ש כי הוא ציוה ונבראו ולא אמר ציוה ובראם כי נבראו משמע ממילא ומאליו הענין מורה על היות שאין ההמשכה מבחי' עצמות א\"ס כלל כנ\"ל רק בבחי' אור וזיו שנק' שם ומלכות כנ\"ל אבל פי' בראת משמע שעצמותו בראם ועד\"מ אדם שחושב בעיון על איזה דבר מה דגם שאינו מתפשט מעצמותו רק אותיות המח' שאינו אלא בחי' גילוי העצמות בלבד מ\"מ יוכל להיות גם מבחי' עצמותו במח' זו כאשר הוא מעיין בכל לבבו ושכלו וכו' עד שא\"א לו לחשוב דבר אחר בשעה זו א\"כ הרי כל עצמותו מתלבש במח' זו אבל לא כן הוא למעלה דגם שכל ההשתלשלות נמשך רק מבחי' אור וזיו שנק' אותיות מח' או אותיו' הדיבור מ\"מ לא נתלבש כלל מבחי' עצמות א\"ס באותו<sup data-n=\"400\">16</sup> מח' כמ\"ש כי<sup data-n=\"401\">17</sup> לא מחשבותי מחשבותיכם כו' וגם בחי' מח' אחת שעלה ברצה\"פ להאציל ולברוא כו' אין זה נוגע לעצמותו כלל וא\"כ הרי התהוות אצי' ובריאה כו' ממח' א' הנ\"ל באה מאליה וממילא כמו שאותיות מח' של אדם בלתי התלבשות עצמותו בהם באין ממילא כו' וכמו זיו השמש שמאיר ממילא וא\"א",[["396","12","<b>דעד שלא נבה\"ע הי' הוא ושמו בלבד</b>: פדר\"א פ\"ג. וראה אוה\"ת יתרו ע' תתלט."],["397","13","<b>וכן. . השמש</b>: בכת\"י ב וכת\"י ג ליתא."],["398","14","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."],["399","15","<b>יהללו את שם ה'</b>: תהלים קמח, יג."],["400","16","<b>באותו</b>: בכת\"י ב וכת\"י ג: באותיות."],["401","17","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח."]]]]});
